window.__D("text/torat-shmuel/c059",{"p":[[2001910515,"ראשון ואני<sup data-n=\"5596\">41</sup> אחרון<sup data-n=\"5595\">40</sup> כו' והוא בחי' ואמת הוי' לעולם<sup data-n=\"5597\">42</sup>, והנה כתי' פי' פתחה בחכ' ותורת חסד על לשונה<sup data-n=\"5598\">43</sup> ואמרז\"ל וכי יש תורה של חסד<sup data-n=\"5599\">44</sup> ותורה שאינה של חסד, אלא כשלומדים תורה לשמה פי' לשם התורה<sup data-n=\"5600\">45</sup> להמשיך המשכות אוא\"ס בתורה אז היא בחי' תורת חסד וכמ\"ש כי עם הוי' החסד<sup data-n=\"5601\">46</sup>, אבל כשאין לומדים תורה לשמה אז היא בחי' זאת דא גזר\"ת אורייתא בחי' גבורות<sup data-n=\"5602\">47</sup>, וזהו מי האיש החכם ויבין את זאת שהעיקר הוא מה שהתורה היא בבחי' זאת, ולא שלא למדו תורה כלל דלמה לא ידעו החכמים והנביאים אלא שלא ברכו בתורה, והתורה הי' בבחי' זאת, ונמצא לפ\"ז העונש הי' לו<sup data-n=\"5603\">*48</sup> מחמת זה שלא ברכו כו' אלא שהי' שארי עוונות חמורות אך אם הי' לומדים תורה לשמה הרי בכח התורה לחזור בתשובה אפי' על עבירות חמורות וכמארז\"ל ויתר הקב\"ה על ג' עבירות חמורות על ע\"ז וג\"ע וש\"ד ולא ויתר על מאסה של תורה<sup data-n=\"5604\">48</sup> דכשממשיכים המשכות אוא\"ס בתורה ה\"ז ממתיק הגבורות, אבל כשלא ברכו בתורה ה\"ה בבחי' זאת דא גזרת אורייתא דאי' דבחכ' יש בה קצת דין<sup data-n=\"5605\">49</sup> וחכ' היא [תורה דכתי' ותורת] חסד. והענין דכשנמשך מלבנון בחי' לובן העליון<sup data-n=\"5606\">50</sup> אז היא בחי' חסד, אך עצם התורה דאורייתא מחכ' נפקת הי' בחי' גבורות, וזהו וברך את לחמך להמשיך המשכות אוא\"ס בתורה.\n<b>ואת</b> מימיך היא בחי' תושבע\"פ<sup data-n=\"5607\">51</sup>, דהנה אמרז\"ל אכל ולא שתה אכילתו דם<sup data-n=\"5608\">52</sup>, דהנה מהמאכל נעשה דם ומתפשט בכל האברים, אך אכל ולא שתה אכילתו דם דפעולת השתי' הוא (שמצליל בל\"א) פירט פ„נ„נדער<sup data-n=\"5609\">53</sup> את הדם ומתפשט בכל האברים אבל בלא שתי' נעשה ממנו דם נקודה חדא ואינו מתפשט בכל האברים, וכמו\"כ יובן בתורה דאף שכל הדינים יש בתושב\"כ אבל הוא בקיצור וכמו תפילין דכתי' וקשרתם לאות על ידך והיו לטוטפות בין עיניך<sup data-n=\"5610\">54</sup> אבל פרטי<sup data-n=\"5611\">55</sup> ההלכות,",[["5596","41","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["5595","40","<b>ואמת . . אני ראשון ואני אחרון</b>: ב\"ר פפ\"א, ב. ראה גם יפ\"ת שם. סה\"מ תרכ\"ז ע' שטו."],["5597","42","<b>ואמת הוי' לעולם</b>: תהלים קיז, ב."],["5598","43","<b>פי' פתחה בחכ' ותורת חסד על לשונה</b>: משלי לא, כו."],["5599","44","<b>וכי יש תורה של חסד</b>: ראה סוכה מט, ב."],["5600","45","<b>לשמה פי' לשם התורה</b>: ראה פע\"ח שער הנהגת הלימוד. מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. לעיל הנחה ד\"ה אז ישיר ובהערה 100."],["5601","46","<b>כי עם הוי' החסד</b>: תהלים קל, ז."],["5602","47","<b>זאת . . בחי' גבורות</b>: ראה זהר חוקת קעט, ב. ראה גם מג\"א הל' תענית סו\"ס תק\"פ."],["5603","*48","<b>לו</b>: כ\"ה בגוכתי\"ק."],["5604","48","<b>ויתר הקב\"ה . . ולא ויתר . . תורה</b>: ראה ירושלמי חגיגה פ\"א, ה\"ז. פתיחתא דאיכ\"ר ב. הל' ת\"ת לאדה\"ז פ\"ד, ה\"ז."],["5605","49","<b>דבחכ' . . קצת דין</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370021\" data-slug=\"torah-or\" data-id=\"3901370021\">תו\"א בראשית ה, ד</a>. סה\"מ תר\"ם ח\"א ע' שז. וש\"נ. לעיל הנחה ד\"ה קדש ישראל לה' על יד הערה 105."],["5606","50","<b>מלבנון בחי' לובן העליון</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשפ. תקס\"ב ח\"א ע' פו. תקס\"ד ע' קעד."],["5607","51","<b>מימיך . . תושבע\"פ</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 54."],["5608","52","<b>אכל ולא שתה אכילתו דם</b>: שבת מא, א. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370348\" data-slug=\"torah-or\" data-id=\"3901370348\">תו\"א משפטים עח, ג</a>. מאמרי אדה\"א בראשית ע' קטו. שמות ח\"א ע' קפב. ויקרא ח\"א ע' קלט. סה\"מ תרל\"ג כאן ע' תלז ובהנסמן בהנ\"ל."],["5609","53","<b>(שמצליל בל\"א) פירט פאנאנדער</b>: אוצ\"ל: שמצליל (בל\"א פירט פאנאנדער)."],["5610","54","<b>וקשרתם . . לטוטפות בין עיניך</b>: ואתחנן ו, ח. ראה גם אגה\"ק סכ\"ט (קנ, ב). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550829\" data-slug=\"torat-chaim\" data-id=\"2300550829\">תו\"ח ויקהל ח\"ב תכד, ב</a> ובהערה 1329."],["5611","55","<b>אבל פרטי</b>: אוצ\"ל: אבל לא פרטי."]]],[2001910516,"ובתושבע\"פ מבואר הפרטים טט בכתפא שתים פת באפריקי שתים<sup data-n=\"5612\">56</sup> ורצועות צ\"ל שחורות<sup data-n=\"5613\">57</sup> הל\"מ מסיני, וכן ל\"ט אבות מלאכות דשבת<sup data-n=\"5614\">58</sup> נלמוד מדברים הדברים אלה הדברים<sup data-n=\"5615\">59</sup> ולכן אמרז\"ל גדול תלמוד<sup data-n=\"5616\">60</sup> שמביא לידי מעשה, אף שכולם ישנם בתושב\"כ אך אינו מבואר הפרטים ובתושבע\"פ מבואר הפרטים, ולכן נק' תושבע\"פ מים, (ע' משארז\"ל (חגיגה דט\"ו<sup data-n=\"5617\">61</sup> ע\"א) משען לחם<sup data-n=\"5618\">62</sup> אלו בעלי תלמוד וצ\"ע), ותושבע\"פ צריך ברכה בפ\"ע ואדרבה צריכה יותר לברכה מתושב\"כ, שהיא בחי' מים שמצמיחים כל מיני תענוג<sup data-n=\"5619\">63</sup>, וכן מעשה הוא בחי' צמיחה וכמ\"ש זורע צדקות<sup data-n=\"5620\">64</sup> וצדקה היא מעשה וכמ\"ש וצדקה תהי' לנו כי נשמור לעשות כל המצוה הזאת<sup data-n=\"5621\">65</sup>, וגדול תלמוד שמביא לידי מעשה לכן צריכה ברכה יותר מתושב\"כ, וביאור הענין הנה כתי' ושמתם ואמרז\"ל סם תם<sup data-n=\"5622\">66</sup>, וכתי' וזאת התורה אשר שם משה ואמרז\"ל למיימינים בה<sup data-n=\"5623\">67</sup> סמי דחייא למשמאילים בה סמא דמותא, דתושבע\"פ ירדה למטה לברר עה\"ד טו\"ר<sup data-n=\"5624\">68</sup>, ולכן למיימינים בה הוא סמא דחייא שנמשך מעץ החיים בעה\"ד אך למשמאילים בה שלומדים תורה להתגדל ולהתייהר ה\"ה מגבירים הרע כו'. וענין להתגדל ולהתייהר שייך בתושבע\"פ<sup data-n=\"5625\">69</sup> יותר מבתושב\"כ, דכל ענין תושב\"כ הוא ביטול וידבר ה' אל משה לאמר<sup data-n=\"5626\">70</sup>, ולבד זה בתושב\"כ אינו שייך כ\"כ להתגדל כו', אבל תושבע\"פ שייך בה להתגדל כו' ח\"ו לכן צריכה ברכה יותר. וזהו דבברכת התורה יש ג' ברכות<sup data-n=\"5627\">71</sup> ברכה אחת על תושב\"כ ושני ברכות על תושבע\"פ<sup data-n=\"5628\">72</sup>. וזהו וברך את לחמך ואת מימיך, לחמך הוא בחי' תושב\"כ ומימיך הוא בחי' תושבע\"פ.\n<b>והסירותי</b> מחלה מקרבך, מחלה הוא היצה\"ר וכמ\"ש במדרש דחולה הוא היצה\"ר<sup data-n=\"5629\">73</sup> כמו\"כ מחלה כו', והוא היפך מלחם שמחבר הנשמה עם",[["5612","56","<b>טט בכתפא . . שתים</b>: ראה מנחות לד, ריש ע\"ב. רש\"י בא יג, טז. ואתחנן ו, ח. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091049\" data-slug=\"likkutei-sichot\" data-id=\"1300091049\">לקו\"ש ואתחנן כרך ט ע' 49</a> ואילך."],["5613","57","<b>ורצועות צ\"ל שחורות</b>: שבת כח, ב. מנחות לה, א. שו\"ע אדה\"ז הל' תפילין סל\"ב, ס\"ס. סע\"ה. סל\"ג, ס\"ד-ס\"ה."],["5614","58","<b>ל\"ט אבות מלאכות דשבת</b>: ראה שבת עג, א."],["5615","59","<b>מדברים הדברים אלה הדברים</b>: ויקהל לה, א. שבת צז, ריש ע\"ב וברש\"י שם. וש\"נ. סה\"מ תרל\"ח ע' קמט. וש\"נ."],["5616","60","<b>גדול תלמוד</b>: ראה קדושין מ, ב."],["5617","61","<b>דט\"ו</b>: אוצ\"ל: די\"ד."],["5618","62","<b>משען לחם</b>: ישעי' ג, א."],["5619","63","<b>מים שמצמיחים כל מיני תענוג</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ\"א</a>."],["5620","64","<b>זורע צדקות</b>: נוסח ברכת יוצר."],["5621","65","<b>וצדקה תהי' לנו . . הזאת</b>: ואתחנן ו, כה [ושם: את כל]."],["5622","66","<b>ושמתם . . סם תם</b>: עקב יא, יח. קדושין ל, ב."],["5623","67","<b>למיימינים בה</b>: ראה שבת פח, ב."],["5624","68","<b>דתושבע\"פ . . עה\"ד טו\"ר</b>: ראה אגה\"ק סכ\"ו. סה\"מ תרל\"ח ע' ר ואילך."],["5625","69","<b>להתגדל ולהתייהר שייך בתושבע\"פ</b>: ראה גם סה\"מ תרל\"ג כאן ע' תלח ובשולי היריעה שם."],["5626","70","<b>וידבר ה' אל משה לאמר</b>: וארא ו, י. כט. בא יג, א. ועוד."],["5627","71","<b>דבברכת התורה יש ג' ברכות</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר סמ\"ו, ס\"א. סמ\"ז, ס\"ד-ס\"ה."],["5628","72","<b>ברכה . . ושני ברכות על תושבע\"פ</b>: ראה אבודרהם ברכות השחר ד\"ה הערב נא ע' מד. וראה גם רבינו יונה לברכות יא, ב ד\"ה והא דרב המנונא."],["5629","73","<b>דחולה הוא היצה\"ר</b>: ראה ויק\"ר פט\"ז, ח. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301790094\" data-slug=\"likkutei-sichot\" data-id=\"1301790094\">לקו\"ש מצורע כרך לז ע' 43</a> ובהערה 16. חגה\"פ כרך יב ע' 156."]]],[2001910517,"הגוף והמחלה מפריד כו', לחם הוא המשכת אוא\"ס [בעולם] והיצה\"ר הוא מפריד כמ\"ש כי אם עונותיכם היו מבדילים ביניכם ובין אלקיכם<sup data-n=\"5630\">74</sup>. וביאור הענין צ\"ל תחילה מ\"ש הן האדם הי' כאחד ממנו<sup data-n=\"5631\">75</sup> ואי' במדרש כיחידו ש\"ע ועוד דיעה יש כגבריאל<sup data-n=\"5632\">76</sup>, והנה מ\"ש כיחידו ש\"ע ניחא אבל מ\"ש כגבריאל צ\"ל מ\"ש גבריאל משארי מלאכים, והענין דהנה כתי' וייצר הוי' אלקים את האדם עפר מן האדמה<sup data-n=\"5633\">77</sup> ואמרז\"ל בתרין יצרין ביצ\"ט וביצה\"ר<sup data-n=\"5634\">78</sup>, ולכאו' נראה דאדה\"ר קודם החטא לא הי' לו יצה\"ר כלל דכתי' ויניחהו בג\"ע לעבדה ולשמרה<sup data-n=\"5635\">79</sup> ואיך שייך בג\"ע עם יצה\"ר, אך א\"א לומר כן דלעבדה הוא רמ\"ח מ\"ע ולשמרה שס\"ה מל\"ת<sup data-n=\"5636\">80</sup>, ועיקרם לברר הנה\"ב ולכן כשמלאכים ביקשו תורה<sup data-n=\"5637\">81</sup> א\"ל כלום יצה\"ר יש בכם<sup data-n=\"5638\">82</sup> וא\"כ אם לא הי' לו יצה\"ר איך קיים מצות, ועוד דהרי דרשו רז\"ל בתרין יצרין, וצ\"ל דיצה\"ר קודם החטא הי' תגבורת האהבה, וזהו וייצר הוי' אלקי' ב' שמות אלו הוי' ואלקים הם מקור יצ\"ט ויצה\"ר<sup data-n=\"5639\">83</sup>, יצ\"ט שרשו משם הוי' ויצה\"ר משם אלקים וקודם החטא היו שניהם מאורות הגדולים<sup data-n=\"5640\">84</sup> דגם ש' אלקים הוא בחי' גדול דכתי' גדול הוי' ומהולל מאד<sup data-n=\"5641\">85</sup> אימתי הוא גדול כשהוא בעיר אלקינו<sup data-n=\"5642\">86</sup> ומאחר שמגדל את שם הוי' מכ\"ש ששם אלקים עצמו הוא גדול וזהו\"ע חסד וגבורה<sup data-n=\"5643\">87</sup> שרש הנה\"א מבחי' חסד ושרש הנה\"ב מבחי' גבורה<sup data-n=\"5644\">88</sup> ובשרשו הוא בחי' גבורות קדושות תגבורת<sup data-n=\"5645\">89</sup>, וכמו גבורות גשמים<sup data-n=\"5646\">90</sup> שהולכים טיפים טיפים, והוא תכלית הטוב והחסד דאל\"כ הי' מבול, וכן הנפש המחי'",[["5630","74","<b>כי אם עונותיכם . . ובין אלקיכם</b>: ישעי' נט, ב [ושם: לבין אלקיכם — ראה גם לעיל הנחה ד\"ה הקבצו ושמעו על יד הערה 118]."],["5631","75","<b>הן האדם . . ממנו</b>: בראשית ג, כב. ראה אוה\"ת בראשית כרך ג ע' 1160 ואילך."],["5632","76","<b>במדרש כיחידו ש\"ע . . כגבריאל</b>: ב\"ר פכ\"א, ה."],["5633","77","<b>וייצר . . מן האדמה</b>: בראשית ב, ז."],["5634","78","<b>וייצר . . ביצ\"ט וביצה\"ר</b>: ראה תרגום יוב\"ע שם. ברכות סא, א. זהר תזריע מו, ב. אוה\"ת בראשית כרך ג ע' 1044 ואילך."],["5635","79","<b>ויניחהו בג\"ע לעבדה ולשמרה</b>: בראשית ב, טו."],["5636","80","<b>דלעבדה הוא רמ\"ח . . שס\"ה מל\"ת</b>: ראה זהר בראשית כז, א. תרומה קסה, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' שצט־ בראשית ע' עג־ קונטרסים ע' שי."],["5637","81","<b>כשמלאכים ביקשו תורה</b>: שבת פח, ב."],["5638","82","<b>כלום יצה\"ר יש בכם</b>: ראה שם פט, א. (לעיל בחלק המאמרים) מאמר ד\"ה שלש רגלים תחוג לי בסופו. מאמרי אדה\"א ויקרא ח\"ב ע' תסט בהערה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560193\" data-slug=\"or-hatorah-hb\" data-id=\"8316560193\">אוה\"ת בראשית כרך ג ע' תקסג</a>. סה\"מ תר\"ם ח\"ב ע' תרד."],["5639","83","<b>הוי' ואלקים . . יצ\"ט ויצה\"ר</b>: ראה גם אוה\"ת בראשית שם. ישעי' ע' רכט ס\"ו. תהלים ע' תלט ס\"ג (בשם המאו\"א אות יו\"ד, סכ\"ב). ביאוה\"ז — להצ\"צ — כרך ב ע' תתקה [ושם: ומשמע]. סה\"מ תר\"ם ח\"א ע' קח. וש\"נ."],["5640","84","<b>הוי' . . אלקים . . מאורות הגדולים</b>: בראשית א, טז. זהר בראשית כ, א."],["5641","85","<b>גדול הוי' ומהולל מאד</b>: תהלים מח, ב."],["5642","86","<b>אימתי הוא גדול כשהוא בעיר אלקינו</b>: ראה זהר פקודי רלה, א. ויקרא ה, א. מאמרי אדה\"א נ\"ך ע' פ. וש\"נ. סה\"מ תרכ\"ז ס\"ע ר. וש\"נ."],["5643","87","<b>הוי' . . אלקים . . חסד וגבורה</b>: ראה גם מאמרי אדה\"א בראשית ע' קעג. דברים ח\"ג ע' תתקפא. נ\"ך ע' קכג ובהנסמן בהנ\"ל."],["5644","88","<b>הנה\"א . . חסד. . הנה\"ב . . גבורה</b>: ראה רמ\"ז תזריע מו, ב ד\"ה וייצר."],["5645","89","<b>גבורות . . תגבורת</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370039\" data-slug=\"torah-or\" data-id=\"3901370039\">תו\"א נח ט, ג</a>. סה\"מ תרכ\"ז ס\"ע רמט. וש\"נ. לקמן הנחה ד\"ה והמים להם חומה על יד הערה 105 ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410173\" data-slug=\"likkutei-sichot\" data-id=\"1301410173\">לקו\"ש תולדות כרך ל ע' 108</a>. וש\"נ."],["5646","90","<b>גבורות גשמים</b>: תענית ב, א. ראה גם לקו\"ת ואתחנן יג, ג. סה\"מ תר\"ם ח\"א ע' פא. וש\"נ."]]],[2001910518,"את האדם הוא בחי' גבורות, אלא שהו\"ע תגבורת וכמו\"כ היצה\"ר ששרשו מבחי' גבורות קדושות<sup data-n=\"5647\">91</sup> וזהו שא' במד' כגבריאל שהוא מלאך מגבו'<sup data-n=\"5648\">92</sup> קדושות, אך קודם החטא הי' בבחי' תגבורת האהבה וע\"י החטא נפל ונעשה רע, דמבחי' חסד כשנופל אינו נעשה רע כ\"כ, אבל מבחי' גבו' כשנופל נעשה רע [גמור] ונק' מחלה שמפריד כו'. אך כשמבררים הנה\"ב הרי אמרז\"ל טוב<sup data-n=\"5650\">94</sup> זה מלאך טוב, מאד זה מלאך רע<sup data-n=\"5649\">93</sup> דיצה\"ר לאחר הבירור הוא למעלה מיצ\"ט, וכמשל המרקחת שהוא מצנון שהוא דבר מר וכשמטגנין אותו בדבש<sup data-n=\"5651\">95</sup> ה\"ה משובח יותר מהדבש וכמו\"כ היצה\"ר לאחר הבירור כו'. וזהו והסירותי מחלה מקרבך גם ש' אלקים יהי' בחי' מאור הגדול, ועז\"נ והסירותי שקאי על שלישי המדבר שכ' הרמב\"ן<sup data-n=\"5652\">96</sup> שכ' בדרך שלישי המדבר וע\"ז קאי והסירותי, דמ\"ש וברך את לחמך ואת מימיך קאי על שם הוי' שמברך דשם הוי' יברך לחמך כו' אבל לברר הנה\"ב הוא מבחי' שלישי המדבר כו'.",[["5647","91","<b>היצה\"ר ששרשו . . גבורות קדושות</b>: ראה גם אוה\"ת בראשית כרך ג ע' 1044. סה\"מ תרל\"ח ע' קצו. וש\"נ."],["5648","92","<b>כגבריאל . . מגבו'</b>: ראה זהר ויחי רלה, ב. סה\"מ תרל\"ח ע' קטז. וש\"נ."],["5650","94","<b>טוב . . מאד זה מלאך רע</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 95."],["5649","93","<b>חסד כשנופל . . גבו' . . רע </b> [גמור]<b></b>: ראה גם לקמן הנחה ד\"ה והמים להם חומה ובהערה 162."],["5651","95","<b>המרקחת . . מצנון . . בדבש</b>: מובא בכ\"מ ומהם: מאמרי אדה\"ז על פרשיות התורה ח\"א ע' ע. תקס\"ג ח\"ב ע' תשדמ. סה\"מ תרל\"ג כאן ע' תמ. תר\"ם ח\"א ע' לג. וש\"נ."],["5652","96","<b>שכ' הרמב\"ן</b>: ראה פתיחת הרמב\"ן על התורה. לעיל הנחה ד\"ה ועבדתם את ה\"א הערה 9."]]],[2001910519,"<h3>ר' נהוראי אומר</h3>\n<b>ש\"פ תצוה</b>\n<b>ר'</b> נהוראי אומר<sup data-n=\"5653\">1</sup> מניח אני כל האומנות שבעולם ואיני מלמד את בני אלא תורה<sup data-n=\"5654\">2</sup>, וצ\"ל מה שייך תורה לאומנות, ועוד צ\"ל מפני מה מניח כל האומנות שבעולם הרי אי' שמעי' אומר אהוב את המלאכה<sup data-n=\"5655\">3</sup> משמע שצ\"ל ביתרון וארז\"ל כל הנהנה מיגיע כפו<sup data-n=\"5656\">4</sup> יותר מיראת שמים דגבי י\"ש כתי' אשרי האיש ירא אלקים<sup data-n=\"5657\">5</sup>, וגבי יגיע כפו כתי' יגיע כפיך כו' תאכל אשריך וטוב לך<sup data-n=\"5658\">6</sup>, הרי כתי' וטוב לך ג\"כ, וא\"כ מפני מה א' מניח כו', והנה צלה\"ק תחילה מה דשימ\"ב נק' בשם מלאכה וכמ\"ש ויכל אלקים<sup data-n=\"5659\">7</sup>",[["5653","1","<b>ר' נהוראי אומר</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ. ונרשמו רק שורות אחדות."],["5654","2","<b>ר' נהוראי אומר . . אלא תורה</b>: קדושין פ\"ד, מי\"ד (פב, א)."],["5655","3","<b>שמעי' אומר אהוב את המלאכה</b>: אבות פ\"א, מ\"י."],["5656","4","<b>כל הנהנה מיגיע כפו</b>: ראה ברכות ח, סע\"א."],["5657","5","<b>אשרי האיש ירא אלקים</b>: תהלים קיב, א [ושם: איש ירא את ה']."],["5658","6","<b>יגיע כפיך . . וטוב לך</b>: תהלים קכח, ב."],["5659","7","<b>ויכל אלקים</b>: בראשית ב, ב."]]],[2001910520,"<h3>ראה קראתי</h3>\n<b>ש\"פ תשא</b>\n<b>ראה</b> קראתי בשם<sup data-n=\"5660\">1</sup> בצלאל בן אורי בן חור למטה יהודה<sup data-n=\"5661\">2</sup> ואמלא אותו רוח אלקים בחכמה ובתבונה ובדעת ובכל מלאכה<sup data-n=\"5662\">3</sup> לחשב מחשבות<sup data-n=\"5663\">4</sup> כו' ואני הנה נתתי אתו את אהליאב בן אחיסמך למטה דן<sup data-n=\"5664\">5</sup>, וצ\"ל מ\"ש רא\"ה קראתי כו' ואי' במד' כשעלה משה למרום<sup data-n=\"5665\">6</sup> הראה לו הקב\"ה כלי המשכן כו' סבר שהוא יעשה אותם כו' הראה לו בספרו דאדה\"ר דבצלאל יעשה אותם, וזהו ראה כו', וצ\"ל ענין שהראה לו בספרו דאדה\"ר.\n<b>והנה</b> אמרז\"ל גדול מקדש שניתן בין שתי אותיות<sup data-n=\"5666\">7</sup> דכתי' מכון לשבתך פעלת הוי' מקדש א\"ד כוננו ידיך<sup data-n=\"5667\">8</sup>. ועל ענין הדעת אמרז\"ל גדולה דיעה<sup data-n=\"5668\">9</sup> שניתנה בין שתי אותיות דכתי' כי אל דיעות הוי'<sup data-n=\"5669\">10</sup>, וצ\"ל מה שגבי מקדש כתי' תחלה שם הוי' ואח\"כ שם א\"ד ובדעת כתי' ש' אל וכתי'<sup data-n=\"5670\">11</sup> תחילה ואח\"כ שם הוי', ואמרז\"ל על בצלאל יודע הי'<sup data-n=\"5671\">12</sup> לצרף אותיות שנבראו בהם שמים וארץ, וצ\"ל מה צריכין זה לבנין המקדש, ואי' בספרים<sup data-n=\"5672\">13</sup> מפני שכל מה שנברא בשימ\"ב<sup data-n=\"5673\">14</sup> הי' במקדש<sup data-n=\"5674\">15</sup>, ביום א' נבראו שמים<sup data-n=\"5675\">16</sup> שהוא יריעות שהי' במקדש וכמ\"ש נוטה שמים כיריעה<sup data-n=\"5676\">17</sup>, יהי אור הם ארון ומנורה<sup data-n=\"5677\">18</sup>, בשני יהי רקיע<sup data-n=\"5678\">19</sup> במקדש והבדילה הפרוכת לכם בין המקדש<sup data-n=\"5680\">21</sup> ובין קדה\"ק<sup data-n=\"5679\">20</sup>, בשלישי יקוו המים<sup data-n=\"5681\">22</sup> במקדש הי' הכיור<sup data-n=\"5682\">23</sup>, ולכן הי' צריך לידע אותיות שנבראו בהם שו\"א, ומה שנק' בצלאל אמרו רז\"ל שהוא ע\"ש חכמתו<sup data-n=\"5683\">24</sup> דהקב\"ה א' למשה עשה לי משכן וארון וכלים, ומשה א' לבצלאל עשה ארון וכלים ומשכן א\"ל בצלאל כלום אדם בונה בית ואח\"כ מכניס הכלים, כלים שאעשה להיכן",[["5660","1","<b>ראה קראתי בשם</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ."],["5661","2","<b>ראה קראתי בשם . . למטה יהודה</b>: תשא לא, ב."],["5662","3","<b>ואמלא אותו . . ובכל מלאכה</b>: שם לא, ג."],["5663","4","<b>לחשוב מחשבות</b>: תשא שם, ד."],["5664","5","<b>ואני הנה . . למטה דן</b>: שם לא, ו."],["5665","6","<b>ואי' במד' כשעלה משה למרום</b>: ראה שמו\"ר מ, ב."],["5666","7","<b>גדול מקדש שניתן בין שתי אותיות</b>: ברכות לג, א. סנהדרין צב, א."],["5667","8","<b>מכון לשבתך . . כוננו ידיך</b>: בשלח טו, יז."],["5668","9","<b>גדולה דיעה</b>: ברכות וסנהדרין שם."],["5669","10","<b>כי אל דיעות הוי'</b>: שמו\"א ב, ג."],["5670","11","<b>וכתי'</b>: אולי תיבה זו היא מיותרת."],["5671","12","<b>בצלאל יודע הי'</b>: ראה ברכות נה, א."],["5672","13","<b>ואי' בספרים</b>: ראה לקמן בפנים שמציין לאלשיך ולהה\"מ נ\"ע (או\"ת). וש\"נ."],["5673","14","<b>שכל מה שנברא בשימ\"ב</b>: ראה במדב\"ר פי\"ב, יג. תנחומא פקודי ב. מדרש תהלים וילקוט המכירי לתהלים פכ\"ו. רבעה\"ת פקודי לח, כה."],["5674","15","<b>במקדש</b>: הכוונה למשכן."],["5675","16","<b>ביום א' נבראו שמים</b>: בראשית א, א ואילך."],["5676","17","<b>יריעות . . נוטה שמים כיריעה</b>: תרומה כו, ז. תהלים קד, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380406\" data-slug=\"likkutei-torah\" data-id=\"4001380406\">לקו\"ת נשא כד, ג</a>."],["5677","18","<b>יהי אור הם ארון ומנורה</b>: בראשית א, ג. בהנסמן לעיל הערה 14 כ\"ז ליתא. וכ\"ז הוא הוספת כ\"ק אדמו\"ר מהר\"ש."],["5678","19","<b>יהי רקיע</b>: בראשית א, ו."],["5680","21","<b>המקדש</b>: שם: הקדש."],["5679","20","<b>והבדילה הפרוכת . . קדה\"ק</b>: תרומה כו, לג."],["5681","22","<b>יקוו המים</b>: בראשית א, ט."],["5682","23","<b>כיור</b>: תשא ל, יח."],["5683","24","<b>בצלאל . . ע\"ש חכמתו</b>: ראה ברכות נה, א. ראה גם לקמן הנחה ד\"ה וידעת היום בסופה פיסקא ועפ\"ז יובן."]]],[2001910521,"אכניסם שמא כך א\"ל הקב\"ה עשה לי משכן וארון וכלים א\"ל בצל אל היית וידעת, וצ\"ל מפני היפך<sup data-n=\"5684\">*25</sup> משה את הסדר כמ\"ש הקב\"ה.\n<b>והענין</b> הנה כתי' ועשו לי מקדש<sup data-n=\"5685\">25</sup> ושכנתי בתוכם, בתוכו לא נא' אלא בתוכם בתוך כאו\"א, דבזמן המקדש האיר בכ\"א בהתגלות, ואף משחרב המקדש יש בכאו\"א בחי' מקדש, ובזה מתורץ דלכאו' הרי אמרז\"ל כ\"מ שנא' לי<sup data-n=\"5686\">26</sup> אינו זז משם לא בעוה\"ז ולא בעוה\"ב, דגם עכשיו יש בחי' זו בכאו\"א, ובעבודה הוא מ\"ש ואהבת את ה' אלקיך בכל לבבך<sup data-n=\"5687\">27</sup>, הב' הוא ב' השימוש שבכל הלב<sup data-n=\"5688\">28</sup> בחלל הימיני ובחלל השמאלי יהי' הוי' אלקיך, ואהבת שרש דאהבה אבה<sup data-n=\"5689\">29</sup> ל' רצון שיהי' לו רצון אחד לאלקות, ובמ\"א מבואר דואהבת הוא ל' הבטחה<sup data-n=\"5690\">30</sup> שמבטיח שיהי' ה' אלקיך, וכאן מבואר דהב' הוא ב' השימוש ואהבת הוא ל' רצון, וזהו מצוה דליחדו וכמ\"ש וידעת היום<sup data-n=\"5691\">31</sup> והשבת אל לבבך כי הוי' הוא אלקים בשמים ובארץ מתחת אין עוד, וזהו מ\"ש בנוסח קדושה דמוסף דשבת ויו\"ט המיחדים שמו ערב ובקר בכ\"י תמיד פעמים באהבה שמע אומרים שמע ישראל<sup data-n=\"5692\">32</sup> כו' דכשם דואהבת צריך התבוננות<sup data-n=\"5693\">33</sup> תחילה בפסוק א' שמע ישראל כו' כמו\"כ מצוה ליחדו צ\"ל תחילה וידעת<sup data-n=\"5694\">34</sup>.\n<b>והענין</b> דהנה כתי' מה יתרון לאדם בכל עמלו שיעשה תחת השמש<sup data-n=\"5695\">35</sup>, דהנה שמש ומגן הוי' אלקים<sup data-n=\"5696\">36</sup> כמו שהמגן ומכסה<sup data-n=\"5697\">37</sup> ומסתיר על אור השמש דאור השמש כמו שהוא אין העולם יכול לקבל, ולע\"ל דאמרז\"ל שקב\"ה מוציא חמה מנרתקה<sup data-n=\"5698\">38</sup> הוא מפני שיזדכך העולם ויוכל לקבל אבל עכשיו אין העולם יכול לקבל אור השמש כמו שהוא, והמגן הוא מכסה ומסתיר על אור השמש. וכמו\"כ יובן",[["5684","*25","<b>מפני היפך</b>: אוצ\"ל: מפני מה היפך."],["5685","25","<b>ועשו לי מקדש</b>: תרומה כה, ח. ראה אלשיך שם. (לעיל בחלק המאמרים) בהמאמר כאן הערה 21."],["5686","26","<b>כ\"מ שנא' לי</b>: ראה ויק\"ר פ\"ב, ב. מדרש שמואל פי\"ט. ספרי בהעלותך יא, טז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380346\" data-slug=\"likkutei-torah\" data-id=\"4001380346\">לקו\"ת במדבר ט, ג</a>."],["5687","27","<b>ואהבת . . בכל לבבך</b>: ואתחנן ו, ה."],["5688","28","<b>בכל לבבך . . שבכל הלב</b>: ראה גם לקו\"ת שמע\"צ פח, ג. סה\"מ תר\"ם ח\"א ע' קפד. וש\"נ."],["5689","29","<b>ואהבת שרש דאהבה אבה</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 25."],["5690","30","<b>דואהבת הוא ל' הבטחה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370388\" data-slug=\"torah-or\" data-id=\"3901370388\">תו\"א תשא פו, ג</a>. סה\"מ תרכ\"ז ע' עד-עה. תרכ\"ט ע' שכב. תרל\"ב ח\"א ע' צה וע' קלט. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301430272\" data-slug=\"likkutei-sichot\" data-id=\"1301430272\">לקו\"ש</a> ר\"ח סיון כרך לג ע' 216 בהערה."],["5691","31","<b>מצוה דליחדו . . וידעת היום</b>: ואתחנן ד, לט. ראה לקמן הערה 57."],["5692","32","<b>מצוה דליחדו . . שמע ישראל</b>: ואתחנן ו, ד. ראה רמב\"ם הל' יסוה\"ת פ\"א, ה\"ז. סהמ\"צ להרמב\"ם מ\"ע ב. ולהצ\"צ נט, ב ואילך. אוה\"ת בראשית כרך ז ע' 2328 ואילך."],["5693","33","<b>דואהבת צריך התבוננות</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 30."],["5694","34","<b>ליחדו צ\"ל תחילה וידעת</b>: ראה לקו\"ת ואתחנן ד, ד."],["5695","35","<b>מה יתרון . . שיעשה . . השמש</b>: קהלת א, ג [ושם: שיעמול — וכ\"ה לקמן בפנים, קרוב לסיום פיסקא זו]."],["5696","36","<b>שמש ומגן הוי' אלקים</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370102\" data-slug=\"torah-or\" data-id=\"3901370102\">תו\"א ויצא כא, ד</a>. תו\"ח ח\"ש קכח, סע\"ב ואילך. ויצא קסז, ג ואילך. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך."],["5697","37","<b>ומכסה</b>: אוצ\"ל: מכסה."],["5698","38","<b>ולע\"ל . . מוציא חמה מנרתקה</b>: ראה נדרים ח, ב. ראה גם שער היחוה\"א רפ\"ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670107\" data-slug=\"torat-chaim\" data-id=\"2300670107\">תו\"ח בראשית לה, א</a> ובהערה 12. שמות ח\"א לט, ב. וש\"נ. מאמרי אדה\"א הנחות תקע\"ז ע' שי."]]],[2001910522,"למעלה, אף דעיקר ההתהוות הוא מצד שם הוי' דהוי' ל' מהווה<sup data-n=\"5699\">39</sup> וכתי' יהללו שם הוי' כי הוא צוה ונבראו<sup data-n=\"5700\">40</sup>, מ\"מ כתי' בראשית ברא אלקים<sup data-n=\"5701\">41</sup> ול\"ב פעמים ש' אלקים כתי' במע\"ב<sup data-n=\"5702\">42</sup> עד לאחר השבת, גבי יצירת אדם ובע\"ח כתי' וייצר הוי' אלקים<sup data-n=\"5703\">43</sup>, אבל במע\"ב אפי' במאמר נעשה אדם<sup data-n=\"5704\">44</sup> כתי' ש' אלקים לבד. והענין דמצד שם הוי' לא הי' העולמות כמו שהם עתה, אך שם אלקים הוא מדת הצמצום<sup data-n=\"5705\">45</sup>, דהנה שם אלקים הוא בחי' אותיות<sup data-n=\"5706\">46</sup>, ואותיות הם מעלימים ומסתירים על האור<sup data-n=\"5707\">47</sup>, ויובן מאותיות הכתב, דתושב\"כ העיקר הם אותיות<sup data-n=\"5708\">48</sup> וצריך שלא יחסר שום אות והכל יש בתושב\"כ וכל הסודות וכל הרמזים ישנם בתושב\"כ, ומן האותיות אינו מובן כלל הרי שהאותיות מסתירים על האור, ואפי' תושבע\"פ שהעיקר אור ההשכלה ולא האותיות, מ\"מ הרי המשנה היא פסק הלכה לבד ואינו מובן הטעם, מכ\"ז מובן שהאותיות מסתירים על אור ההשכלה, וכמו\"כ יובן בשם אלקים דכתיב גדול ה' ומהולל מאד בעיר אלקינו<sup data-n=\"5709\">49</sup>, עיר אלקינו הוא כללות עולם הדיבור וכמ\"ש בס\"י שתי אבנים<sup data-n=\"5710\">50</sup> בונות שתי בתים שלשה אבנים בונות ששה, פי' ב' אותיות י\"ל<sup data-n=\"5711\">51</sup> ב' צירופי' כמו אב בא ומשלשה כו' וקיבוץ מבתים הרבה נק' עיר אלקינו והוא כללות עולם הדיבור, והאותיות הם מסתירים ומעלימים על אור הוי', ולכן אם הי' הבריאה מצד שם הוי' היו העולמות בטלים במציאות כמו עולמות העליונים יהללו שם הוי' כי הוא צוה ונבראו בדרך מאיליו וממילא דשם הוי' הוא הי' הוה ויהי' כאחד<sup data-n=\"5712\">52</sup>, אבל כדי שיהי' ברא כח הפועל בנפעל<sup data-n=\"5713\">53</sup> הוא משם אלקי' דוקא, וזהו שמש ומגן הוי' אלקים כמו שהמגן מכסה ומסתיר על אור השמש כמו\"כ שם אלקי' מכסה ומסתיר על אור ה', וזהו מה יתרון לאדם בכל עמלו שיעמול תחת השמש, דמי שמעמיל ומייגע עצמו רק בענין הבריאה איך שהוא משם אלקים מה יתרון בזה ה\"ז לא טוב וה\"ז כמו",[["5699","39","<b>דהוי' ל' מהווה</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"ט. שער עצמות וכלים שער ד, ספ\"י. סה\"מ תר\"ם ח\"א ע' קצח. וש\"נ."],["5700","40","<b>יהללו שם . . צוה ונבראו</b>: תהלים קמח, ה [ושם: את שם]. ראה גם לקמן בסמוך בפנים. לקמן הנחה ד\"ה וידבר כו' קדושים תהיו ובהערה 29. (לעיל בחלק המאמרים) בהמאמר כאן הערה 38."],["5701","41","<b>בראשית ברא אלקים</b>: בראשית א, א. ראה גם לעיל הנחה ד\"ה ועבדתם את ה' אלקיכם ובהערה 37."],["5702","42","<b>ול\"ב פעמים ש' אלקים כתי' במע\"ב</b>: נמנו בפרטיות בתקז\"ח קיב, ג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכה. וש\"נ. שעה\"י קלב, א ובהערה 3."],["5703","43","<b>וייצר הוי' אלקים</b>: בראשית ב, ז. יט."],["5704","44","<b>נעשה אדם</b>: בראשית א, כו."],["5705","45","<b>שם אלקים . . הצמצום</b>: ראה שער היחוה\"א רפ\"ו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540695\" data-slug=\"torat-chaim\" data-id=\"2300540695\">תו\"ח שמות ח\"א לד, ד</a>. וש\"נ."],["5706","46","<b>שם אלקים . . אותיות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370311\" data-slug=\"torah-or\" data-id=\"3901370311\">תו\"א יתרו סט, ד</a>."],["5707","47","<b>ואותיות . . ומסתירים על האור</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380143\" data-slug=\"likkutei-torah\" data-id=\"4001380143\">לקו\"ת צו טז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380199\" data-slug=\"likkutei-torah\" data-id=\"4001380199\">אחרי כח, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380345\" data-slug=\"likkutei-torah\" data-id=\"4001380345\">במדבר ט, ב</a>."],["5708","48","<b>דתושב\"כ . . אותיות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381103\" data-slug=\"likkutei-torah\" data-id=\"4001381103\">לקו\"ת ברכה צד, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540171\" data-slug=\"torat-chaim\" data-id=\"2300540171\">תו\"ח וארא ח\"א ע, א</a> ואילך ובהנסמן שם ובריש המאמר שם."],["5709","49","<b>גדול הוי' . . בעיר אלקינו</b>: תהלים מח, ב. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה הוא אהרן ומשה פיסקא והענין הוא."],["5710","50","<b>כמ\"ש בס\"י שתי אבנים</b>: ראה שם פ\"ד, מי\"ב."],["5711","51","<b>י\"ל</b>: יכולים לעשות. יכול להיות."],["5712","52","<b>הוי' . . הי' הוה ויהי' כאחד</b>: ראה שער היחוד והאמונה פ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680292\" data-slug=\"torat-chaim\" data-id=\"2300680292\">תו\"ח מקץ ריט, ד</a> הערה 62."],["5713","53","<b>כח הפועל בנפעל</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a>: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת) סוף ש\"ג."]]],[2001910523,"שאמר פרעה לא ידעתי את הוי'<sup data-n=\"5714\">54</sup> דמש' אלקים ידע דיוסף א\"ל האלקים יענה את שלום פרעה<sup data-n=\"5715\">55</sup>, וכשבא משה וא\"ל משם הוי' הי' הוה יהי' כאחד אמר לא ידעתי את הוי', מי הוי' אשר אשמע בקולו<sup data-n=\"5716\">56</sup>, אך העבודה היא שידע דהוי' ואלקים כולא חד<sup data-n=\"5717\">57</sup> וכמ\"ש אני ראשון ואני אחרון<sup data-n=\"5718\">58</sup> ומבלעדי אין אלקים שהכל מבחי' הוי', ומה שנראה העולם למציאות יש ודבר נפרד הוא רק לעינינו אבל באמת הוא מבחי' הוי'.\n<b>וכמו\"כ</b> יובן ענין המקדש שהוא לחבר שם הוי' בשם אלקי'<sup data-n=\"5719\">59</sup>, הגם שבברה\"ע נמשך ג\"כ משם הוי' בש' אלקים, אך הרי שם אלקים מסתיר על שם הוי' אבל במקדש הי' גילוי אלקות וכמארז\"ל ע\"פ שלש פעמים בשנה<sup data-n=\"5720\">60</sup> יראה כל זכורך כשם שבא לרָאות<sup data-n=\"5721\">61</sup> כך בא לראות מה לראות בשתי עיניו של מקום הם יחו\"ע ויחו\"ת<sup data-n=\"5722\">62</sup> ד\"ע וד\"ת כו', וא' ע\"פ ושאבתם מים בששון<sup data-n=\"5723\">63</sup> שמשם היו שואבים רוה\"ק<sup data-n=\"5724\">64</sup> ולכאורה מה שייך רוה\"ק, אך לפי מה שפרש\"י כאן על מ\"ש גבי בצלאל ובדעת, רוה\"ק, ניחא מה שהיו שואבים משם רוה\"ק, וזהו משארז\"ל יודע הי' בצלאל לצרף אותיות שנבראו בהם שו\"א ופי' האלשיך כדי להמשיך משו\"א למקדש<sup data-n=\"5725\">65</sup>, והמגיד נ\"ע פי' שהמקדש למעלה משו\"א<sup data-n=\"5726\">66</sup>, וכן מובן ממשארז\"ל גדולים מעשה צדיקים<sup data-n=\"5727\">67</sup> ממעשה שו\"א דבמעשה שו\"א כתי' אף ידי יסדה ארץ<sup data-n=\"5728\">68</sup> וימיני טפחה שמים, וגבי מעשה צדיקים כתי' מקדש אד' כוננו ידיך, אף דבמעשה שו\"א כתי' ג\"כ ב' ידות, הרי ידי הוא דבר בפ\"ע וימיני הוא דבר בפ\"ע, ידי יד כהה<sup data-n=\"5729\">69</sup> וכתי' נטה ימינו וברא שמים<sup data-n=\"5730\">70</sup> נטה שמאלו וברא ארץ אבל במקדש כתי' ב' ידות, הרי המקדש למעלה משו\"א, ובעבודה הוא מצוה דליחדו להמשיך משם הוי' בשם אלקים.",[["5714","54","<b>לא ידעתי את הוי'</b>: שמות ה, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380228\" data-slug=\"likkutei-torah\" data-id=\"4001380228\">לקו\"ת אמור לה, ג</a>."],["5715","55","<b>האלקים . . שלום פרעה</b>: מקץ מא, טז [ושם: אלקים]."],["5716","56","<b>מי הוי' . . בקולו</b>: שמות ה, ב."],["5717","57","<b>דהוי' ואלקים כולא חד</b>: ראה זהר בהקדמה יב, א. (לעיל בחלק המאמרים) בהמאמר כאן הערה 51."],["5718","58","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370176\" data-slug=\"torah-or\" data-id=\"3901370176\">תו\"א מקץ לח, רע\"ד</a>."],["5719","59","<b>המקדש שהוא . . בש' אלקי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380393\" data-slug=\"likkutei-torah\" data-id=\"4001380393\">לקו\"ת נשא כא, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470098\" data-slug=\"or-hatorah-hb\" data-id=\"8316470098\">אוה\"ת בשלח ע' תקסד</a>. ויקהל ריש ע' ב'ריא. במדבר ע' כה. עקב ע' תקיט."],["5720","60","<b>שלש פעמים בשנה</b>: (לעיל בחלק המאמרים) בהמאמר כאן פ\"ג מציין: ”תשא לד, כג\". והוא ע\"פ פרש\"י חגיגה ב, א ד\"ה יראה יראה (את פני). אבל לפי פרש\"י שבע\"י שם (אל פני) הכוונה להכתוב דמשפטים כג, יז."],["5721","61","<b>כשם שבא לראות</b>: ראה חגיגה ב, א. תוד\"ה יראה."],["5722","62","<b>יחו\"ע ויחו\"ת</b>: זהר בהקדמה יב, א."],["5723","63","<b>ושאבתם מים בששון</b>: ישעי' יב, ג."],["5724","64","<b>שמשם היו שואבים רוה\"ק</b>: ירושלמי סוכה פ\"ה, ה\"א. ב\"ר פ\"ע, ח."],["5725","65","<b>ופי' האלשיך . . משו\"א למקדש</b>: ויקהל לה, י (ד\"ה ואחר אומרו). לו, ח."],["5726","66","<b>והמגיד נ\"ע . . למעלה משו\"א</b>: ראה אור תורה ר\"פ תצוה [הובא באוה\"ת תשא כרך ח' ע' ג'קג]. בראשית ד\"ה איתא במדרש [ד, ב במהדורת קה\"ת]. לקו\"א סקכ\"ו."],["5727","67","<b>גדולים מעשה צדיקים</b>: ראה כתובות ה, א."],["5728","68","<b>אף ידי יסדה ארץ</b>: ישעי' מח, יג."],["5729","69","<b>ידי יד כהה</b>: ראה מנחות לו, סע\"ב."],["5730","70","<b>נטה ימינו וברא שמים</b>: ראה פדר\"א פי\"ח. לעיל הנחה ד\"ה ועבדתם את ה\"א ובהערה 52."]]],[2001910524,"<b>ועפ\"ז</b> מ\"ש<sup data-n=\"5731\">71</sup> ולחשב מחשבות ולכאו' צ\"ל מה שייך זה כו', והענין דהנה נת'<sup data-n=\"5732\">72</sup> דשם אלקים הוא בחי' דיבור ושם הוי' אף שהוא הי' הוה ויהי' כא' מ\"מ ה\"ז שם וכמ\"ש אני הוי' הוא שמי<sup data-n=\"5733\">73</sup> ה\"ז אותיות המח'<sup data-n=\"5734\">74</sup> דבאדם שלמטה אין למעלה מאותיות המח'<sup data-n=\"5735\">75</sup>, ועוי\"ל דהנה שכל ומח' הם מקיפים לגבי מדות ודיבור דהמח' מקיף את הדיבור, ומח' הגם שהוא לבוש הנפש מ\"מ הוא לבוש הפנימי<sup data-n=\"5736\">76</sup> שמאחד עם העצמות הנפש דדיבור יכול להחזיק א\"ע שלא לדבר אבל בלא מח' א\"א<sup data-n=\"5737\">77</sup> שהוא בהכרח, הרי מחשבה למעלה מדיבור, לכן בצלאל שהי' בבחי' מח' הי' יכול להמשיך שם הוי' בשם אלקים, וזהו מ\"ש בפ' ויקהל ראו קרא הוי' בשם<sup data-n=\"5738\">78</sup> פי' שבחי' הוי' נמשך בשם אד'. וזהו גדול מקדש שניתן בין שתי אותיות וגדולה דעה שניתנה בין שתי אותיות וכמ\"ש כי אל דעות<sup data-n=\"5739\">79</sup> הוי'<sup data-n=\"5740\">80</sup>, דהנה יש ד\"ת וד\"ע, ד\"ע הוא איך שלמעלה היש וכל מה שלמטה הוא אין פי' שלמעלה הוא יש האמיתי וכולא קמי' כלא חשיב<sup data-n=\"5741\">81</sup>, וד\"ת הוא שלמטה הוא מציאות היש שניכר ומורגש ולמעלה אינו ניכר ומורגש ה\"ז אין, וצריכים שיומשך ד\"ע בד\"ת שגם בד\"ת יהי' מורגש בחי' ד\"ע, ובכדי שיומשך ד\"ע בד\"ת הוא דוקא משם אל תקונא קדמאה מי\"ג ת\"ד<sup data-n=\"5742\">82</sup>, וע\"ד מ\"ש בזהר<sup data-n=\"5743\">83</sup> תלת עלמין נפקין<sup data-n=\"5744\">84</sup> מתקונא קדמאה ופי' הרמ\"ז שהם ג' עולמות בי\"ע<sup data-n=\"5745\">85</sup> ולכאו' איך שייך שג' עולמות אלו יומשכו מתיקון הראשן די\"ג ת\"ד שהם לפני האצי', אך היא הנותנת שכדי שיומשך למטה מטה הוא מפני ששרשו למעלה יותר<sup data-n=\"5746\">86</sup> וכמו\"כ יובן כאן שמבחי' מי אל כמוך שהוא תקון הראשון<sup data-n=\"5747\">87</sup> נמשך שיומשך ד\"ע בד\"ת, וכמ\"ש המגביהי לשבת המשפילי לראות<sup data-n=\"5748\">88</sup> בשמים ובארץ. ועפ\"ז יובן מה שגבי מקדש כתי' תחילה ש' הוי' ואח\"כ שם אד' ובדעת כתי' תחילה שם אל דכדי שיומשך מד\"ע לד\"ת הוא משם אל, זהו בצל אל היית<sup data-n=\"5749\">89</sup> כו', וזהו מ\"ש בספרי'",[["5731","71","<b>ועפ\"ז מ\"ש</b>: אוצ\"ל: ועפ\"ז יובן מ\"ש."],["5732","72","<b>דהנה נת'</b>: לעיל בפיסקא והענין דהנה כתי'."],["5733","73","<b>אני הוי' הוא שמי</b>: ישעי' מב, ח."],["5734","74","<b>הוי' . . אותיות המח'</b>: ראה גם אוה\"ת וארא ע' קצו ואילך."],["5735","75","<b>אין למעלה מאותיות המח'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310025\" data-slug=\"tanya\" data-id=\"3401310025\">תניא פ\"כ</a> ופכ\"א. שהיחוה\"א פ\"ח. אגה\"ק סי\"ט בסופה."],["5736","76","<b>ומח' . . לבוש הפנימי</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. ש\"ש סה, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקטז. אתהלך לאזניא ע' ריז."],["5737","77","<b>בלא מח' א\"א</b>: ראה לקו\"ת ש\"ש סה, ד."],["5738","78","<b>בפ' ויקהל ראו קרא הוי' בשם</b>: לה, ל."],["5739","79","<b>כי אל דעות</b>: ראה להבא בסמוך <a class=\"ft-cite\" href=\"#/read/torah-or/3901370307\" data-slug=\"torah-or\" data-id=\"3901370307\">תו\"א יתרו סח, ד</a>."],["5740","80","<b>כי אל דעות הוי'</b>: שמו\"א ב, ג. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670564\" data-slug=\"torat-chaim\" data-id=\"2300670564\">תו\"ח בראשית יח, ג</a> ובהערה 11."],["5741","81","<b>וכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["5742","82","<b>אל תקונא קדמאה מי\"ג ת\"ד</b>: ראה זהר אד\"ר נשא קלא, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041347\" data-slug=\"likkutei-sichot\" data-id=\"1300041347\">לקו\"ש אלול כרך ד ע' 1348</a> ואילך."],["5743","83","<b>בזהר</b>: ראה אד\"ר נשא קלב, א."],["5744","84","<b>נפקין</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 106."],["5745","85","<b>ופי' הרמ\"ז . . בי\"ע</b>: ראה גם קול ברמה לאד\"ר שם (ע' מה)."],["5746","86","<b>שכדי שיומשך . . ששרשו למעלה יותר</b>: ראה ש\"א שער הפורים נח, א. סה, א. סה\"מ תרל\"ח ע' תב. וש\"נ."],["5747","87","<b>מי אל . . תקון הראשון</b>: מיכה ז, יח."],["5748","88","<b>המגביהי לשבת המשפילי לראות</b>: תהלים קיג, ה. ו."],["5749","89","<b>בצל אל היית</b>: ברכות נה, א. הובא לעיל בפנים סוף פיסקא א."]]],[2001910525,"דשם אל הוא המסייע את בצלאל<sup data-n=\"5750\">90</sup> שכדי שיומשך משם הוי' לשם אד' הוא ע\"י שם אל, וזהו בצלאל כו' למטה יהודה ואהליאב כו' למטה דן, דיהודה יש בו שם הוי'<sup data-n=\"5751\">91</sup>, ודן הוא בחי' שם א\"ד<sup data-n=\"5752\">92</sup> והוא ההמשכה משם הוי' בשם א\"ד. ועפ\"ז יובן מ\"ש במד' שהראה לו בספרו דאדם קדמאה, הוא כמ\"ש הדורות<sup data-n=\"5753\">93</sup> מראש<sup data-n=\"5754\">94</sup> הוא בחי' מח' הקדומה שגם שם בצלאל הוא הבונה את המקדש, ובעבודה היא מצוה דליחדו.",[["5750","90","<b>דשם אל . . בצלאל</b>: ראה מק\"מ לזהר בהקדמה ב, סע\"א."],["5751","91","<b>דיהודה . . שם הוי'</b>: ראה סוטה י, ב (ובמהרש\"א שם)."],["5752","92","<b>ודן . . שם א\"ד</b>: ראה הגהות מהרח\"ז לזהר בלק קצז, א."],["5753","93","<b>כמ\"ש הדורות</b>: אולי צ\"ל: כמ\"ש קורא הדורות."],["5754","94","<b>קורא הדורות מראש</b>: ישעי' מא, ד. ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתיא. ע' תתפח. קונטרסים ע' תלב."]]],[2001910526,"<h3>כי תשא</h3>\n<b>ש\"פ ויקהל פ\"ש</b>\n<b>כי</b> תשא<sup data-n=\"5755\">1</sup> את ראש בנ\"י לפקודיהם ונתנו איש כפר נפשו לה' בפקד אותם<sup data-n=\"5756\">2</sup> זה יתנו כל העבר על הפקודים מחצית השקל בשקל הקדש עשרים גרה השקל מחצית השקל תרומה לה'<sup data-n=\"5757\">3</sup>, וצ\"ל והלא המצוה היא רק מחצית השקל שהם עשר גרה מהו התועלת במה שמספר דעשרים גרה השקל. והענין דהנה כתי' וייצר הוי' אלקים את האדם<sup data-n=\"5758\">4</sup> ואמרז\"ל בתרין יצרין<sup data-n=\"5759\">5</sup> יצ\"ט ויצה\"ר והם נה\"א ונה\"ב, והנה\"א מצד עצמו א\"צ תיקון<sup data-n=\"5760\">6</sup> רק שירד למטה לברר הנה\"ב, והנה הנה\"א והנה\"ב יש בכ\"א עשר כחות<sup data-n=\"5761\">7</sup>, וזהו שאמר עשרים גרה השקל שצ\"ל עשרים גרה היינו שיתהפך הנה\"ב לגמרי לטוב, ואמרז\"ל טוב זה יצ\"ט מאד זה יצה\"ר<sup data-n=\"5762\">8</sup>, דיצה\"ר לאחר הבירור הוא טוב מאד, אך זהו עבודת הצדיקים, ומה שמבקשים הוא עשר גרה שלכה\"פ יהיה אתכפי' וסוף כל סוף יבוא לאתהפכא, וזהו שכ' ברע\"מ דמחצית השקל הוא עבודת הבינונים<sup data-n=\"5763\">9</sup> דהיינו שהוא עדיין באמצע הבירור, ולא שהוא מבורר לגמרי כמו הצדיקים דאתהפכא חשוכא לנהורא<sup data-n=\"5764\">10</sup> לגמרי אבל הבינוני הוא שמברר הרע.",[["5755","1","<b>כי תשא</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ."],["5756","2","<b>כי תשא את ראש . . בפקד אותם</b>: תשא ל, יב."],["5757","3","<b>זה יתנו . . תרומה לה'</b>: תשא שם, יג."],["5758","4","<b>וייצר הוי' אלקים את האדם</b>: בראשית ב, ז. בהבא בסמוך ראה אוה\"ת תשא ע' א'תתקז ס\"ג."],["5759","5","<b>וייצר . . בתרין יצרין</b>: ראה זהר תזריע מו, ב. ברכות סא, א . תרגום יוב\"ע בראשית שם. אוה\"ת בראשית כרך ג ע' 1044 ואילך."],["5760","6","<b>והנה\"א . . א\"צ תיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>). לקמן הנחה ד\"ה וידעת היום על יד הערה 29. מאמרי אדה\"א בראשית ע' עד. וש\"נ. קונטרסים ע' שעח. וש\"נ. שע\"ת קמא, ב."],["5761","7","<b>הנה\"א והנה\"ב . . עשר כחות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא פ\"ג</a>. פ\"ו."],["5762","8","<b>טוב . . מאד זה יצה\"ר</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ובירך את לחמך ובהערה 95."],["5763","9","<b>ברע\"מ דמחצית השקל . . הבינונים</b>: זהר תרומה קנח, ב."],["5764","10","<b>דאתהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א. סה\"מ תרל\"ח ע' קנב. וש\"נ."]]],[2001910527,"<b>והענין</b> דהנה כל משפטי התורה הם רק לברר הנה\"ב וכמו ואלה המשפטים אשר תשים לפניהם<sup data-n=\"5765\">11</sup> הם לברר הנה\"ב וכמ\"ש על כל דבר פשע<sup data-n=\"5766\">12</sup> על שור על חמור על שה על שלמה כו', על כל דבר פשע פי' אפי' מי שיש לו פשעים מ\"מ אין לך דבר שעומד בפני התשובה<sup data-n=\"5767\">13</sup>, וכ\"ז בא מהנה\"ב וזהו על שור שרש הנה\"ב מפני שור<sup data-n=\"5768\">14</sup> שבמרכבה, רק כמו שהוא במרכבה ה\"ה בהתלהבות והתלהטות באלקות שהוא מה שנתברר אך מה שנפל הרי י\"ל<sup data-n=\"5769\">15</sup> ההיפך וכמו שור נגח<sup data-n=\"5770\">16</sup>, שופך דם האדם<sup data-n=\"5771\">17</sup>, והו\"ע הכעס כעס שיש בו מעשה כל הכועס<sup data-n=\"5772\">18</sup> כו', והוא ג\"כ התלהטות הדמים שכועס על המנגד דכשרוצה באיזה דבר שהרצון הוא מהנה\"ב והמנגדו כועס עליו.\n<b>על</b> חמור הנה אמרז\"ל חמרא אפי' בתקופת תמוז קרירא לי'<sup data-n=\"5773\">19</sup> פי' אפי' בתקופת תמוז שאז תוקף החום שהשמש זורח בתוקף<sup data-n=\"5774\">20</sup> ומ\"מ קרירא לי', וכמו\"כ בעבודה אף בענין<sup data-n=\"5775\">*21</sup> שמש ומגן הוי' אלקים<sup data-n=\"5776\">21</sup> והוי' הוא אלקים<sup data-n=\"5777\">22</sup> הי' צ\"ל ואהבת את הוי' אלקיך<sup data-n=\"5778\">23</sup> שיהי' לו אהבה ורצון שהוי' יהי' אלקיך אלוקה שלך<sup data-n=\"5779\">24</sup> ומ\"מ אינו מתפעל כלל מזה. ועוי\"ל ענין החמור הוא כמ\"ש אשר בשר חמורים בשרם וזרמת סוסים<sup data-n=\"5780\">25</sup> כו'.\n<b>על</b> שה הוא מ\"ש שה פזורה ישראל<sup data-n=\"5781\">26</sup>. וזהו שטען המן ישנו עם אחד<sup data-n=\"5782\">27</sup> מפוזר ומפורד בין העמים, פי' עם אחד כמ\"ש ומי כעמך כישראל<sup data-n=\"5783\">28</sup> גוי אחד בארץ שגם בארץ יהי' בחי' אחד<sup data-n=\"5784\">29</sup> והיינו כמ\"ש ואספת דגנך<sup data-n=\"5785\">30</sup> כו' שמאסף כל הדברים",[["5765","11","<b>ואלה המשפטים . . לפניהם</b>: משפטים כא, א."],["5766","12","<b>על כל דבר פשע</b>: משפטים כב, ח. ראה גם בהבא להלן (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 8."],["5767","13","<b>אין לך דבר שעומד בפני התשובה</b>: ראה תניא פכ\"ה. אגה\"ת רפ\"ד ובמ\"מ הגהות והע\"ק לשם. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061066\" data-slug=\"likkutei-sichot\" data-id=\"1300061066\">לקו\"ש בא כרך ו ע' 66</a> הערה 54."],["5768","14","<b>שרש הנה\"ב מפני שור</b>: ראה סידור שער האלול רל, א. ש\"א יז, א הערה 11. סה\"מ תר\"ם ח\"ב ע' תקפ. וש\"נ. לקמן הנחה ד\"ה וידעת היום על יד הערה 10."],["5769","15","<b>י\"ל</b>: יכול להיות."],["5770","16","<b>שור נגח</b>: משפטים כא, לו. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380085\" data-slug=\"likkutei-torah\" data-id=\"4001380085\">לקו\"ת ויקרא ב, ד</a>."],["5771","17","<b>שופך דם האדם</b>: נח ט, ו."],["5772","18","<b>כל הכועס</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 12."],["5773","19","<b>חמרא . . קרירא לי'</b>: שבת נג, א. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שלה. מארז\"ל ע' נט. אוה\"ת שמע\"צ ע' א'תתטז. סה\"מ תר\"ם ח\"א ע' שצח. וש\"נ."],["5774","20","<b>שהשמש זורח בתוקף</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181319\" data-slug=\"likkutei-sichot\" data-id=\"1300181319\">לקו\"ש</a> יב-יג תמוז כרך יח ע' 310 ואילך."],["5775","*21","<b>אף בענין</b>: כ\"ה בגוכתי\"ק."],["5776","21","<b>שמש ומגן הוי' אלקים</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370102\" data-slug=\"torah-or\" data-id=\"3901370102\">תו\"א ויצא כא, ד</a>. תו\"ח ח\"ש קכח, סע\"ב ואילך. ויצא קסז, ג ואילך. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך. לעיל הנחה ד\"ה ראה קראתי בשם על יד הערה 35 ואילך."],["5777","22","<b>והוי' הוא אלקים</b>: תהלים ק, ג. וכ\"ה גם לקמן — ראה שם הערה 52."],["5778","23","<b>ואהבת את הוי' אלקיך</b>: ואתחנן ו, ה."],["5779","24","<b>אלקיך אלוקה שלך</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370368\" data-slug=\"torah-or\" data-id=\"3901370368\">תו\"א תצוה פב, רע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381297\" data-slug=\"likkutei-torah\" data-id=\"4001381297\">לקו\"ת שה\"ש מב, ב</a>."],["5780","25","<b>אשר בשר . . סוסים</b>: יחזקאל כג, כ."],["5781","26","<b>שה פזורה ישראל</b>: ירמי' נ, יז."],["5782","27","<b>ישנו עם אחד</b>: אסתר ג, ח."],["5783","28","<b>ומי כעמך כישראל</b>: שמו\"ב ז, כג."],["5784","29","<b>שגם בארץ . . אחד</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370130\" data-slug=\"torah-or\" data-id=\"3901370130\">תו\"א וישב כז, סע\"ד</a>. (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 21."],["5785","30","<b>ואספת דגנך</b>: עקב יא, יד. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה במשנה וכו' ר' נהוראי אומר ספ\"ב. וש\"נ."]]],[2001910528,"גשמים לאלקות, והוא ע\"י שאמרז\"ל עשה תורתך קבע<sup data-n=\"5786\">31</sup> ומלאכתך עראי, ואין הפי' קבע ועראי<sup data-n=\"5787\">32</sup> בשהיות זמן אלא שהעיקר קביעות יהי' תורה וכל העסק יהי' כדי שיוכל לעסוק בתורה ותפלה ועי\"ז ואספת דגנך כו', וזהו עם אחד בארץ, ואף בזה מצא הבע\"ד מקום לקטרג שהוא מפוזר ומפורד בין העמים היינו רבות המח' הטורדות ומבלבלות ומעכבים על מ\"ש ואגודתו על ארץ יסדה<sup data-n=\"5788\">33</sup> שהוא אגודה אבל הרבות מח' מעכבות את זה, וזהו על שה.\n<b>על</b> שלמה כמ\"ש וריח שלמותיך כריח הלבנון<sup data-n=\"5789\">34</sup>, ריחא דלבושייכא<sup data-n=\"5790\">35</sup>, והוא בחי' ריח דמעשה המצות ריח בגדיו<sup data-n=\"5791\">36</sup>, ובלעו\"ז יש ג\"כ בגד בוגדים<sup data-n=\"5792\">37</sup> לבושים צואים.\n<b>על</b> כל אבידה פי' על ידי כל הנ\"ל י\"ל שיאבד הניצוץ האלקי לגמרי, עד שיאמר כי הוא זה שיכול להיות כ\"כ עד שיאמר כי הוא זה, פי' דהנה כתי' שמים חשך לאור ואור לחשך<sup data-n=\"5793\">38</sup>, הוא, הוא חשך, וזה, הוא אור וגילוי, והוא קאי על הנה\"ב וכמ\"ש הוא הי' גבור ציד<sup data-n=\"5794\">39</sup>. והנה המרגלים אמרו כי חזק הוא ממנו<sup data-n=\"5795\">40</sup> קאי על היצה\"ר<sup data-n=\"5796\">41</sup>, ורז\"ל אמרו כביכול אין בעה\"ב<sup data-n=\"5797\">42</sup> יכול להוציא את כליו, ובעה\"ב הוא אדון העולם<sup data-n=\"5798\">43</sup>, הענין דעולם התיקון הוא שם<sup data-n=\"5800\">45</sup> מ\"ה<sup data-n=\"5799\">44</sup> ועולם התהו הוא שם ס\"ג<sup data-n=\"5801\">46</sup> והנה\"ב שהוא משם<sup data-n=\"5805\">50</sup> ב\"ן<sup data-n=\"5804\">49</sup> שרשו<sup data-n=\"5806\">51</sup> משם ס\"ג<sup data-n=\"5802\">47</sup> ולכן נק' זקן<sup data-n=\"5803\">48</sup>, וזהו כי חזק הוא ממנו, אבל באמת אינו כן דהוי' הוא אלקים<sup data-n=\"5807\">52</sup> ועד שלא נברא העולם הי' הוא",[["5786","31","<b>עשה תורתך קבע</b>: רמב\"ם הל' ת\"ת פ\"ג, ה\"ז. ראה גם לעיל הנחה ד\"ה הקבצו ושמעו בנ\"י ובהערה 111."],["5787","32","<b>הפי' קבע ועראי</b>: ראה גם לעיל בהנחה שם ובהערה 112."],["5788","33","<b>ואגודתו על ארץ יסדה</b>: עמוס ט, ו."],["5789","34","<b>וריח שלמותיך כריח הלבנון</b>: שה\"ש ד, יא [ושם: לבנון — ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 26]."],["5790","35","<b>ריחא דלבושייכו</b>: זהר ינוקא בלק קפו, א. ראה מאמרי אה\"ז הקצרים ע' שצט ואילך. מאמרי אדה\"א דרושי חתונה ח\"א ע' קה ואילך. וש\"נ."],["5791","36","<b>ריח בגדיו</b>: תולדות כז, כז."],["5792","37","<b>בגד בוגדים</b>: ישעי' כד, טז [ושם: ובגד]."],["5793","38","<b>שמים חשך לאור ואור לחשך</b>: ישעי' ה, כ."],["5794","39","<b>הוא הי' גבור ציד</b>: נח י, ט."],["5795","40","<b>כי חזק הוא ממנו</b>: שלח יג, לא."],["5796","41","<b>קאי על היצה\"ר</b>: ראה ערכי הכנויים — לבעל סדה\"ד — מערכת הוא."],["5797","42","<b>כביכול אין בעה\"ב</b>: ראה סוטה לה, א."],["5798","43","<b>ובעה\"ב הוא אדון העולם</b>: רש\"י סוטה שם ד\"ה בעל הבית."],["5800","45","<b>שם מ\"ה</b>: ראה זהר בהקדמה ד, א ובדרך אמת שם. הנסמן במאמרי אדה\"א נ\"ך ע' עא."],["5799","44","<b>דעולם התיקון הוא שם מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"א ואילך."],["5801","46","<b>ועולם התהו הוא שם ס\"ג</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670152\" data-slug=\"torat-chaim\" data-id=\"2300670152\">תו\"ח בראשית ט, א</a> ובהערה 2."],["5805","50","<b>משם ב\"ן</b>: מובא כמ\"פ בע\"ח ופע\"ח וכו'. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה [נקדישך] וביאור הענין ובהערה 54."],["5804","49","<b><a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380231\" data-slug=\"likkutei-torah\" data-id=\"4001380231\">והנה\"ב שהוא משם ב</a>\"ן</b>: ראה גם לקו\"ת אמור לו, ב. לעיל שם על יד הערה 36."],["5806","51","<b>ב\"ן שרשו משם ס\"ג</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. שער אנ\"ך שי\"ט, פ\"ז."],["5802","47","<b>שם ס\"ג</b>: ראה זהר רע\"מ פינחס רמו, ב."],["5803","48","<b>והנה\"ב . . נק' זקן</b>: ראה גם מק\"מ לזהר וישב קעט, ריש ע\"ב. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 38."],["5807","52","<b>דהוי' הוא אלקים</b>: תהלים ק, ג. וכ\"ה גם לעיל על יד הערה 22. אבל ראה (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 40 ששם הובא הכתוב: כי הוי' הוא האלקים — ואתחנן ד, לה. לט."]]],[2001910529,"ושמו בלבד<sup data-n=\"5808\">53</sup> והו\"א ר\"ת הוא ושמו אחד<sup data-n=\"5809\">54</sup>, אך ע\"י שיאמר כי הוא זה ששמים חושך לאור ואור לחשך עי\"ז הוא מ\"ש ואנכי הסתר אסתיר פני ביום ההוא<sup data-n=\"5810\">55</sup>, ועל ידי תשובה נמשך בחי' ואמר ביום ההוא<sup data-n=\"5811\">56</sup> הנה אלקינו זה.\n<b>עד</b> אלקים יבא דבר שניהם זה קאי על תשובה, פי' שניהם דבתשובה יש ב' דברים<sup data-n=\"5812\">57</sup> עקירת הרצון ווידוי דברים, ועד אלקים יבא דבר שניהם פי' שיבא עד אלקים כמ\"ש שובה ישראל עד הוי' אלקיך<sup data-n=\"5813\">58</sup>, הוי' הוא האלקים<sup data-n=\"5814\">59</sup> שהוי' כאלקים יחשב.\n<b>את</b> אשר ירשיעון אלקים ואי' במדר' זה משה<sup data-n=\"5815\">60</sup> דכתי' ואלה המשפטים<sup data-n=\"5816\">61</sup> אשר תשים לפניהם<sup data-n=\"5817\">62</sup> שקאי על משה<sup data-n=\"5818\">63</sup> וכתי' כי יהי' להם דבר בא אלי<sup data-n=\"5819\">64</sup>.\n<b>ישלם</b> שנים לרעהו זה הקב\"ה<sup data-n=\"5820\">65</sup>, ישלם שנים היינו תשו\"ע ותשו\"ת<sup data-n=\"5821\">66</sup> והו\"ע תורה ותפלה, ממעמקים ב' עומקים<sup data-n=\"5822\">67</sup>, והי' רגיל לקרות דף א' קורא ב' דפים ואי' בתדב\"א<sup data-n=\"5823\">68</sup> שזה תשובה, והוא מלמטלמ\"ע וכמו\"כ שנים מלמעלמ\"ט הם ב' שמות הוי' שקודם י\"ג מדה\"ר<sup data-n=\"5824\">69</sup>, וכתי' שלום שלום לרחוק ולקרוב<sup data-n=\"5825\">70</sup> לרחוק שנעשה קרוב<sup data-n=\"5826\">71</sup> במקום שבע\"ת עומדים<sup data-n=\"5827\">72</sup> צ\"ג אינם יכולים לעמוד, [וב' בחי' שלום<sup data-n=\"5828\">73</sup> הם] י\"ה ו\"ה, הרי משפטי התורה הם בירור דנה\"ב.",[["5808","53","<b>ועד שלא . . ושמו בלבד</b>: ראה פדר\"א פ\"ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540053\" data-slug=\"torat-chaim\" data-id=\"2300540053\">תו\"ח וארא ח\"א נג, ב</a> הערה 6."],["5809","54","<b>והו\"א ר\"ת . . אחד</b>: של\"ה בית ה' ד, א."],["5810","55","<b>ואנכי הסתר . . ביום ההוא</b>: וילך לא, יח."],["5811","56","<b>ואמר ביום ההוא</b>: ישעי' כה , ט."],["5812","57","<b>דבר שניהם . . ב' דברים</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 46. אגה\"ת פ\"א ובליקוט פירושים לשם. ש\"א ח, א ובהנסמן במ\"מ לשם. אוה\"ת ש\"ש כרך ו ע' ב'תקה ואילך."],["5813","58","<b>שובה ישראל עד הוי' אלקיך</b>: הושע יד, ב."],["5814","59","<b>הוי' הוא האלקים</b>: מלכים-א יח, לט. ראה לק\"ת ש\"ש סד, ג ואילך."],["5815","60","<b>אשר ירשיעון אלקים . . משה</b>: ראה במדב\"ר פ\"ט, מז בסופו."],["5816","61","<b>דכתי' ואלה המשפטים</b>: במדרש שם לא הובא כתוב זה. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 49."],["5817","62","<b>ואלה המשפטים אשר תשים לפניהם</b>: משפטים כא, א."],["5818","63","<b>אשר תשים . . שקאי על משה</b>: ראה גם לעיל שם ובהערה 52."],["5819","64","<b>כי יהי' . . בא אלי</b>: יתרו יח, טז."],["5820","65","<b>לרעהו זה הקב\"ה</b>: ראה במדב\"ר שם."],["5821","66","<b>תשו\"ע ותשו\"ת</b>: זהר רע\"מ נשא קכג, א."],["5822","67","<b>ממעמקים ב' עומקים</b>: תהלים קל, א. ראה זהר בשלח סג, ב. אחרי ע, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380902\" data-slug=\"likkutei-torah\" data-id=\"4001380902\">לקו\"ת נצבים מה, ד</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תקצ. וש\"נ. קונטרסים ס\"ע שט ואילך. וש\"נ."],["5823","68","<b>והי' רגיל . . ואי' בתדב\"א</b>: נסמן (לעיל בחלק המאמרים) בהמאמר כאן הערה 57."],["5824","69","<b>ב' שמות . . י\"ג מדה\"ר</b>: תשא לד, ו."],["5825","70","<b>שלום שלום לרחוק ולקרוב</b>: ישעי' נז, יט."],["5826","71","<b>לרחוק שנעשה קרוב</b>: ראה ברכות לד, ב. אוה\"ת ישעי' כרך א ע' רעג."],["5827","72","<b>במקום שבע\"ת עומדים</b>: ראה ברכות שם. לקו\"ש נצבים כרך יד ע' 361 וע' 363. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a>. וש\"נ. סה\"מ מלוקט ד' ס\"ע יח."],["5828","73","<b>וב' בחי' שלום</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380667\" data-slug=\"likkutei-torah\" data-id=\"4001380667\">לקו\"ת מטות פו, ב</a>."]]],[2001910530,"<b>וכמו\"כ</b> ענין מחצית השקל הוא בירור דנה\"ב, וזהו העשיר לא ירבה<sup data-n=\"5829\">74</sup> והדל לא ימעיט, אין עשיר אלא בדעת<sup data-n=\"5830\">75</sup> ואין עני אלא בדעת, העשיר שהוא בחי' אתהפכא לגמרי בחי' טוב מאד לא ירבה מצד הבירור דנה\"ב הוא רק עשר (פי' אף שהעשיר הוא אתהפכא והוא בחי' עשרים גרה כנ\"ל, אך גוף מצות מחצית השקל הוא לברר הנה\"ב דכל משפטי התורה כו' כנ\"ל ומצד בירור נה\"ב הוא עשר גרה היינו עשר כחות דנה\"ב וזהו העשיר לא ירבה על עשר כו'), ואפי' העני בדעת לא ימעט מעשר שיהי' אתכפי' וסוף כל סוף בא לאתהפכא.\n<b>והנה</b> כ\"ז בנה\"ב וצ\"ל העלי' דנה\"א, דאף דמצד עצמו א\"צ תיקון מ\"מ ע\"י שמברר הנה\"ב ה\"ה מתעלה עי\"ז, וזהו מ\"ש כי תשא את ראש בנ\"י שמתעלה לשרש שרשו הראשון. והענין דהנה אי' בזהר בג' דברים נתקשה משה<sup data-n=\"5831\">76</sup> במנורה ושקלים והחודש, וזהו מרומז בשמו מש\"ה<sup data-n=\"5832\">77</sup> מנורה שקלים החוד\"ש, ומה שנתקשה בשקלים הוא דישראל הם למעלה ממנין וענין השקלים ה\"ז מנין, והראה לו הקב\"ה מטבע של אש<sup data-n=\"5834\">79</sup> ופי' הרמ\"ז<sup data-n=\"5833\">78</sup> שבה הי' חקוק כל האורות העליונים וא\"ל זה יתנו חלק הגלוי, והענין דלא כל הנשמה מלובשת בגוף<sup data-n=\"5835\">80</sup> רק מקצת מהנשמה אבל עיקר הנשמה הוא למעלה והוא בחי' ונוזלים מלבנון<sup data-n=\"5836\">81</sup> מזלייהו חזי<sup data-n=\"5837\">82</sup>, וזהו דע מאין באת<sup data-n=\"5838\">83</sup> פי' אין א' בכתר י' בחכ' נו\"ן הם נו\"ן שע\"ב<sup data-n=\"5839\">84</sup>, והארה לבד מתלבשת בגוף, והו\"ע העלם וגילוי וכמ\"ש מי ברא אלה<sup data-n=\"5840\">85</sup> מי העלם אלה גילוי, וכתי' מי מנה עפר יעקב<sup data-n=\"5841\">86</sup> כמו גוש עפר שאינו שייך בו מספר וזהו העלי' שהחלק המלובש בגוף לשרש<sup data-n=\"5842\">*87</sup> שרשו הראשון, ולפ\"ז צריכים לפרש זה יתנו כמ\"ש בירושלמי י\"ב שבטים יתנו<sup data-n=\"5843\">87</sup> דאי' בס\"י ג' אמ\"ש<sup data-n=\"5844\">88</sup> א' מ' ש' ז' כפולות בג\"ד כפר\"ת<sup data-n=\"5845\">89</sup> וי\"ב פשוטות<sup data-n=\"5846\">90</sup> ומהם נמשך י\"ב שבטים, וזהו\"ע והחיות נושאות את הכסא<sup data-n=\"5847\">91</sup> דהם י\"ב בקר<sup data-n=\"5848\">92</sup> דבריאה והם נושאות את הכסא",[["5829","74","<b>העשיר לא ירבה</b>: תשא ל, טו."],["5830","75","<b>אין עשיר אלא בדעת</b>: ראה כתובות סח, א."],["5831","76","<b>בג' דברים נתקשה משה</b>: זהר רע\"מ תרומה קנז, סע\"ב ואילך."],["5832","77","<b>וזהו מרומז בשמו מש\"ה</b>: זהר שם. וראה גם בניצוצי אורות לשם."],["5834","79","<b>והראה לו הקב\"ה מטבע של אש</b>: ראה ירושלמי שקלים פ\"א, ה\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161394\" data-slug=\"likkutei-sichot\" data-id=\"1300161394\">לקו\"ש תשא כרך טז ע' 381</a> ואילך. וש\"נ."],["5833","78","<b>ומה שנתקשה . . ופי' הרמ\"ז</b>: לזהר פקודי רכה, ב ד\"ה ורזא דא (רנ, א)."],["5835","80","<b>דלא כל הנשמה מלובשת בגוף</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370387\" data-slug=\"torah-or\" data-id=\"3901370387\">תו\"א תשא פו, ב</a>. (לעיל בחלק המאמרים) בהמאמר כאן הערה 78."],["5836","81","<b>ונוזלים מלבנון</b>: שה\"ש ד, טו [ושם: מן לבנון — ראה לעיל הנחה ד\"ה אז ישיר משה הערה 51]."],["5837","82","<b>מזלייהו חזי</b>: מגילה ג, א."],["5838","83","<b>דע מאין באת</b>: אבות פ\"ג, מ\"א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380316\" data-slug=\"likkutei-torah\" data-id=\"4001380316\">לקו\"ת במדבר ב, סע\"א</a>."],["5839","84","<b>פי' אין . . שע\"ב</b>: ראה ת\"ז רתמ\"ב. ת\"ע קכו, סע\"א."],["5840","85","<b>מי ברא אלה</b>: ישעי' מ, כו."],["5841","86","<b>מי מנה עפר יעקב</b>: בלק כג, י."],["5842","*87","<b>בגוף לשרש</b>: כ\"ה בגוכתי\"ק."],["5843","87","<b>כמ\"ש בירושלמי י\"ב שבטים יתנו</b>: שקלים פ\"א, ה\"ג."],["5844","88","<b>דאי' בס\"י ג' אמ\"ש</b>: [ אויר מים אש] — פ\"ב, מ\"א."],["5845","89","<b>ז' כפולות בג\"ד כפר\"ת</b>: ס\"י פ\"ד, מ\"א."],["5846","90","<b>וי\"ב פשוטות</b>: ס\"י פ\"ב, מ\"א. פ\"ה, מ\"א."],["5847","91","<b>והחיות נושאות את הכסא</b>: נסמן (לעיל בחלק המאמרים) במאמר ד\"ה ועבדתם את ה\"א הערה 97."],["5848","92","<b>י\"ב בקר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380144\" data-slug=\"likkutei-torah\" data-id=\"4001380144\">לקו\"ת צו יז, רע\"א</a>."]]],[2001910531,"והאדם שעל הכסא ומה שייך אדם למעלה אלא שהו\"ע ע\"ס, וזהו זה יתנו י\"ב שבטים יתנו והנתינה היא עשר זהו ג' אמ\"ש וז' כפולות, שמקבלים מבחי' זו וצריכים ליתן כו' וכתי' והחיות נושאות, נושאות ומנושאות<sup data-n=\"5849\">93</sup> שהם מתעלים ג\"כ, והענין דהנה כתי' נודע בשערים בעלה<sup data-n=\"5850\">94</sup> כל חד וחד לפום מאי דמשער בליבו<sup data-n=\"5851\">95</sup>, דבמדות יש התחלקות דמאחר דאין דעותיהם שוות<sup data-n=\"5852\">96</sup> והמדות שנולדים מהשכל יש בהם התחלקות, אבל בחי' רעותא דליבא<sup data-n=\"5853\">97</sup> אין בזה שום התחלקות ומ\"מ יש שם עשר ספי' וזהו עשרים גרה שיתעלה חלק הגלוי המלובש בגוף בשרשו ומקורו הראשון אך צ\"ל<sup data-n=\"5854\">98</sup> ע\"פ השכל ואח\"כ העלי' בבחי' שלמעלה מהשכל, וזהו\"ע מחצית השקל בנה\"ב הוא לכה\"פ אתכפי' וסוף סוף יבא לאתהפכא ובנה\"א העלי' בבחי' רעו\"ד, וזהו כי תשא את ראש בנ\"י העלי' בשרשו ובמקורו שלמעלה מהשכל כו'.\nש\"פ פקודי\nוידעת היום<sup data-n=\"5855\">1</sup> והשבות אל לבבך כי הוי' הוא האלקים בשמים ממעל ובארץ מתחת אין עוד<sup data-n=\"5856\">2</sup>. והנה נת\"ל בד\"ה ראה קראתי בשם<sup data-n=\"5857\">3</sup> דענין המקדש הוא שיומשך מש' הוי' בשם א\"ד ובעבודה הו\"ע מצות ליחדו וזהו מ\"ש וידעת היום כו' דאף בזמן המקדש בתוכו לא נא' אלא בתוכם בכאו\"א מישראל<sup data-n=\"5858\">4</sup> וגם לאחר שחרב בהמק\"ד יש בחי' זו בכאו\"א, ועפ\"ז מתורץ משארז\"ל כ\"מ שנא' לי<sup data-n=\"5859\">5</sup> אינו זז משם לא בעוה\"ז כו' דגם עכשיו יש בכ\"א בחי' זו, ולפ\"ז צ\"ל כל הפרטים שהיו במקדש ישנם עכשיו בכ\"א מישראל. ולהבין זה צ\"ל תחילה ענין והשבות אל לבבך דלכאו' הול\"ל והשבות אל לבך דהוי' הוא האלקים כתי' אחר והשבות כו'. אך הנה לבבך הם ב' לבבות חיצוניות הלב ופנימיות הלב<sup data-n=\"5860\">6</sup> וכנגד ב' דברים שהיו במקדש מזבח החיצון ומזבח הפנימי<sup data-n=\"5861\">7</sup>,",[["5849","93","<b>והחיות . . נושאות ומנושאות</b>: ראה גם לעיל הנחה ד\"ה אז ישיר משה ובהערה 138."],["5850","94","<b>נודע בשערים בעלה</b>: משלי לא, כג."],["5851","95","<b>לפום מאי דמשער בליבו</b>: ראה זהר וירא קג, ריש ע\"ב."],["5852","96","<b>דאין דעותיהם שוות</b>: ראה ברכות נח, א ובדק\"ס שם. תניא בהקדמה."],["5853","97","<b>רעותא דליבא</b>: זהר וירא ק, א."],["5854","98","<b>אך צ\"ל</b>: אוצ\"ל: אך מתחילה צ\"ל."],["5855","1","<b>וידעת היום</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ."],["5856","2","<b>וידעת . . והשבות . . אין עוד</b>: ואתחנן ד, לט."],["5857","3","<b>בד\"ה ראה קראתי בשם</b>: נדפס לעיל (לפני הנחה ד\"ה כי תשא)."],["5858","4","<b>בזמן המקדש . . בתוכם בכאו\"א מישראל</b>: ראה לעיל בהנחה שם פיסקא והענין הנה ובהערה 25."],["5859","5","<b>כ\"מ שנא' לי</b>: ראה ויק\"ר פ\"ב, ב. מדרש שמואל פי\"ט. ספרי בהעלותך יא, טז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380346\" data-slug=\"likkutei-torah\" data-id=\"4001380346\">לקו\"ת במדבר ט, ג</a>."],["5860","6","<b>חיצוניות הלב ופנימיות הלב</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370027\" data-slug=\"torah-or\" data-id=\"3901370027\">תו\"א בראשית ז, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380589\" data-slug=\"likkutei-torah\" data-id=\"4001380589\">תצוה פד, ד</a>. לקו\"ת בלק סז, ד."],["5861","7","<b>חיצוניות הלב . . מזבח החיצון ומזבח הפנימי</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381039\" data-slug=\"likkutei-torah\" data-id=\"4001381039\">לקו\"ת סוכות עח, ד</a> ובהנסמן במ\"מ לשם. מאמרי אדה\"ז אתהלך לאזניא ע' קלב."]]],[2001910532,"מזבח החיצון שם היו מקריבין פרים ואילים וכבשים<sup data-n=\"5862\">8</sup>, ומזבח הפנימי היו מקטירין עליו קטורת<sup data-n=\"5863\">9</sup>, והנה חיצוניות הלב היא נגד מזבה\"ח והו\"ע ההקרבה דנה\"ב דשרשו מפני שור<sup data-n=\"5864\">10</sup> שבמרכבה כמו הבהמה רק שהבהמה שרשה מפני שור<sup data-n=\"5865\">11</sup> שבפני שור והנה\"ב שרשה מפני אדם שבפני שור<sup data-n=\"5866\">12</sup> אבל מ\"מ שרשו מפני שור, וההקרבה היא שיהי' לו אהבה לאלקות, דתפלה נחלק לג' מדריגות<sup data-n=\"5867\">13</sup> פסוד\"ז וברכת יוצר מדרי' א' ק\"ש ואוי\"צ מדרי' ב' שמ\"ע מדריגה ג', וענין פסוד\"ז וברכת יוצר הם התבוננות, פסוד\"ז שיר של כל הנבראים הללו את ה' מן השמים<sup data-n=\"5868\">14</sup> הללוהו במרומים הללוהו כל מלאכיו<sup data-n=\"5869\">15</sup> כו', וברכת ק\"ש הוא איך שהשרפים אומרים קדוש והאופנים וחיות הקדש אומרים ברוך ושרש הנה\"ב מהחיות עי\"ז נעשה הזזה בנה\"ב שיהי' ע\"ד בהמה של מעלה<sup data-n=\"5870\">16</sup> שהו\"ע תוקף המדה באלקות כמו\"כ הנה\"ב יהי' לו תוקף האהבה לאלקות, וזהו ההקרבה דרוח הבהמה יורדת למטה<sup data-n=\"5871\">17</sup> וכשפועלים בה העלאה זהו הקרבה, וז\"ש אחרי הוי' ילכו כארי' ישאג<sup data-n=\"5872\">18</sup> כמו במקדש הי' ארי' דאכיל קורבנין<sup data-n=\"5873\">19</sup> כמו\"כ כאן כארי' ישאג, ובחי' זו נק' חיצוניות הלב שההתבוננות הוא מבחי' חיצוניות היינו הארת אלקות דברה\"ע שהיא רק הארה חיצוניות דכתי' יהללו שם הוי' כי הוא צוה ונבראו<sup data-n=\"5874\">20</sup> דאף שהוא שם לבד שהוא הארה מ\"מ ונבראו דרך מאליו וממילא ואינו שייך בזה התלבשות כח הפועל בנפעל<sup data-n=\"5875\">21</sup> כ\"א בבחי' מל' מכ\"ע<sup data-n=\"5876\">22</sup> והוא בחי' הארה חיצוניות, ואם הי' מתבונן בהתבוננות עצמותו לא הי' הנה\"ב מתפעל מזה כלל ומהו הפעולה בהתבוננות, אך כשמתבונן איך שהמקור שלו ומקור המהווה העולם בטל לאלקות פועלים בו ג\"כ הזזה וכמאמר אין הגבורות נמתקים אלא בשרשן<sup data-n=\"5877\">23</sup>, ובחי' פנימיות",[["5862","8","<b>מזבח החיצון . . וכבשים</b>: ראה יתרו כ, כא. רמב\"ם הל' ביהב\"ח פ\"א, ה\"ו."],["5863","9","<b>ומזבח הפנימי . . קטורת</b>: ראה תצוה ל, א. ז. ח. סהמ\"צ להרמב\"ם מ\"ע כח. רמב\"ם הל' כלי המקדש פ\"א, הי\"א. הל' תמידין ומוספין רפ\"ג."],["5864","10","<b>דנה\"ב דשרשו מפני שור</b>: ראה סידור שער האלול רל, א. ש\"א יז, א הערה 11. סה\"מ תר\"ם ח\"ב ע' תקפ. וש\"נ."],["5865","11","<b>שהבהמה שרשה מפני שור</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ח. מאמרי אדה\"א שמות ח\"א ע' כח. וש\"נ. סה\"מ תרל\"ח ע' יח. וש\"נ."],["5866","12","<b>והנה\"ב . . מפני אדם שבפני שור</b>: ראה גם שערי אורה ח, א הערה 15. סה\"מ תרל\"א ח\"א ע' רלג. וש\"נ. תרל\"ח ע' לט. וש\"נ. תר\"ם ח\"ב ע' תריח."],["5867","13","<b>דתפלה נחלק לג' מדריגות</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 16."],["5868","14","<b>הללו את ה' מן השמים</b>: תהלים קמח, א."],["5869","15","<b>הללוהו כל מלאכיו</b>: תהלים שם, ב."],["5870","16","<b>ע\"ד בהמה של מעלה</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ה. ע' י. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670324\" data-slug=\"torat-chaim\" data-id=\"2300670324\">תו\"ח בראשית יב, א</a>."],["5871","17","<b>דרוח הבהמה יורדת למטה</b>: קהלת ג, כא."],["5872","18","<b>אחרי הוי' ילכו כארי' ישאג</b>: הושע יא, י."],["5873","19","<b>ארי' דאכיל קורבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שה\"א עט, ב הערה 13. סה\"מ תר\"ם ח\"א ע' מ ואילך."],["5874","20","<b>יהללו . . צוה ונבראו</b>: תהלים קמח, ה [ושם: את שם]. ראה גם לקמן הנחה ד\"ה וידבר כו' קדושים תהיו ובהערה 29. (לעיל בחלק המאמרים) מאמר ד\"ה ועבדתם את ה\"א ובהערה 79."],["5875","21","<b>כח הפועל בנפעל</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a>: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת) סוף ש\"ג."],["5876","22","<b>מל' מכ\"ע</b>: תהלים קמה, יג. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380227\" data-slug=\"likkutei-torah\" data-id=\"4001380227\">לקו\"ת אמור לה, ב</a>."],["5877","23","<b>אין הגבורות נמתקים אלא בשרשן</b>: ראה פע\"ח שער השופר שכ\"ו, פ\"א. מ\"מ, הגהות והערות קצרות לתניא פל\"א. מאמרי אדה\"א דברים ח\"ב ע' תרטו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670562\" data-slug=\"torat-chaim\" data-id=\"2300670562\">תו\"ח וירא קח, ב</a> ובהערה 14."]]],[2001910533,"הלב הוא שהי' מקטירין עליו קטורת, וקטורת הוא ל' קשר<sup data-n=\"5878\">24</sup> דתרגם ותקשור על ידו שני וקטרית<sup data-n=\"5879\">25</sup> על ידי', והו\"ע התקשרות הנה\"א באלקות וכמ\"ש הקשורים ליעקב<sup data-n=\"5880\">26</sup>, וכמו הקטורת שהם דבר שהנשמה נהנה ממנו<sup data-n=\"5881\">27</sup> ולא הגוף, אך תחילה צ\"ל בירור נה\"ב דהנה\"א מלובש בנה\"ב וכשמבררי' הנה\"ב אז אח\"כ יוכל להתקשר הנה\"א וע\"ד ענין החיות שנושאות את הכסא<sup data-n=\"5882\">28</sup> והאדם שעל הכסא, רק בהנה\"א אינו שייך ל' בירור<sup data-n=\"5883\">29</sup>, דבירור שייך כשמעורב טו\"ר והנה\"א הוא חלק אלוקה ממעל<sup data-n=\"5884\">30</sup> לכן אינו שייך בו ל' בירור כ\"א ל' נתקשר או נתעלה, וע\"י בירור דנה\"ב מתקשר הנה\"א באלקות. וע\"ד ענין שבת וששת יומין דחול<sup data-n=\"5885\">31</sup>, דששת יומין הם ענין הבירורים ושבת בורר אסור<sup data-n=\"5886\">32</sup> כ\"א עליות העולמות<sup data-n=\"5887\">33</sup> והעיקר עלי' דשבת הוא ע\"י בירורים דששת יומין דחול ולכן המהלך במדבר ואינו יודע אימתי שבת מונה ששה ימים<sup data-n=\"5888\">34</sup> ומשמר יום א', וזהו\"ע פנימיות הלב (ע' מענין ההתבוננות שע\"י ההעלאה דנה\"ב והוא בחי' חיצוניות והתבוננות שע\"י העלי' דנה\"א והוא בחי' פנימיות בלקו\"ת פ' ויקרא בביאור לד\"ה אדם כי יקריב מכם<sup data-n=\"5890\">36</sup> ושם מבואר כן על עליות הנה\"א והנר' שכ\"ה גם שהעלי' היא ע\"י בירור דנה\"ב, ושם מבו'<sup data-n=\"5891\">37</sup> שהו\"ע מפתחות הפנימים ומפתחות החיצונים<sup data-n=\"5892\">38</sup> ומבואר במ\"א שהו\"ע פסוד\"ז וק\"ש, פסוד\"ז הו\"ע מפתחות החיצונים<sup data-n=\"5893\">39</sup> בחי' אחרי ה' תלכו<sup data-n=\"5894\">40</sup> כו' וע' בשע\"ת ח\"א שת\"פ ד\"ה אחרי<sup data-n=\"5895\">41</sup>, וק\"ש הוא מפתחות הפנימים<sup data-n=\"5896\">42</sup> עליות הנה\"א וצ\"ע)<sup data-n=\"5889\">35</sup> וזהו והשבות אל לבבך ב' לבבות פנימיות<sup data-n=\"5897\">43</sup> וחיצוניות הלב.",[["5878","24","<b>וקטורת . . קשר</b>: ראה בחיי שמיני י, א: ולשון קטרת התקשרות. זהר שמיני לז, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380399\" data-slug=\"likkutei-torah\" data-id=\"4001380399\">לקו\"ת נשא כב, ד</a>. סה\"מ תרל\"ח ע' מו. וש\"נ. בהערה הבאה."],["5879","25","<b>דתרגם ותקשור . . וקטרית</b>: וישב לח, כח [ושם: וקטרת]. ראה סה\"מ תר\"ם ח\"ב ע' תרכד ואילך ובהנסמן שם."],["5880","26","<b>הקשורים ליעקב</b>: ויצא ל, מב [ושם: והקשורים]. ראה לקו\"ת נשא שם."],["5881","27","<b>דבר שהנשמה נהנה ממנו</b>: ראה ברכות מג, ב. סה\"מ תר\"ם ח\"א ע' מז. וש\"נ."],["5882","28","<b>החיות שנושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג."],["5883","29","<b>בהנה\"א . . ל' בירור</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>). וראה גם לעיל הנחה ד\"ה כי תשא ובהנסמן שם."],["5884","30","<b>חלק אלוקה ממעל</b>: איוב לא, ב. ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 34."],["5885","31","<b>שבת וששת יומין דחול</b>: ראה תו\"א ח\"ש טו, ג ואילך. (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 35."],["5886","32","<b>ושבת בורר אסור</b>: ראה שו\"ע אדה\"ז הל' שבת סשי\"ט. סה\"מ תר\"ם ח\"א ע' רמג. וש\"נ."],["5887","33","<b>ושבת . . עליות העולמות</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540867\" data-slug=\"torat-chaim\" data-id=\"2300540867\">תו\"ח בא ח\"א קכז, א</a> הערה 667."],["5888","34","<b>המהלך במדבר . . ששה ימים</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה זכור את יום השבת פ\"ו. וש\"נ."],["5890","36","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380086\" data-slug=\"likkutei-torah\" data-id=\"4001380086\">לקו\"ת</a> פ' ויקרא . . מכם</b>: ג, סע\"א ואילך."],["5891","37","<b>ושם מבו'</b>: ג, סע\"ב ואילך."],["5892","38","<b>מפתחות הפנימים . . החיצונים</b>: ראה שבת לא, ריש ע\"ב."],["5893","39","<b>פסוד\"ז הו\"ע מפתחות החיצונים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380809\" data-slug=\"likkutei-torah\" data-id=\"4001380809\">לקו\"ת פ' ראה כג, ב</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316270483\" data-slug=\"or-hatorah-hb\" data-id=\"8316270483\">אוה\"ת בראשית ס\"ע תפג</a>."],["5894","40","<b>אחרי ה' תלכו</b>: פ' ראה יג, ה [ושם: ה\"א]."],["5895","41","<b>בשע\"ת </b> [ בשער התשובה]<b> ח\"א שת\"פ </b> [ שער התפלה]<b> ד\"ה אחרי</b>: ראה שע\"ת כה, ד ואילך."],["5896","42","<b>וק\"ש הוא מפתחות הפנימים</b>: ראה לעיל הערה 39."],["5889","35","<b>(ע' . . וצ\"ע)</b>: בפנים צויין סי' עגול ועל צד הימני של הע' נרשמה הגהה זו."],["5897","43","<b>פנימיות</b>: ניכר קצת בהצילום שחסר תיבת הלב."]]],[2001910534,"<b>ועוד</b> יש עבודה ויחד לבבנו<sup data-n=\"5898\">44</sup> הוא כנגד מדרי' אחרת שהי' במקדש וית' אי\"ה<sup data-n=\"5899\">45</sup>. ועוד זאת הי' במקדש יריעות וכלים וביריעות הי' ד'<sup data-n=\"5901\">47</sup> מדרי' וכנגדם בכלים ג\"כ ד' מדרי', והם כנגד ד' אותיות הוי'<sup data-n=\"5900\">46</sup>, ובד\"כ הי' עשר יריעות כנגד ע\"ס<sup data-n=\"5902\">48</sup>, וד' דיריעות הם תכלת וארגמן ותולעת שני ושש<sup data-n=\"5903\">49</sup>, וכנגדן בכלים שולחן מנורה ארון ומזבה\"פ. ובעבודה תכלת הו\"ע יראה<sup data-n=\"5904\">50</sup>, דיראה הוא מצד ההתנשאות ואמרז\"ל תכלת דומה לים<sup data-n=\"5905\">51</sup> וים דומה לרקיע והו\"ע מלכותא דרקיע<sup data-n=\"5906\">52</sup>, וכמ\"ש המלך המרומם לבדו<sup data-n=\"5907\">53</sup> וכתי' שום תשים עליך מלך<sup data-n=\"5908\">54</sup> ואמרז\"ל שתהא אימתו עליך<sup data-n=\"5909\">55</sup>, ובד\"כ הו\"ע יראה וקבעומ\"ש, תולעת שני הוא גון סומק<sup data-n=\"5910\">56</sup> והו\"ע אהבה ברשפי אש אם רץ לבך<sup data-n=\"5911\">57</sup> וזהו\"ע הזאת הדמים שהי' במקדש ולכן איש המרובה בדמים יותר אצלו הרשפי אש, ארגמן יש בו כמה גוונים<sup data-n=\"5912\">58</sup> והוא מדת הרחמים<sup data-n=\"5913\">59</sup> יעקב<sup data-n=\"5914\">60</sup> שכולל אברהם ויצחק, וכמ\"ש לולי אלקי אבי אברהם ופחד יצחק<sup data-n=\"5915\">61</sup>, וכתי' ליעקב אשר פדה את אברהם<sup data-n=\"5916\">62</sup>, שש הוא מדת החסד<sup data-n=\"5917\">63</sup> ונק' ששת<sup data-n=\"5918\">64</sup> שכולל ששה מדות וכמ\"ש יומם יצוה הוי' חסדו<sup data-n=\"5919\">65</sup> בתוס' מם שהוא יומא דאזיל עם כולא יומין<sup data-n=\"5920\">66</sup>, ושש הוא בד<sup data-n=\"5921\">67</sup> שהוא לבן שהוא גוון עצמי<sup data-n=\"5922\">68</sup> לא",[["5898","44","<b>ויחד לבבנו</b>: ברכת (אהבת עולם אהבתנו) ק\"ש. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380588\" data-slug=\"likkutei-torah\" data-id=\"4001380588\">לקו\"ת בלק סז, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381019\" data-slug=\"likkutei-torah\" data-id=\"4001381019\">האזינו עד, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550054\" data-slug=\"torat-chaim\" data-id=\"2300550054\">תו\"ח תרומה ח\"ב כאן דש, ג</a> ובהערה 10."],["5899","45","<b>ויחד לבבנו . . וית' אי\"ה</b>: לקמן ריש פיסקא והנה נת\"ל."],["5901","47","<b>בכלים ג\"כ ד' . . כנגד ד'</b>: ראה אוה\"ת ויקהל כאן ס\"ע ב'רי ואילך."],["5900","46","<b>וביריעות הי' ד' . . אותיות הוי'</b>: ראה מאמרי אדה\"ז תקס\"ד כאן ע' סח בשולי היריעה."],["5902","48","<b>עשר יריעות כנגד ע\"ס</b>: ראה זהר תרומה קסד, ב ובאוה\"ח שם (ד\"ה והרח\"ו). רקאנטי תרומה כו, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550569\" data-slug=\"torat-chaim\" data-id=\"2300550569\">תו\"ח תרומה ח\"ב כאן שי, ג</a>. וש\"נ."],["5903","49","<b>וד' דיריעות הם . . ושש</b>: תרומה כו, א."],["5904","50","<b>תכלת הו\"ע יראה</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 48."],["5905","51","<b>תכלת דומה לים</b>: ראה לעיל שם הערה 49."],["5906","52","<b>מלכותא דרקיע</b>: ברכות נח, א."],["5907","53","<b>המלך המרומם לבדו</b>: נוסח ברכת יוצר."],["5908","54","<b>שום תשים עליך מלך</b>: פ' שופטים יז, טו."],["5909","55","<b>שתהא אימתו עליך</b>: סנהדרין כב, א (במשנה)."],["5910","56","<b>תולעת שני . . סומק</b>: ראה אוה\"ת ויקהל ע' ב'קפז. תרומה ע' א'תקא."],["5911","57","<b>אם רץ לבך</b>: ס\"י פ\"א, מ\"ח."],["5912","58","<b>ארגמן . . כמה גוונים</b>: ראה זהר תרומה קלט, א."],["5913","59","<b>ארגמן . . מדת הרחמים</b>: במאמרי אדה\"ז תקס\"ד ואוה\"ת כאן: הארגמן . . ת\"ת שהוא מדת הרחמים."],["5914","60","<b>מדת הרחמים יעקב</b>: ראה זהר לך פז, ב. מאמרי אדה\"א בראשית ע' קנו. וש\"נ."],["5915","61","<b>לולי אלקי . . ופחד יצחק</b>: ויצא לא, מב [בדילוג]. ראה ספר הבהיר סק\"צ. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370083\" data-slug=\"torah-or\" data-id=\"3901370083\">תו\"א תולדות יז, ג</a>. סידור שער הלולב רסב, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540885\" data-slug=\"torat-chaim\" data-id=\"2300540885\">תו\"ח בא ח\"א קכז ג</a>. וש\"נ."],["5916","62","<b>ליעקב אשר פדה את אברהם</b>: ישעי' כט, כב [ושם: אל בית יעקב. ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' ח. וש\"נ. סה\"מ תר\"ם ח\"ב ע' תתמו הערה 116]."],["5917","63","<b>שש הוא מדת החסד</b>: ראה הגהת הרח\"ו לזהר פקודי רכח, א. מאמרי אדה\"ז כאן ע' עה. אוה\"ת כאן ע' ב'קפז וע' קצג."],["5918","64","<b>החסד ונק' ששת</b>: ראה זהר וארא לא, א ובניצוצי אורות שם."],["5919","65","<b>יומם יצוה הוי' חסדו</b>: תהלים מב, ט."],["5920","66","<b>יומא דאזיל עם כולא יומין</b>: ראה זהר אמור קג, ב. פע\"ח שער יוה\"כ שכ\"ז, פ\"ג (הובא ברמ\"ז לזהר יתרו סז, א — <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450565\" data-slug=\"or-hatorah-hb\" data-id=\"8316450565\">אוה\"ת כאן ע' ב'קצג</a>). הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'לה."],["5921","67","<b>ושש הוא בד</b>: ראה יומא עא, ב."],["5922","68","<b>לבן שהוא גוון עצמי</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380198\" data-slug=\"likkutei-torah\" data-id=\"4001380198\">לקו\"ת אחרי כח, ג</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תפד. וש\"נ. דברים ח\"ד ע' א'רלו-א'רלז. המשך תרס\"ו ע' שעג ואילך."]]],[2001910535,"כשאר גוונים והו\"ע מ\"ש וישכם לבן בבקר<sup data-n=\"5923\">69</sup>, בקר הוא בקר דאברהם<sup data-n=\"5925\">71</sup> מדת החסד<sup data-n=\"5926\">72</sup> ונמשך בו בחי' לובן העליון<sup data-n=\"5924\">70</sup> ובעבודה הוא רצון פשוט לאלקות בחי' יחידה<sup data-n=\"5927\">73</sup>.\n<b>וכנגד</b> זה הי' ד' מדרי' בכלים, שולחן הוא נגד תכלת שהוא בחי' מל'<sup data-n=\"5928\">74</sup> יראת המלך כנ\"ל כמו\"כ שולחן<sup data-n=\"5929\">75</sup> בחי' וכמ\"ש<sup data-n=\"5930\">76</sup> כי על שולחן המלך הוא אוכל<sup data-n=\"5931\">77</sup>, אמנם כל ההשפעות הם ע\"י בחי' השולחן<sup data-n=\"5932\">78</sup> דשולחן בצפון<sup data-n=\"5933\">79</sup> וכתי' מצפון זהב יאתה<sup data-n=\"5934\">80</sup> ולכן השולחן עצמו וכל כליו היו של זהב<sup data-n=\"5935\">81</sup>, וההפרש בין תכלת לשולחן דתכלת דומה לים וים דומה לרקיע שהוא כדורי<sup data-n=\"5936\">82</sup> בחי' מקיף והשולחן פנימי, דבמל' יש ב' בחי' בחי' מקיף והוא מ\"ש המלך המרומם לבדו מאז ומזה נמשך בחי' יראה דעיקר היראה שנמשך ממלך הוא ממה שהוא מנושא ומרומם מהעם, ועוד בחי' י\"ל במל' שמתפשט השפע בפנימיות וכמ\"ש ואתה מחי'<sup data-n=\"5937\">83</sup> את כולם<sup data-n=\"5938\">84</sup> וזהו\"ע שולחן. ומנורה היא נגד תולעת שני שהוא אהבה ברשפי אש וכמו\"כ מנורה הוא אש רק שהוא מדרי' הגבוה יותר שיש בה שמן ופתילה<sup data-n=\"5940\">86</sup> שהוא בחי' תורה<sup data-n=\"5939\">85</sup>. ונגד שש שהי' במקדש הו\"ע הארון דהנה נת\"ל דשש הוא לבן שהוא גוון עצמי לא כשאר גוונים שהם צבועים בל\"א גיפארבט, וכמו\"כ הלוחות<sup data-n=\"5942\">88</sup> הם חקוקים שהוא מני' ובי' והוא",[["5923","69","<b>וישכם לבן בבקר</b>: ויצא לב, א."],["5925","71","<b>בקר דאברהם</b>: ע\"פ וירא כב, ג (כ\"ה ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370114\" data-slug=\"torah-or\" data-id=\"3901370114\">תו\"א</a> דבסמוך. וראה גם שם: יט, כז. כא, יד).\nראה זהר מקץ רג, א. רע\"מ משפטים קיט, ב. אחרי סד, ב. בלק רד, א. ת\"ז תכ\"ב סז, א. תו\"א ויצא כד, ב."],["5926","72","<b>דאברהם מדת החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ. וראה גם לעיל הנחה ד\"ה הוא אהרן ומשה על יד הערה 104 ואילך."],["5924","70","<b>לבן . . לובן העליון</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. מאמרי אדה\"א בראשית ע' רכב. וש\"נ. תו\"ח ויצא קסח, ד ובהערה 31."],["5927","73","<b>רצון פשוט . . יחידה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת פ' ראה כה, א</a> ואילך. סה\"מ תר\"ם ח\"ב ע' תרכח. וש\"נ."],["5928","74","<b>תכלת שהוא בחי' מל'</b>: ראה הגהת הרח\"ו לזהר פקודי רכח, א. מאו\"א מערכת תכלת אות כא. מאמרי אדה\"ז תקס\"ד כאן ע' סח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550749\" data-slug=\"torat-chaim\" data-id=\"2300550749\">תו\"ח ויקהל ח\"ב תח, ב</a>. וש\"נ."],["5929","75","<b>שולחן בחי' מל'</b>: ראה טור ברקת סתרע\"א, ס\"ה (קכו, ד) בשם זהר תרומה [ראה שם קנג, ב — קנה, א ובמפרשים]. פרדס שעה\"כ שכ\"ג, פכ\"א מערכת שולחן."],["5930","76","<b>בחי' וכמ\"ש</b>: כנצ\"ל: בחי' מל' וכמ\"ש."],["5931","77","<b>כי על שולחן . . אוכל</b>: שמו\"ב ט, יג [ושם: תמיד הוא אוכל — ראה גם מאמרי אדה\"א שמות ח\"ב ע' תרעח]."],["5932","78","<b>כל ההשפעות . . בחי' השולחן</b>: ראה זהר לך פח, ב. תרומה קנג, ב. קנד, ב."],["5933","79","<b>דשולחן בצפון</b>: תרומה כו, לה. פקודי מ, כב. יומא כא, ב. לג, ריש ע\"ב."],["5934","80","<b>מצפון זהב יאתה</b>: איוב לז, כב."],["5935","81","<b>השלחן . . וכל כליו . . של זהב</b>: תרומה כה, כד-כט."],["5936","82","<b>לרקיע שהוא כדורי</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' יב. ענינים ע' רפ. מאמרי אדה\"א הנחות תקע\"ז ע' קעט. סהמ\"צ להצ\"צ קסב, ב. סה\"מ תרכ\"ח סע\"ב. תרכ\"ט ע' ז."],["5937","83","<b>דבמל' יש . . המלך המרומם . . ואתה מחי'</b>: ראה אוה\"ת פ' זכור ע' א'תשעא. ויקהל ע' ב'קנח ואילך."],["5938","84","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["5940","86","<b>שיש בה שמן ופתילה</b>: ראה מאמרי אדה\"ז תקס\"ד כאן ע' סט. אוה\"ת ויקהל כאן ע' ב'רי."],["5939","85","<b>מנורה . . תורה</b>: ראה תורת העולה ח\"א פט\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550892\" data-slug=\"torat-chaim\" data-id=\"2300550892\">תו\"ח ויקהל ח\"ב תמ, א</a> ובהערה 1928."],["5942","88","<b>הלוחות הם חקוקים</b>: תשא לב, טז."]]],[2001910536,"למעלה מבחי' תושב\"כ<sup data-n=\"5941\">87</sup> וכמו כשכותבין בדיו על הקלף הרי הם ב' דברים נפרדים והדיו הוא דבר נוסף, וכמו\"כ למעלה אש שחורה ע\"ג אש לבנה<sup data-n=\"5943\">89</sup> ה\"ז דבר נוסף אבל הלוחות הם חקוקים מני' ובי' ולמעל' הו\"ע גליף גליפו בטה\"ע<sup data-n=\"5944\">90</sup>, וענין שנתנו הלוחות בארון דהנה נת\"ל דבעבודה הו\"ע בחי' יחידה ונק' כן דמקבל מא\"ס בחי' יחיד<sup data-n=\"5945\">91</sup> וזהו שנתנו הלוחות בארון זהו ההשפעה מבחי' יחיד בבחי' יחידה. וכנגד ארגמן הוא מזה\"פ שהי' מכוון כנגד הארון<sup data-n=\"5946\">92</sup> והוא בחי' ת\"ת<sup data-n=\"5947\">93</sup> בריח התיכון המבריח<sup data-n=\"5948\">94</sup> מהקצה אל הקצה.\n<b>והנה</b> ההפרש בין ד' מדרי' שביריעות לד' מדרי' שבכלים, דגבי יריעות כתי' שזור<sup data-n=\"5949\">95</sup> שהיו כלולים יחד ובהכלים הי' התחלקות דהארון הי' בקדה\"ק והבדיל הפרוכת וכמ\"ש והבדילה הפרוכת<sup data-n=\"5950\">96</sup> לכם בין הקדש ובין קדה\"ק והשולחן ומנורה ומזבח היו בהיכל<sup data-n=\"5951\">97</sup> במקדש ובמשכן היו באהל מועד שולחן בצפון ומנורה בדרום<sup data-n=\"5952\">98</sup> ומזבח מכוון באמצע. והענין דהנה לכל זמן ועת לכל חפץ תחת השמים<sup data-n=\"5953\">99</sup>, דכל דבר הוא תחת התחלקות הזמן אפי' מצות כמו מצות מילה שניתנה לאברהם ולא קודם, וכן כלליות תורה ניתנה למשה, אף דתומ\"צ הם למעלה מהזמן מ\"מ למטה<sup data-n=\"5954\">100</sup> מן הזמן, וכתי' השמים החדשים והארץ החדשה אשר אני עושה<sup data-n=\"5955\">101</sup> כו' הרי ישנם עתה ג\"כ אך עדיין לא הגיע הזמן שצריכים להתגלות, אך כ\"ז תחת השמים אבל בשמים אינו שייך שם התחלקות, ובעבודה הם מוחין ולב דבלב שייך התחלקות אהבה בפ\"ע ויראה בפ\"ע וזהו והשבות אל לבבך, אבל במוחין אינו שייך התחלקות וזהו וידעת היום שבחי'<sup data-n=\"5956\">102</sup> דעת אין שם התחלקות, הגם דגם בדעת יש חו\"ג<sup data-n=\"5957\">103</sup> מ\"מ",[["5941","87","<b>הלוחות . . תושב\"כ</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380198\" data-slug=\"likkutei-torah\" data-id=\"4001380198\">לקו\"ת אחרי כח, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381149\" data-slug=\"likkutei-torah\" data-id=\"4001381149\">מה, א</a>. ד ואילך. חוקת נו, א. נט, ג ואילך. שה\"ש ה, א."],["5943","89","<b>אש שחורה ע\"ג אש לבנה</b>: ראה רש\"י שה\"ש ה, טז ד\"ה שחורות. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תקעח."],["5944","90","<b>גליף גליפו בטה\"ע</b>: ראה זהר בראשית טו, א."],["5945","91","<b>יחידה . . בחי' יחיד</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. לקו\"ת ואתחנן יא, ג. מאמרי אדה\"א קונטרסים ע' שצא. וש\"נ. סה\"מ תר\"ם ח\"ב ע' תרכח. וש\"נ."],["5946","92","<b>מזה\"פ שהי' מכוון כנגד הארון</b>: ראה תוספתא יומא פ\"ב, הי\"א. ברייתא דמלאכת המשכן פ\"ד. רש\"י תצוה ל, ו."],["5947","93","<b>מזה\"פ . . בחי' ת\"ת</b>: ראה ע\"ח שער ציור עולמות שמ\"ג, פ\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550465\" data-slug=\"torat-chaim\" data-id=\"2300550465\">תו\"ח ויקהל שצ, ג</a>. וש\"נ."],["5948","94","<b>בריח התיכון המבריח</b>: ע\"פ תרומה כו, כח. ויקהל לו, לג."],["5949","95","<b>יריעות כתי' שזור</b>: תרומה כו, א. ויקהל לו, ח [משזר]."],["5950","96","<b>דהארון . . והבדילה הפרוכת</b>: תרומה כו, לג."],["5951","97","<b>והשולחן ומנורה ומזבח היו בהיכל</b>: תוספתא יומא שם. יומא לג, ריש ע\"ב. שקלים פ\"ו, ה\"ג. רמב\"ם הל' בית הבחירה פ\"א, ה\"ו-ז. פ\"ג, הי\"ז."],["5952","98","<b>ומנורה בדרום</b>: תרומה כו, לה. פקודי מ, כד. יומא כא, ב. לג, ריש ע\"ב."],["5953","99","<b>לכל זמן . . תחת השמים</b>: קהלת ג, א. ראה קה\"ר שם."],["5954","100","<b>מ\"מ למטה</b>: אוצ\"ל: מ\"מ הם נמשכים למטה."],["5955","101","<b>השמים החדשים . . אני עושה</b>: ישעי' סו, כב. ראה ילקוט שמעוני שם (רמז תקיב). בראשית א, א (רמז ג — ירושלים תשל\"ג ע' 7 הערה 39). ב\"ר פ\"א, יג."],["5956","102","<b>שבחי'</b>: אוצ\"ל: שבבחי'."],["5957","103","<b>בדעת יש חו\"ג</b>: ראה ע\"ח שער תיקון הנוקבא של\"ד, פ\"ג. מאמרי אדה\"א בראשית ע' ד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540168\" data-slug=\"torat-chaim\" data-id=\"2300540168\">תו\"ח וארא ח\"א נז, ד</a> הערה 14."]]],[2001910537,"הם כלולים, וכמו עד\"מ מים מכבה אש ודוקא אש הוא מכבה אבל מקור אין<sup data-n=\"5958\">104</sup> המים מכבה וכמו צור שיש בו כח על אש וכשנותנו במים אין המים מכבה הכח, או כמ\"ש הרמב\"ן דהכח היולי מהד' יסודות ארמ\"ע<sup data-n=\"5960\">106</sup> שהן עצמן הפכים אבל הכח היולי<sup data-n=\"5959\">105</sup> מארמ\"ע כלולים יחד, וכמו\"כ יובן דבבחי' שמים אינו שייך<sup data-n=\"5961\">107</sup>, ועפ\"ז יובן דיריעות שהם בחי' מקיפים לכן היו שזורים שאינו שייך שם התחלקות אבל בכלים שהם תחת השמים לכן שייך שם התחלקות.\n<b>והנה</b> נת\"ל דבחי' ויחד לבבינו הוא נגד עבודה אחרת שהי' במקדש, והוא, דלהקטיר קטרת על מזבה\"פ היו מביאים גחלים מזבה\"ח<sup data-n=\"5962\">108</sup>, והענין דבמזבה\"פ<sup data-n=\"5963\">109</sup> בעבודה הוא שמו\"ע דמה קטרת<sup data-n=\"5964\">110</sup> כך צלותא בחשאי<sup data-n=\"5965\">111</sup>, פי' קטרת בחשאי דעל מזבח החיצון הי' ארי' דאכיל קורבנין והי' שורף ומכלה הבהמה ובעבודה הו\"ע והאופנים וחיות ברעש גדול<sup data-n=\"5966\">112</sup> והו\"ע בירור דנה\"ב, אבל בקטרת היו מביאים גחלים לוחשות מעל מזבה\"ח<sup data-n=\"5967\">113</sup> גחלים שרופים בל\"א איבער געברענטע רק בהעלם הי' בהם רצוא ושוב, והקרבה דקטורת הוא משארז\"ל מיכאל עומד ומקריב<sup data-n=\"5968\">114</sup> נשמותיהן דצדיקים ע\"ג מזבח, דנשמות אף דשרשן מפנימיות הכלים<sup data-n=\"5969\">115</sup> מ\"מ ה\"ז כלי וכדי לאשתאבא בגופא דמלכא<sup data-n=\"5970\">116</sup> צ\"ל הקרבה, ומה שהיו מביאים גחלים ממזבה\"ח זהו ויחד לבבינו יחוד פנימיות הלב עם חיצוניות הלב, ובתפלה הוא ק\"ש ואמוי\"צ לכן יש בויציב ט\"ו ווי\"ן<sup data-n=\"5971\">117</sup> דבווין תתקטר<sup data-n=\"5972\">118</sup> והוא התקשרות פנימיות הלב עם חיצוניות הלב.",[["5958","104","<b>מקור אין</b>: אוצ\"ל: מקור האש אין."],["5960","106","<b>מהד' יסודות ארמ\"ע</b>: ראה שה\"א סו, א ובהערה 17. סה\"מ תרכ\"ט ע' קעט. וש\"נ. תרל\"ח ע' תצא. לקמן הנחה ד\"ה כתר יתנו לך על יד הערה 38 ואילך."],["5959","105","<b>כמ\"ש הרמב\"ן . . הכח היולי</b>: ראה בראשית א, א. סה\"מ תר\"ם ח\"א ס\"ע קפח. וש\"נ. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 105."],["5961","107","<b>שייך</b>: אוצ\"ל: שייך התחלקות."],["5962","108","<b>מזבה\"ח</b>: אוצ\"ל: ממזבה\"ח. וכן הוא להלן בסוף הפיסקא."],["5963","109","<b>דבמזבה\"פ</b>: אוצ\"ל: דמזבה\"פ."],["5964","110","<b>קטרת</b>: אוצ\"ל: קטרת בחשאי."],["5965","111","<b>צלותא בחשאי</b>: זהר ח\"ש קלב, א. ויגש רי, א. תרומה קלח, ב. ועוד. ראה מאמרי אדה\"א בראשית ע' צט. וש\"נ."],["5966","112","<b>והאופנים וחיות ברעש גדול</b>: ע\"פ ברכת יוצר."],["5967","113","<b>גחלים לוחשות מעל מזבה\"ח</b>: ראה תמיד לג, א. רמב\"ם הל' תמידין ומוספין פ\"ג, ה\"ה. ראה גם מאמרי אדה\"ז תקס\"ד כאן ע' סז. אוה\"ת ויקהל כאן ע' ב'רז ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550214\" data-slug=\"torat-chaim\" data-id=\"2300550214\">תו\"ח תרומה ח\"ב כאן שה, ד</a> ואילך. וש\"נ."],["5968","114","<b>מיכאל עומד ומקריב</b>: ראה חגיגה יב, ב כגי' הע\"י. תוד\"ה ומיכאל מנחות קי, א. מאמרי אדה\"א ויקרא ח\"א ע' א. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540486\" data-slug=\"torat-chaim\" data-id=\"2300540486\">תו\"ח שמות ח\"א ה, א</a>. וש\"נ. סה\"מ תר\"ם ח\"א ס\"ע מא ואילך."],["5969","115","<b>דנשמות . . מפנימיות הכלים</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה אז ישיר משה רפ\"ב. וש\"נ."],["5970","116","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם סה\"מ תר\"ם ח\"א ע' צז. וש\"נ."],["5971","117","<b>יש בויציב ט\"ו ווי\"ן</b>: ראה פע\"ח שער הק\"ש ש\"ח, פכ\"ח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680334\" data-slug=\"torat-chaim\" data-id=\"2300680334\">תו\"ח וישב רי, א</a> הערה 14. (לעיל בחלק המאמרים) מאמר ד\"ה שלש רגלים תחוג לי על יד הערה 75. ולקמן בהנחה שם על יד הערה 67."],["5972","118","<b>דבווין תתקטר</b>: זמירות לליל שבת — אזמר בשבחין."]]],[2001910538,"<b>ועפ\"ז</b> יובן<sup data-n=\"5973\">119</sup> פלוגתא דמשה עם בצלאל<sup data-n=\"5974\">120</sup>, בצלאל אמר שיעשה תחילה המשכן ואח\"כ הכלים ומשה א' בהיפך, דכסדר צ\"ל תחילה המקיף ואח\"כ יומשך בפנימיות וזהו שא\"ל דרך אדם בונה בית ואח\"כ מכניס לתוכו כלים, כלים שאעשה להיכן אכניסם, וא\"ל בצל אל הית וידעת<sup data-n=\"5975\">121</sup> צל הוא מקיף, ומשה א' שצ\"ל תחילה הכלים דהעיקר הוא האתעדל\"ת וכמ\"ש הן לה' אלקיך השמים ושמי השמים<sup data-n=\"5976\">122</sup> כו' רק באבותיך חשק ה'<sup data-n=\"5977\">123</sup>, דהעיקר האתעדל\"ת, וכתי' הן השמים ושמי השמים לא יכלכלוך ואף כי הבית הזה<sup data-n=\"5978\">124</sup>, וכדי שיומשך אפי' המקיף הוא ע\"י אתעדל\"ת, וזהו שכ' בפ' תרומה ועש\"ו ארון<sup data-n=\"5979\">125</sup> עצי שטים כו' ועשי\"ת שולחן<sup data-n=\"5980\">126</sup> כו' ועשי\"ת מנורת<sup data-n=\"5981\">127</sup> אתעדל\"ת מלמטלמ\"ע ועי\"ז יומשך המקיף. וזהו הפלוגתא דב\"ש וב\"ה<sup data-n=\"5982\">128</sup> בש\"א שמים קדמו וכמ\"ש בראשית ברא אלקים<sup data-n=\"5983\">129</sup> את השמים ואת הארץ ובה\"א ארץ קדמו<sup data-n=\"5984\">130</sup> דכתי' ביום עשות ה' אלקים<sup data-n=\"5985\">131</sup> ארץ ושמים וכתי' לפנים ארץ יסדת<sup data-n=\"5986\">132</sup>, ושניהם אמת דמצד המקיף שמים קדמו דבסדר השתל' שמים קדום לארץ, אבל עיקר המכוון הוא בשביל הארץ דכתי' אנכי עשיתי ארץ<sup data-n=\"5987\">133</sup> ואדם עלי' בראתי וארץ קדמה, וכמו\"כ כאן בצלאל אמ' איך שצ\"ל בסדר השתל' והמקיף קדום לפנימי ומשה א' שהעיקר האתעדל\"ת ועי\"ז יומשך המקיף.",[["5973","119","<b>ועפ\"ז יובן</b>: ראה גם לעיל הנחה ד\"ה ראה קראתי בשם על יד הערה 24 ואילך."],["5974","120","<b>פלוגתא דמשה עם בצלאל</b>: ראה ברכות נה, א."],["5975","121","<b>בצל אל הית </b> [אוצ\"ל: היית]<b> וידעת</b>: ברכות נה, א."],["5976","122","<b>הן לה' . . ושמי השמים</b>: עקב י, יד."],["5977","123","<b>רק באבותיך חשק ה'</b>: שם י, טו."],["5978","124","<b>הן השמים . . הבית הזה</b>: מלכים-א ח, כז [ושם: הנה . . אף]."],["5979","125","<b>בפ' תרומה ועש\"ו ארון</b>: כה, י."],["5980","126","<b>ועשי\"ת שולחן</b>: שם כה, כג."],["5981","127","<b>ועשי\"ת מנורת</b>: שם כה, לא. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 127."],["5982","128","<b>הפלוגתא דב\"ש וב\"ה</b>: ראה חגיגה יב, א. ב\"ר פ\"א, טו."],["5983","129","<b>בראשית ברא אלקים</b>: בראשית א, א."],["5984","130","<b>קדמו</b>: לקמן: קדמה. ואלי גם כאן צ\"ל כן."],["5985","131","<b>ביום עשות ה' אלקים</b>: בראשית ב, ד."],["5986","132","<b>לפנים ארץ יסדת</b>: תהלים קב, כו [ושם: הארץ]. כתוב זה מובא בב\"ר שם."],["5987","133","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב."]]],[2001910539,"<h3>ויקרא אל משה</h3>\n<b>ש\"פ ויקרא פ\"ז</b>\n<b>ויקרא</b> אל משה<sup data-n=\"5988\">1</sup>, ואי' בזהר ויקרא ל' חיבה<sup data-n=\"5989\">2</sup> כמ\"ש אוקיר אנוש מפז<sup data-n=\"5990\">3</sup>, והענין דהנה כתי' ולא קם עוד נביא כמשה<sup data-n=\"5991\">4</sup> ואי' בישראל לא קם<sup data-n=\"5992\">5</sup> אבל באוה\"ע קם ומני בלעם שהי' במדרי' א' עם משה רק שקיבל זה מההיפך, ואי' במדרש (ויקרא פ\"א<sup data-n=\"5993\">6</sup>) מה בין נביאי ישראל לנביאי אוה\"ע, נביאי אוה\"ע אין הקב\"ה נגלה עליהם אלא בחצי דיבור וכמ\"ש ויקר<sup data-n=\"5994\">7</sup> ונביאי ישראל הקב\"ה נגלה עליהם בדיבור וכמ\"ש ויקרא, ר\"י דכפר מנדא אמר כך אין ויקר אלא ל' טומאה וכמ\"ש אשר לא יהי' טהור מקרא לילה<sup data-n=\"5995\">8</sup>, וצ\"ל מה שייך טומאה לנבואה. והנה אי' בזהר דבלעם ועמלק<sup data-n=\"5996\">9</sup> ענינים<sup data-n=\"5997\">10</sup> אחד בשניהם יש תי' עמל רק שכאן כתי' עמל ב' וכאן כתי' עמל ק'<sup data-n=\"5998\">11</sup>. והנה כשציוה הקב\"ה לחרום את עמלק כשבא שאול אמר הקמותי את דבר ה'<sup data-n=\"5999\">12</sup> ושמואל א\"ל מאסת את דבר ה'<sup data-n=\"6000\">13</sup>, ולכאו' במה שחס על שלל עמלק הרי בטעם הדבר הי' הצדק אתו שהביא אותם להקריבם קרבן לה', ולמה הי' העון כ\"כ עד שא\"ל מאסת את דבר ה' וגדול עונו מנשוא<sup data-n=\"6001\">14</sup>, אלא צ\"ל דשלל עמלק א\"א שיהי' לו עלי'<sup data-n=\"6002\">15</sup>.\n<b>והענין</b> דהנה כתי' ועשית ציץ זהב טהור<sup data-n=\"6003\">16</sup>, יש בזה ב' פי' א' ל' נץ החמה<sup data-n=\"6004\">17</sup> וכמו עליו יציץ נזרו<sup data-n=\"6005\">18</sup> וכמו יציץ ופרח ישראל<sup data-n=\"6006\">19</sup> וא\"כ ציץ ל' הארה<sup data-n=\"6007\">20</sup>, ב' ל' הנה זה עומד אחר כתלינו משגיח מן החלונות מציץ מן החרכים<sup data-n=\"6009\">22</sup> ופי' רש\"י ראי'",[["5988","1","<b>ויקרא אל משה</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה מגילה נקראת שנדפס לעיל בחלק המאמרים [ונרשם רק חלק]. וש\"נ.\nהנחה זו נזכרה בהנחה שלאח\"ז."],["5989","2","<b>ויקרא . . ל' חיבה</b>: ויקרא א, א. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערות 5-6."],["5990","3","<b>אוקיר אנוש מפז</b>: ישעי' יג, יב."],["5991","4","<b>ולא קם עוד נביא כמשה</b>: ברכה לד, י [ושם: נביא עוד בישראל — ראה גם מאמרי אדה\"ז תקע\"א ע' כד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670123\" data-slug=\"torat-chaim\" data-id=\"2300670123\">תו\"ח בראשית לה, ב</a>. מאמרי אדה\"א במדבר ח\"ג ע' א'צח. דברים ח\"א ע' לט]."],["5992","5","<b>בישראל לא קם</b>: ראה גם הנסמן (לעיל בחלק המאמרים) בהמאמר כאן. מאמרי אדה\"א ויקרא ח\"א ע' שלז ובהנסמן שם."],["5993","6","<b>ואי' במדרש (ויקרא פ\"א</b>: ראה שם סימן יג."],["5994","7","<b>ויקר</b>: בלק כג, ד."],["5995","8","<b>אשר לא . . מקרא לילה</b>: תצא כג, יא [ושם: מקרה]."],["5996","9","<b>אי' בזהר דבלעם ועמלק</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערות 28-29."],["5997","10","<b>ענינים</b>: אוצ\"ל: ענינם."],["5998","11","<b>עמל ק'</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן פ\"ו."],["5999","12","<b>כשציוה הקב\"ה . . הקמותי את דבר ה'</b>: שמו\"א טו, א ואילך. שם, יג."],["6000","13","<b>מאסת את דבר ה'</b>: שם טו, כג. ראה גם סה\"מ תרכ\"ז כאן (ס\"ע קפד בשולי היריעה) ד\"ה וענין."],["6001","14","<b>וגדול עונו מנשוא</b>: ע\"פ בראשית ד, יג."],["6002","15","<b>דשלל עמלק . . עלי'</b>: נסמן (לעיל בחלק המאמרים) בהמאמר כאן הערה 34."],["6003","16","<b>ועשית ציץ זהב טהור</b>: תצוה כח, לו."],["6004","17","<b>נץ החמה</b>: ברכות ח, ב. ט, ב. ועוד."],["6005","18","<b>עליו יציץ נזרו</b>: תהלים קלב, יח [ושם: ועליו]."],["6006","19","<b>יציץ ופרח ישראל</b>: ישעי' כז. ו."],["6007","20","<b>ציץ ל' הארה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370370\" data-slug=\"torah-or\" data-id=\"3901370370\">תו\"א תצוה פג, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550059\" data-slug=\"torat-chaim\" data-id=\"2300550059\">תו\"ח תצוה ח\"ב שנו, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550094\" data-slug=\"torat-chaim\" data-id=\"2300550094\">שסג, ג</a>."],["6009","22","<b>הנה זה . . מציץ מן החרכים</b>: שה\"ש ב, ט."]]],[2001910540,"והבטה<sup data-n=\"6008\">21</sup> וכמ\"ש ראה ראיתי בעניי עמי<sup data-n=\"6010\">23</sup>, וצ\"ל תחילה הפי' ציץ ל' הארה, דהנה הציץ הי' על מצח אהרן<sup data-n=\"6011\">24</sup>, ואהרן הי' אחד מז' רועים<sup data-n=\"6012\">25</sup> שזן ומפרנס בחי' אה\"ר לנש\"י<sup data-n=\"6013\">26</sup>, הגם דארז\"ל דהכל בידי שמים<sup data-n=\"6014\">27</sup> חוץ מיראת שמים א\"כ י\"ש הוא בידי אדם, זהו בחי' אהוי\"ר שמלמטלמ\"ע שזהו תלוי בעבודת האדם וביגיעתו שיגיע לאהוי\"ר, אבל בחי' אה\"ר היא אהבה הבאה מלמעלה ועז\"נ עבודת מתנה<sup data-n=\"6015\">28</sup> אתן את כהונתכם, כהני ברעותא דליבא<sup data-n=\"6016\">29</sup> והוא בחי' אהבה בתענוגים, ולבחי' אה\"ר זו אינו שייך יגיעה והכנה, דהכנה שייך באהוי\"ר הבאה מלמטלמ\"ע שזה תלוי בעבודת האדם וביגיעתו<sup data-n=\"6017\">30</sup>",[["6008","21","<b>ציץ ל' . . ראי' והבטה</b>: נסמן (לעיל בחלק המאמרים) בהמאמר כאן הערה 41."],["6010","23","<b>ראה ראיתי בעניי עמי</b>: שמות ג, ז [ושם: את עני]."],["6011","24","<b>הציץ הי' על מצח אהרן</b>: תצוה כח, לח."],["6012","25","<b>ואהרן . . מז' רועים</b>: ראה תיקונים לז\"ח קד, א. סה\"מ תרל\"ט ח\"ב ע' תכב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201655\" data-slug=\"likkutei-sichot\" data-id=\"1300201655\">לקו\"ש חנוכה כרך כ ע' 643</a>. בהעלותך כרך לח ע' 193."],["6013","26","<b>אהרן . . אה\"ר לנש\"י</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370366\" data-slug=\"torah-or\" data-id=\"3901370366\">תו\"א תצוה פב, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380428\" data-slug=\"likkutei-torah\" data-id=\"4001380428\">לקו\"ת בהעלותך כט, ג</a> ואילך. מאמרי אדה\"א במדבר ח\"ג ס\"ע תתפג ואילך (ובהנסמן בראשית המאמרים שם)."],["6014","27","<b>דהכל בידי שמים</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערות 48-52."],["6015","28","<b>עבודת מתנה</b>: קרח יח, ז."],["6016","29","<b>כהני ברעותא דליבא</b>: ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316610312\" data-slug=\"or-hatorah-hb\" data-id=\"8316610312\">אוה\"ת תצא ע' תתקמא</a> מציין: ע' בזהר פ' שמיני דל\"ט ע\"א. ראה גם במ\"מ הגהות והע\"ק לאגה\"ק סי\"ח ע' מב."],["6017","30","<b>וביגיעתו</b>: ע\"כ נרשם בגוכתי\"ק."]]],[2001910541,"<h3>להבין בתוס' ביאור משנת\"ל (ד\"ה ויקרא) ב' פי' בציץ</h3>\n<b>ש\"פ צו פ' פרה</b>\n<b>להבין</b> בתוס' ביאור משנת\"ל (ד\"ה ויקרא) ב' פי' בציץ<sup data-n=\"6018\">1</sup> א' ל' הארה<sup data-n=\"6019\">2</sup> דאהרן כה\"ר ממשיך אה\"ר בנש\"י<sup data-n=\"6020\">3</sup> ב' ל' ראי'<sup data-n=\"6021\">4</sup> מציץ מן החרכים<sup data-n=\"6022\">5</sup>. הנה אי' בזהר ברע\"מ ציץ וציצית, ציץ הוא עלמא דאתי<sup data-n=\"6023\">6</sup> דמאיר בי' הארת עונג עליון מבחי' ע\"י וא\"א, וציצית הוא בחי' מל'<sup data-n=\"6024\">7</sup> מקבל השפע והוא בחי' עלמא תתאה<sup data-n=\"6025\">8</sup>, ואי' שם ציץ סימנא דעלמא דאתי<sup data-n=\"6026\">9</sup> דמעטרא בי' אהרן כהנא רבא, והוא בחי' בינה עולם התענוג<sup data-n=\"6027\">10</sup>,",[["6018","1","<b>להבין בתוס' וכו' ב' פי' בציץ</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה להבין שרשי וביאור הדברים בענין הציץ שנדפס לעיל בחלק המאמרים. וש\"נ."],["6019","2","<b>בציץ . . הארה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370370\" data-slug=\"torah-or\" data-id=\"3901370370\">תו\"א תצוה פג, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550059\" data-slug=\"torat-chaim\" data-id=\"2300550059\">תו\"ח תצוה ח\"ב שנו, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550094\" data-slug=\"torat-chaim\" data-id=\"2300550094\">שסג, ג</a>."],["6020","3","<b>דאהרן . . אה\"ר בנש\"י</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370366\" data-slug=\"torah-or\" data-id=\"3901370366\">תו\"א שם פב, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380428\" data-slug=\"likkutei-torah\" data-id=\"4001380428\">לקו\"ת בהעלותך כט, ג</a> ואילך. מאמרי אדה\"א במדבר ח\"ג ס\"ע תתפג ואילך (ובהנסמן בראשית המאמרים שם)."],["6021","4","<b>ב' ל' ראי'</b>: ראה אוה\"ת תצוה ע' א'תרפט שמציין לזהר ויקהל דרי\"ז, ב ע\"פ ויעש את הציץ, ציץ אסתכלותא. תו\"ח תצוה שם."],["6022","5","<b>מציץ מן החרכים</b>: שה\"ש ב, ט."],["6023","6","<b>בזהר ברע\"מ ציץ . . עלמא דאתי</b>: ראה לשון הרע\"מ שלח קעה, ב. הועתק בסמוך בפנים."],["6024","7","<b>בזהר ברע\"מ . . וציצית . . בחי' מל'</b>: ראה שם קעה, רע\"א. מאו\"א מערכת ציצית אות כב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550060\" data-slug=\"torat-chaim\" data-id=\"2300550060\">תו\"ח תצוה ח\"ב כאן שנט, א</a>. וש\"נ."],["6025","8","<b>מל' . . עלמא תתאה</b>: ראה זהר בראשית לד, א ובמק\"מ שם. אוה\"ת (יהל אור) תהלים ע' תטו ואילך."],["6026","9","<b>דאתי</b>: ברע\"מ שם: עלאה — וכן נעתק (לעיל בחלק המאמרים) בהמאמר כאן."],["6027","10","<b>בינה עולם התענוג</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה קדש ישראל לה' הערה 118."]]],[2001910542,"ואהרן כה\"ר ממשיך הארת הכתר שמאיר בבינה בבחי' מל', דמל' מקבל מז\"א ואף שאינם גבול שהם מדות עליונות מ\"מ הם מקור לגבול ואהרן ממשיך מבינה למל'. והענין דכתי' גדול אדונינו ורב כח ולתבונתו<sup data-n=\"6028\">11</sup> אין מספר ואי' בפרקי היכלות שיעור קומה<sup data-n=\"6029\">12</sup> של יוצר בראשית רל\"ו אלפים רבבות פרסאות, ואף שהם פרסאות של מעלה והמספר הוא שם והוא גימ' ור\"ב כ\"ח<sup data-n=\"6030\">13</sup> מ\"מ ה\"ז הגבלה, אבל לתבונתו אין מספר שאינו בגדר מספר והגבלה, וזהו שאהרן ממשיך מבחי' בינה במל', וזהו פי' ציץ ל' הארה שממשיך אור אה\"ר. ופי' הב' ציץ ל' ראי' דהנה כתי' וישע ה' אל הבל<sup data-n=\"6031\">14</sup> שנמשך ש\"ע נהורין<sup data-n=\"6032\">15</sup>, דבז\"א הם רק ק\"ן נהורין<sup data-n=\"6033\">16</sup> ולכן נק' זעי\"ר אנפין דחסר ר\"ך נהורין<sup data-n=\"6034\">17</sup> לש\"ע וענין הציץ שיומשך ש\"ע נהורין במל', וזהו\"ע הארת פנים תקון ואמת דפנוי משערות<sup data-n=\"6035\">18</sup>, דשארי ת\"ד הם שערות שיונקים מן מותרי מוחין<sup data-n=\"6036\">19</sup> וכ\"ה ע\"פ נגלה דתורה דש\"ץ צ\"ל בן ך' שנה<sup data-n=\"6037\">20</sup> שאז ראוי למלאות זקנו דאז נשלם המוחין ויונקים ממותרי מוחין, אבל תקון ואמת תתן אמת ליעקב<sup data-n=\"6038\">21</sup> הוא פנוי משערות והו\"ע הארת פנים חכ' אדם תאיר פניו<sup data-n=\"6039\">22</sup> שמאיר שם ח\"ס קדש מילי' בגרמי'<sup data-n=\"6040\">23</sup> עצם המוחין, ולכן ר' אבוהו מצא תוספתא חדתא<sup data-n=\"6041\">24</sup> צהבו פניו, ודוקא תוס' חדת\"א שנמשך ממשכיל מקור השכל בשכל ועיקר החיות ניכר במוח וזהו\"ע יאר ה' פניו אליך<sup data-n=\"6042\">25</sup> וכמו\"כ כאן תקון ואמת הוא הארת פנים וזהו שממשיכים ש\"ע נהורין והם נק' עיינין. ופי' עיינין הוא, דהנה כתי' כי עין בעין יראה<sup data-n=\"6043\">26</sup>, עינא",[["6028","11","<b>גדול אדונינו . . ולתבונתו</b>: תהלים קמז, ה [ושם: לתבונתו — ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 23]."],["6029","12","<b>בפרקי היכלות שיעור קומה</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה ועבדתם את ה\"א בסופו. וש\"נ."],["6030","13","<b>רל\"ו . . גימ' ור\"ב כ\"ח</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380309\" data-slug=\"likkutei-torah\" data-id=\"4001380309\">לקו\"ת ויקרא בהוספות נד, ב</a> מפרקי היכלות. מאמרי אדה\"א דברים ח\"ג ע' תתיט בהערה."],["6031","14","<b>וישע ה' אל הבל</b>: בראשית ד, ד. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380297\" data-slug=\"likkutei-torah\" data-id=\"4001380297\">לקו\"ת ויקרא שם נא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381138\" data-slug=\"likkutei-torah\" data-id=\"4001381138\">פינחס עז, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381288\" data-slug=\"likkutei-torah\" data-id=\"4001381288\">שה\"ש ב, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370103\" data-slug=\"torah-or\" data-id=\"3901370103\">מ, א</a>. וראה גם תו\"א ויצא כב, רע\"א."],["6032","15","<b>ש\"ע נהורין</b>: ראה זהר אד\"ר נשא קכח, ב. ע\"ח שער א\"א שי\"ג, פי\"ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010096\" data-slug=\"or-hatorah-hb\" data-id=\"8159010096\">אוה\"ת מטות ע' א'רעב</a>. המשך תער\"ב ח\"ב ע' א'רה."],["6033","16","<b>ק\"ן נהורין</b>: ראה זהר אד\"ר נשא קלה, סע\"ב. ע\"ח והמשך תער\"ב שם. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370218\" data-slug=\"torah-or\" data-id=\"3901370218\">תו\"א ויחי מח, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380698\" data-slug=\"likkutei-torah\" data-id=\"4001380698\">לקו\"ת מסעי צג, סע\"ג</a>. וש\"נ. פלח הרמון שה\"ש צח, א."],["6034","17","<b>זעי\"ר אנפין דחסר ר\"ך נהורין</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 27. וראה גם סה\"מ תרל\"ח ע' קסח. וש\"נ."],["6035","18","<b>תקון ואמת דפנוי משערות</b>: ראה זהר אד\"ר נשא קלא, א. קלג, ב. ע\"ח שער א\"א שי\"ג, פ\"ט. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת מסעי צג, א</a> ואילך."],["6036","19","<b>שערות . . מותרי מוחין</b>: ראה ע\"ח שער א\"א שי\"ג, פי\"א. מבוא שערים ש\"ה ח\"א, פי\"ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381109\" data-slug=\"likkutei-torah\" data-id=\"4001381109\">לקו\"ת ברכה צה, רע\"ג</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תשעח. וש\"נ. נ\"ך ס\"ע קעו ואילך. תו\"ח ח\"ש קכג, סע\"ג ואילך. לקמן הנחה ד\"ה קא מיפלגי במתיבתא דרקיע הערה 33."],["6037","20","<b>דש\"ץ צ\"ל בן ך' שנה</b>: ראה שו\"ע או\"ח סנ\"ג, ס\"ח. שו\"ע אדה\"ז שם, סי\"א."],["6038","21","<b>תתן אמת ליעקב</b>: מיכה ז, כ."],["6039","22","<b>חכ' אדם תאיר פניו</b>: קהלת ח, א."],["6040","23","<b>קדש מילי' בגרמי'</b>: זהר אמור צד, ב."],["6041","24","<b>ר' אבוהו מצא תוספתא חדתא</b>: ראה ירושלמי שבת פ\"ח, ה\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380697\" data-slug=\"likkutei-torah\" data-id=\"4001380697\">לקו\"ת מסעי צג, ב</a>. מאמרי אדה\"א קונטרסים ע' שדמ. וש\"נ. ש\"א יב, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550424\" data-slug=\"torat-chaim\" data-id=\"2300550424\">תו\"ח יתרו ח\"ב רסז, ג</a>. הנסמן בסה\"מ תרכ\"ז ע' פז."],["6042","25","<b>יאר ה' פניו אליך</b>: נשא ו, כה."],["6043","26","<b>כי עין בעין יראה</b>: שלח יד, יד [ושם: א) נראה — וכ\"ה לקמן ריש פיסקא והנה כתי'. ב) בדילוג — ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה מגילה נקראת ובהערה 88]."]]],[2001910543,"דלעילא ועינא דלתתא<sup data-n=\"6044\">27</sup>, ופי' עין נבואה<sup data-n=\"6045\">28</sup> וכמ\"ש וישכן ישראל בטח בדד עין יעקב<sup data-n=\"6046\">29</sup> ואמרז\"ל אין עין אלא ל' נבואה, וכמו ראתה שפחה על הים<sup data-n=\"6047\">30</sup> מה שלא ראה גדול הנביאים, וכמו שמואל א' אנכי הרואה<sup data-n=\"6048\">31</sup>, כי לנביא היום יקרא לפנים הרואה<sup data-n=\"6049\">32</sup>, דנבואה הוא גילוי ההעלם<sup data-n=\"6050\">33</sup> וכמו קיש אבי שאול<sup data-n=\"6051\">34</sup> שנאבדו אצלו האתונות והלך שאול לשאול משמואל וא\"ל שבאו האתונות ואצל שאול הי' זאת בהעלם ושמואל גילה לו הדבר, וכמו\"כ יובן מ\"ש ראתה שפחה על הים אף שהיא ממדרי' הפחותות נתגלה ההעלם שלא נתגלה לנביאים.\n<b>והנה</b> פי' עין בעין הוא עינא דלעילא ועינא דלתתא, עינא דלתתא הוא יחו\"ת ועינא דלעילא הוא יחו\"ע<sup data-n=\"6052\">35</sup>, ואיך הוא ביחו\"ע ויחו\"ת, הענין דהנה יחו\"ת הוא כמו שהי' הבריאה יש מאין, ועיקר המכוון שיהי' ביטול היש לאין, אך מה שנראה ונגלה הוא היש והביטול להאין הוא בהעלם וצ\"ל דהיש בטל להאין, וזהו איזהו חכם<sup data-n=\"6053\">36</sup> הרואה את הנולד פי' הנולד הוא בריאות<sup data-n=\"6054\">37</sup> יש מאין ומציאות היש שנתהווה מהאין נק' נולד והרוא\"ה את הנולד הוא איך שכל הנבראים בטלים לאלקו' וכמ\"ש וכל צבא השמים<sup data-n=\"6055\">38</sup> לך משתחוים והשמש משתחוה למערב דשכינה<sup data-n=\"6057\">40</sup> במערב<sup data-n=\"6056\">39</sup>, ויש פרק שכל הנבראים אומרים שירה<sup data-n=\"6058\">41</sup> ובטלים לאלקות [ופי' חכם דהוא לפ\"ע ההתבוננות], וזהו יחו\"ת ונק' עינ\"א דלתתא דאין עין אלא ל' נבואה שהוא גילוי ההעלם, וכמו\"כ כאן דהרי מציאות היש ניכר ונגלה ואיך שהם בטלים ה\"ז בהעלם וצ\"ל זה מהעלם אל הגילוי לכן נק' עין, ויחו\"ע הוא איך שכולא קמי' כלא חשיב<sup data-n=\"6059\">42</sup> וכל מה שיותר קמי'",[["6044","27","<b>עינא דלעילא ועינא דלתתא</b>: ראה זהר אד\"ר נשא קל, א."],["6045","28","<b>עין נבואה</b>: ראה שמו\"ר פל\"ח, ד."],["6046","29","<b>וישכון ישראל . . יעקב</b>: ברכה לג, כח."],["6047","30","<b>ראתה שפחה על הים</b>: מכילתא בשלח טו, ב. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ריא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540775\" data-slug=\"torat-chaim\" data-id=\"2300540775\">תו\"ח בשלח ח\"א קצד, ב</a> ואילך. סה\"מ תרל\"א ח\"א ע' רסד ואילך. לעיל הנחה ומאמר ד\"ה אז ישיר בתחילתן."],["6048","31","<b>אנכי הרואה</b>: שמו\"א ט, יט."],["6049","32","<b>כי לנביא . . הרואה</b>: שם שם, ט."],["6050","33","<b>דנבואה הוא גילוי ההעלם</b>: ראה גם לעיל הנחה ד\"ה אז ישיר משה ובהערה 29."],["6051","34","<b>קיש אבי שאול</b>: שמו\"א שם פסוק ג ואילך."],["6052","35","<b>יחו\"ת . . יחו\"ע</b>: זהר בהקדמה יב, א."],["6053","36","<b>איזהו חכם</b>: תמיד לב, א. ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310048\" data-slug=\"tanya\" data-id=\"3401310048\">תניא</a> פמ\"ג. מאמרי אדה\"א דברים ח\"א ע' רכא. וש\"נ. שע\"ת עא, ג ובהערה 23. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550089\" data-slug=\"torat-chaim\" data-id=\"2300550089\">תו\"ח תצוה ח\"ב שכט סע\"ד</a> ואילך."],["6054","37","<b>בריאות</b>: ראה גם לעיל הנחה ד\"ה אז ישיר משה ובהערה 90."],["6055","38","<b>וכל צבא השמים</b>: נחמי' ט, ו [ושם: וצבא — ראה גם לעיל בחלק המאמרים מאמר ד\"ה מגילה נקראת ובהערה 108].\nראה מאמרי אדה\"א בראשית ע' נז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670055\" data-slug=\"torat-chaim\" data-id=\"2300670055\">תו\"ח בראשית א, ג</a> ובהערה 42."],["6057","40","<b>דשכינה במערב</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרכו ואילך. סה\"מ תר\"ל ע' רעא ואילך. ע' רעט ואילך."],["6056","39","<b>והשמש משתחוה . . במערב</b>: ראה ב\"ב כה, א."],["6058","41","<b>ויש פרק . . אומרים שירה</b>: פרק שירה. ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' רל.\nפרק שירה — בבית אלקים להמבי\"ט בפירושו לפרק שירה (ע' קנה ד\"ה וקרוב הדבר) מייחסו לדוד המלך.\nנזכר בשמו בכ\"מ בדברי רבותינו ומהם: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370169\" data-slug=\"torah-or\" data-id=\"3901370169\">תו\"א מקץ לז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380208\" data-slug=\"likkutei-torah\" data-id=\"4001380208\">לקו\"ת קדושים ל, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380440\" data-slug=\"likkutei-torah\" data-id=\"4001380440\">בהעלותך לב, ג</a>. מאמרי אדה\"ז שם. שו\"ת הצ\"צ חיו\"ד ס\"ס, ס\"ו. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' רסג. המשך תער\"ב ח\"ב ע' א'לד. ע' א'קה. ח\"ג ע' א'תלה."],["6059","42","<b>שכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."]]],[2001910544,"יותר כ\"ח, וזהו ה' אחד<sup data-n=\"6060\">43</sup> ח\"ד הוא ז' רקיעים וארץ וד' הוא ד' רוחות העולם<sup data-n=\"6061\">44</sup> וזהו אחד דז\"ר וארץ וד\"ר העולם בטלים לגמרי לאלף א\"ס אלופו ש\"ע<sup data-n=\"6062\">45</sup>, שאינם מציאות דגם מקור המהוום הוא אין<sup data-n=\"6063\">46</sup> ואינו שייך שמה שנתהווה ה\"ז יש אלא שהוא ג\"כ אין, ומה שנראה למציאות היש הוא לעינינו אבל באמת ה\"ז אין, וא\"ז כמו שמבואר במ\"א דכח מסתיר ג\"כ אלקות<sup data-n=\"6064\">47</sup>, אלא כאן ההסבר בא\"א שהוא אין ממש וזהו יחו\"ע, ומ\"ש עין ית\"ל אי\"ה.\n<b>והנה</b> ב' בחי' הנ\"ל הם שילוב הוי' באד' ושילוב אד' בהוי'<sup data-n=\"6065\">48</sup>, דשם הוי' הוא יחו\"ע הי' הוה ויהי' כאחד<sup data-n=\"6066\">49</sup>, ושם אד' הוא יחו\"ת<sup data-n=\"6067\">50</sup>, וזהו כלל בשילובים דאות הא' הוא מתגבר<sup data-n=\"6068\">51</sup> וא\"כ בשילוב הוי' באד' האות הראשון משם אד' הוא מתגבר ושילוב הוי' באד'<sup data-n=\"6069\">52</sup> האות הא' משם הוי' ה\"ה מתגבר וזה יחו\"ע וזה יחו\"ת. והנה ענין שילוב הוי' באד' הוא, דאף דעיקר ההתהוות משם הוי' שהוא ל' מהווה<sup data-n=\"6070\">53</sup> מ\"מ אם הי' עיקר ההתהוות משם הוי' הי' העולם בטל במציאות ולא הי' נראה כמו שהוא עתה, אך העיקר מצד שם אד' שהוא מסתיר על שם הוי' וממנו הוא המציאות היש, ומצד שם הוי' הוא שיהי' ביטול היש לאין אך הוא בהעלם, ואיזהו חכם הרואה את הנולד ביטול היש לאין שזהו עיקר המכוון, וזהו יחו\"ת, ושילוב אד' בהוי' הוא איך ששם אד' מיוחד במאציל ב\"ה והיינו שמדת המצמצם הוא מיוחד בא\"ס, אך הנשמה ירדה למטה והגוף והנה\"ב מסתירים ומתוך היחוד העליון שהוא בהעלם וצריכים להמשיך זאת מהעלם אל הגילוי שיאיר למטה לכן נק' עינ\"א דלתתא, וזהו כי עין בעין<sup data-n=\"6071\">54</sup> שיאיר בחי' עינא דלעילא בעינא דלתתא.\n<b>אך</b> זה יהי' לע\"ל וכמ\"ש כי עין כו' בשוב הוי' את ציון<sup data-n=\"6072\">55</sup>, וז\"ש על לע\"ל נפלה ולא תוסיף קום<sup data-n=\"6073\">56</sup> שלא יהי' עוד עליות העולמות, דהנה עכשיו הוא עליות העולמות",[["6060","43","<b>ה' אחד</b>: ואתחנן ו, ד."],["6061","44","<b>ח\"ד הוא . . העולם</b>: ראה שו\"ע אדה\"ז הל' ק\"ש סס\"א, ס\"ו. סה\"מ תר\"ם ח\"א ע' קט הערה 50."],["6062","45","<b>אלופו ש\"ע</b>: לשון ב\"ר פ\"כ, ב."],["6063","46","<b>דגם מקור . . אין</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה מגילה נקראת פיסקא והפי' הב' ובהנסמן שם ובריש המאמר שם."],["6064","47","<b>דכח מסתיר ג\"כ אלקות</b>: ראה גם סה\"מ תרכ\"ט ע' קסג. וש\"נ. תר\"ם ח\"א ע' שי. וש\"נ."],["6065","48","<b>שילוב הוי' באד' . . בהוי'</b>: ראה מבו\"ש ש\"ג ח\"ב ספ\"ה. לקו\"ת ש\"ש סה, ד ובהנסמן במ\"מ לשם סד, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540126\" data-slug=\"torat-chaim\" data-id=\"2300540126\">תו\"ח וארא ח\"א נ, א</a> הערה 32."],["6066","49","<b>הוי' . . הי' הוה ויהי' כאחד</b>: ראה גם לעיל הנחה ד\"ה ראה קראתי בשם ובהערה 52."],["6067","50","<b>הוי' . . יחו\"ע . . אד' . . יחו\"ת</b>: ראה שער היחוה\"א פ\"ז. לקו\"ת שם."],["6068","51","<b>דאות הא' הוא מתגבר</b>: בלקו\"ת שם (סה, ד) בשם הפע\"ח. ובמ\"מ לשם מציין למ\"ח מסכת או\"א פ\"ג, מ\"ה. ראה גם שער היחוד והאמונה פ\"ז ע' פב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370193\" data-slug=\"torah-or\" data-id=\"3901370193\">תו\"א מקץ מג, א</a>. סה\"מ תרל\"ב ח\"א ע' סה."],["6069","52","<b>הוי' באד'</b>: אוצ\"ל: אד' בהוי'."],["6070","53","<b>הוי' שהוא ל' מהווה</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"ט. שער עצמות וכלים שער ד, ספ\"י. סה\"מ תר\"ם ח\"א ע' קצח. וש\"נ."],["6071","54","<b>כי עין בעין</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380811\" data-slug=\"likkutei-torah\" data-id=\"4001380811\">לקו\"ת פ' ראה כג, ד</a>."],["6072","55","<b>כי עין . . את ציון</b>: ישעי' נב, ח [בהוספת תיבת ”את\"]."],["6073","56","<b>נפלה ולא תוסיף קום</b>: עמוס ה, ב [ושם: לא — ראה לעיל בחלק המאמרים בהמאמר כאן ובהערה 69]."]]],[2001910545,"וכמו שבת שהוא עליות העולמות<sup data-n=\"6074\">57</sup>, דבוימ\"ב ירידת והמשכת האור מקור להתהות ה\"ז בחי' שילוב הוי' באד', אבל בשבת אז זמן עליות העולמות שילוב אד' בהוי' לכן כתי' שבת לה'<sup data-n=\"6075\">58</sup> וביו\"ט כתי' מועדי הוי'<sup data-n=\"6076\">59</sup> ששם מתגבר<sup data-n=\"6077\">60</sup>, אבל לע\"ל שיהי' הגילוי למטה כמו למעלה לא תוסיף קום שלא יהי' עוד עליות העולמות. וביאור הענין דהנה אמרז\"ל עוה\"ב אין בו לא אכילה ולא שתי' אלא צדיקים יושבים ונהנים מזיו השכינה<sup data-n=\"6078\">61</sup>, ופי' עוה\"ב מוכרח לומר שהוא עולם התחי' דעולם הנשמות מהו הרבותא דאין בו אכילה ושתי' הרי הנשמה קודם התלבשותה בגוף ג\"כ אין לה אכילה ושתי' אלא קאי על עולם התחי' שיתלבשו נשמות בגופים. ולכאורה צ\"ל וכי הקרבים והאצטומכא יהיו לריק ח\"ו, אלא צ\"ל שלע\"ל יהי' הגוף הגשמי ניזון מזיו השכינה וכמו משה שהי' ג\"פ בהר ארבעים יום<sup data-n=\"6079\">62</sup> לחם לא אכל ומים לא שתה<sup data-n=\"6080\">63</sup> וניזון הגוף מרוחניות<sup data-n=\"6081\">64</sup>, אך לאחר שירד מן ההר הי' צריך לגשמיות מפני שהעולם לא הי' מזוכך עדיין אבל לע\"ל שיזדכך העולם ממילא יהי' ניזון הגוף הגשמי מזיו השכינה שיאיר למטה כמו למעלה. וזהו ולא תוסיף קום שלא יהי' עוד עליות, דלמטה יהי' גילוי אור כמו למעלה וזהו\"ע כי עין בעין.\n<b>והנה</b> כתי' כי עין בעין נראה אותיות אהרן<sup data-n=\"6082\">65</sup> שממשיך בחי' עינא דלעילא למטה, וזהו\"ע הציץ שנשא אהרן<sup data-n=\"6083\">66</sup> והוא ציץ ל' ראי' שהמשיך בחי' עין דיחו\"ע למטה. ועתה צ\"ל מ\"ש הנה זה עומד אחר כתלינו<sup data-n=\"6084\">67</sup> משגיח מן החלונות מציץ מן החרכים, הנה כתלינו ל' רבים שיש ב' בחי' כותל אחד כותל דקדושה והוא מ\"ש ויסב חזקי' פניו אל הקיר<sup data-n=\"6085\">68</sup>, פניו הוא בחי' יאר ה' פניו אליך, קיר בחי' שם אד'<sup data-n=\"6086\">69</sup> והוא יחוד הוי' ואד', לכן המתפלל צריך שלא יהי' דבר בינו לקיר<sup data-n=\"6087\">70</sup>, דהמתפלל אומר ברוך אתה ה' שממשיך מבחי' שם הוי' לכן צריך שלא יהי' דבר חוצץ כדי שיומשך",[["6074","57","<b>שבת שהוא עליות העולמות</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540867\" data-slug=\"torat-chaim\" data-id=\"2300540867\">תו\"ח בא ח\"א קכז, א</a> הערה 667."],["6075","58","<b>שבת להוי'</b>: יתרו כ, י. ואתחנן ה, יד. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380258\" data-slug=\"likkutei-torah\" data-id=\"4001380258\">לקו\"ת בהר מב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370237\" data-slug=\"torah-or\" data-id=\"3901370237\">תו\"א שמות נג, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370292\" data-slug=\"torah-or\" data-id=\"3901370292\">בשלח סה, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370296\" data-slug=\"torah-or\" data-id=\"3901370296\">סו, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370311\" data-slug=\"torah-or\" data-id=\"3901370311\">יתרו סט, ד</a>."],["6076","59","<b>מועדי הוי'</b>: אמור כג, ב. ד. לז. מד. עזרא ג, ה."],["6077","60","<b>ששם מתגבר</b>: אוצ\"ל: ששם הוי' מתגבר."],["6078","61","<b>עוה\"ב אין בו . . השכינה</b>: ראה ברכות יז, א. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 76."],["6079","62","<b>ג\"פ בהר ארבעים יום</b>: ראה משפטים כד, יח. עקב ט, ט ואילך. עקב יח ואילך (וברש\"י ולקח טוב שם). תשא לד, כח. עקב י, י [וברש\"י שם]. תנחומא תשא לא. פקודי יא. סדר הדורות ב\"א תמ\"ח."],["6080","63","<b>לחם לא אכל ומים לא שתה</b>: תשא לד כח. [עקב ט, ט. יח]."],["6081","64","<b>וניזון הגוף מרוחניות</b>: ראה שמו\"ר פמ\"ז, ה. ז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301730240\" data-slug=\"likkutei-sichot\" data-id=\"1301730240\">לקו\"ש תשא כרך לו ע' 172</a> ואילך ובהערות 37־ 39."],["6082","65","<b>נראה אותיות אהרן</b>: ראה זהר אמור קג, א ובמק\"מ ובהרמ\"ז שם. מאמרי אדה\"א ויקרא ח\"ב ע' תשסז. וש\"נ. שמות ח\"ב ע' שמ. וש\"נ."],["6083","66","<b>הציץ שנשא אהרן</b>: תצוה כח, לח."],["6084","67","<b>הנה זה עומד אחר כתלינו</b>: שה\"ש ב, ט."],["6085","68","<b>ויסב חזקי' פניו אל הקיר</b>: ישעי' לח, ב."],["6086","69","<b>קיר בחי' שם אד'</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן רפ\"ד. ד\"ה מגילה נקראת פ\"ג פיסקא וזהו."],["6087","70","<b>המתפלל צריך . . לקיר</b>: ראה ברכות ה, ב. אוה\"ת ישעי' כרך א ע' רכח ואילך."]]],[2001910546,"ישר לקיר שם אד', ושמו\"ע יש ח\"י ברכאן דצלותא<sup data-n=\"6088\">71</sup> [כנגד ח\"י חוליות שבשדרה] והוא בחי' צדיק ח\"י עלמין<sup data-n=\"6089\">72</sup>, וכמו\"כ יש כותל בלעו\"ז<sup data-n=\"6090\">73</sup> דהפסיק<sup data-n=\"6091\">74</sup> חומה של ברזל<sup data-n=\"6092\">75</sup> בין ישראל לאביהם שבשמים, ברזל ע\"ה בגימ' עמלק<sup data-n=\"6093\">76</sup> חושבנא דדין כחושבנא דדין<sup data-n=\"6094\">77</sup>, לכן במקדש כתי' זהב וכסף ונחשת<sup data-n=\"6095\">78</sup> ואילו ברזל לא הי' במקדש וכן בבנין שלמה כתי' והבית בהבנתו<sup data-n=\"6096\">79</sup> אבן שלמה מסע נבנה ומקבות וכל כלי ברזל<sup data-n=\"6097\">80</sup> לא נשמע בבית בהבנתו, וגבי מזבח כתי' לא תניף עליהם ברזל<sup data-n=\"6098\">81</sup> כי חרבך הנפת<sup data-n=\"6099\">82</sup> עלי' ותחלליה דפוסל בנגיעה<sup data-n=\"6100\">83</sup>, דמזבח נבנה להאריך ימיו של אדם וברזל מקצר<sup data-n=\"6101\">84</sup> ימיו של אדם, מזבח מאריך כו' דע\"ג מזבח מקריבים קרבנות וקרבן בגימ' א\"א<sup data-n=\"6102\">85</sup> אריכא דאנפין ונמשך אריכות ימים, ועוי\"ל שמאריך ימיו של אדם דלעילא דע\"י הקרבן מתעלה בחי' אדם בבחי' כי לא אדם הוא<sup data-n=\"6103\">86</sup>, וזהו\"ע כל המאריך באחד<sup data-n=\"6104\">87</sup> מאריכין לו ימיו ושנותיו, פי' מאריך בהתבוננות דאחד ח\"ד ז\"ר וארץ וד' רוחות העולם וא' הוא א\"ס אלופו ש\"ע ונמשך משם להאריך ימיו של אדם משא\"כ ברזל מקצר ימיו של אדם דכתי' אם תגביהי כנשר<sup data-n=\"6105\">88</sup> שמגביהים א\"ע לקבל ממקום אשר שם כחשיכה כאורה<sup data-n=\"6106\">89</sup> ומדלג על בחי' אדם דלעילא וזהו מקצר ימיו של אדם כו' שרוצים לקבל מבחי' כי לא אדם הוא אך משם אורידך נאום הוי'<sup data-n=\"6107\">90</sup> מצד שם הוי' דבחכ'<sup data-n=\"6108\">91</sup> ובחכ' אתברירו<sup data-n=\"6109\">92</sup> לכן אורידך משם כו'. והנה החומה של ברזל מפסקת בין ישרא\"ל",[["6088","71","<b>ח\"י ברכאן דצלותא</b>: ראה זהר רע\"מ פינחס רנה, סע\"ב. ברכות כח, ב."],["6089","72","<b>צדיק ח\"י עלמין</b>: זהר בראשית כה, ב. מקץ קצג, ב. שם השמטות רע\"מ רסו, ב. ועוד. ויקרא רע\"מ יז, א."],["6090","73","<b>בלעו\"ז</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד."],["6091","74","<b>דהפסיק</b>: ראה גם ההנחה שלאח\"ז על יד הערה 15."],["6092","75","<b>חומה של ברזל</b>: ראה ברכות לב, ב."],["6093","76","<b>ברזל ע\"ה בגימ' עמלק</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה מגילה נקראת ובהערה 183."],["6094","77","<b>חושבנא דדין כחושבנא דדין</b>: ע\"פ איכ\"ר פ\"א, כ. ב\"ר פס\"ח, יב כגי' הערוך מערכת סולם. בחיי ולק\"ט ויצא כח, יב."],["6095","78","<b>זהב וכסף ונחושת</b>: תרומה כה, ג. ראה שמ\"\"ר פל\"ה, ה."],["6096","79","<b>והבית בהבנתו</b>: מלכים-א ו, ז."],["6097","80","<b>וכל כלי ברזל</b>: במלכים-א שם: והגרזן כל כלי ברזל — ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה מגילה נקראת ובהערה 181."],["6098","81","<b>לא תניף עליהם ברזל</b>: תבוא כז, ה."],["6099","82","<b>כי חרבך הנפת</b>: יתרו כ, כב."],["6100","83","<b>דפוסל בנגיעה</b>: מדות פ\"ג, מ\"ד."],["6101","84","<b>דמזבח נבנה . . וברזל מקצר</b>: מדות שם."],["6102","85","<b>וקרבן בגימ' א\"א</b>: ארך אפים — מאו\"א מערכת קרבן אות כא."],["6103","86","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."],["6104","87","<b>כל המאריך באחד</b>: ברכות יג, ב. ראה סה\"מ תרכ\"ט ע' קסח ואילך."],["6105","88","<b>אם תגביהי כנשר</b>: עובדי' א, ד [ושם: תגביה — ראה גם לעיל בחלק המאמרים בהמאמר כאן ובהערה 130]."],["6106","89","<b>כחשיכה כאורה</b>: ראה תהלים קלט, יב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380124\" data-slug=\"likkutei-torah\" data-id=\"4001380124\">לקו\"ת צו יב, א</a>. סה\"מ תר\"ם ח\"א ע' שו. וש\"נ."],["6107","90","<b>משם אורידך נאום הוי'</b>: סיום הכתוב אם תגביה [עובדי' א, ד]. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370122\" data-slug=\"torah-or\" data-id=\"3901370122\">תו\"א וישלח כו, ב</a>. מאמרי אדה\"ז תקס\"ו ע' פד ואילך [ובמהדורת תשס\"ד ח\"א ע' קסח]."],["6108","91","<b>הוי' דחכ'</b>: ראה זהר רע\"מ פינחס רנה, ריש ע\"ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קלה."],["6109","92","<b>ובחכ' אתברירו</b>: ראה אגה\"ק סכ\"ח. זהר היכלות פקודי רנד, סע\"ב. ע\"ח שער דרושי נקודות ש\"ח, פ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550161\" data-slug=\"torat-chaim\" data-id=\"2300550161\">תו\"ח תשא ח\"ב שפד, ד</a> ואילך."]]],[2001910547,"לאביהם שבשמים ולא בין אביה\"ם כו' לכן ע\"י תשובה עושים חלונות וחרכים<sup data-n=\"6110\">93</sup> בהחומה, וחלונות וחרכים יש בב' כתלים הנ\"ל, דבקדושה מצד ריבוי האור א\"א להאיר כ\"א ע\"י חרכים וכמו נקבי העין ואזן וחוטם פה דקדושה שמאיר ע\"י נקבים דוקא, וכמו\"כ בכותל דלעו\"ז אין לך דבר שעומד בפני התשובה<sup data-n=\"6111\">94</sup> ועי\"ז עושין חלונות וחרכים בהחומה כו'.",[["6110","93","<b>ע\"י תשובה . . וחרכים</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ספ\"ד. לקו\"ת שמע\"צ צא, סע\"ג ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550187\" data-slug=\"torat-chaim\" data-id=\"2300550187\">תו\"ח תצוה ח\"ב שנז, א</a>."],["6111","94","<b>אין לך דבר שעומד בפני התשובה</b>: ראה תניא פכ\"ה. אגה\"ת רפ\"ד ובמ\"מ הגהות והע\"ק לשם. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061066\" data-slug=\"likkutei-sichot\" data-id=\"1300061066\">לקו\"ש בא כרך ו ע' 66</a> הערה 54."]]],[2001910548,"<h3>ועשית ציץ</h3>\n<b>ש\"פ שמיני</b>\n<b>ועשית</b> ציץ<sup data-n=\"6112\">1</sup> זהב טהור ופתחת עליו פתוחי חותם קדש לה'<sup data-n=\"6113\">2</sup>, ונת\"ל<sup data-n=\"6114\">3</sup> ב' פי' בציץ, א' ל' הארה<sup data-n=\"6115\">4</sup> שאהרן כה\"ר ממשיך אור אה\"ר בנש\"י<sup data-n=\"6116\">5</sup>, ב' ל' הנה זה עומד<sup data-n=\"6118\">7</sup> אחר כתלינו משגיח מן החלונות מציץ<sup data-n=\"6117\">6</sup> מן החרכים, וכתלינו הם ב' בחי' כותל<sup data-n=\"6119\">8</sup> א' כותל דקדושה ך\"ו תל<sup data-n=\"6120\">9</sup>, וזהו ויסב חזקיה' פניו אל הקיר<sup data-n=\"6121\">10</sup> פניו הו\"ע יאר ה' פניו אליך<sup data-n=\"6122\">11</sup>, קיר בחי' שם אד'<sup data-n=\"6123\">12</sup> וזהו יחוד הוי' אלקי', וזה<sup data-n=\"6124\">13</sup> עומד אחר כתלינו כו' מציץ מן החרכים דמצינו חרכים בקדושה דמצד ריבוי האור א\"א להאיר כ\"א על ידי חרכים כמו נקבי העין ואזן חוטם פה דא\"ק, ב' כותל דלעו\"ז<sup data-n=\"6125\">14</sup> קיר ברזל דהפסיק<sup data-n=\"6126\">15</sup> חומת ברזל בין ישראל לאביהם שבשמים<sup data-n=\"6127\">16</sup>, ומ\"מ אין לך דבר שעומד בפני",[["6112","1","<b>ועשית ציץ</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה והנה כתיב ועשית ציץ [שהוא פ\"ה ואילך ממאמר ד\"ה להבין וכו' בענין הציץ] שנדפס לעיל בחלק המאמרים. וש\"נ."],["6113","2","<b>ועשית ציץ . . קדש לה'</b>: תצוה כח, לו."],["6114","3","<b>ונת\"ל</b>: הנחה ד\"ה ויקרא אל משה פיסקא והענין. הנחה ד\"ה להבין וכו' ב' פי' בציץ בתחילתה."],["6115","4","<b>בציץ . . הארה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370370\" data-slug=\"torah-or\" data-id=\"3901370370\">תו\"א תצוה פג, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550059\" data-slug=\"torat-chaim\" data-id=\"2300550059\">תו\"ח תצוה ח\"ב שנו, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550094\" data-slug=\"torat-chaim\" data-id=\"2300550094\">שסג, ג</a>."],["6116","5","<b>שאהרן כה\"ר . . אה\"ר בנש\"י</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370366\" data-slug=\"torah-or\" data-id=\"3901370366\">תו\"א שם פב, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380428\" data-slug=\"likkutei-torah\" data-id=\"4001380428\">לקו\"ת בהעלותך כט, ג</a> ואילך. מאמרי אדה\"א במדבר ח\"ג ס\"ע תתפג ואילך (ובהנסמן בראשית המאמרים שם)."],["6118","7","<b>הנה זה עומד</b>: שה\"ש ב, ט."],["6117","6","<b>ב' ל' . . מציץ</b>: ראה אוה\"ת תצוה ע' א'תרפט שמציין לזהר ויקהל דרי\"ז, ב ע\"פ ויעש את הציץ, ציץ אסתכלותא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550059\" data-slug=\"torat-chaim\" data-id=\"2300550059\">תו\"ח תצוה ח\"ב שנו, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550094\" data-slug=\"torat-chaim\" data-id=\"2300550094\">שסג, ג</a>."],["6119","8","<b>ב' בחי' כותל</b>: ראה גם לעיל הנחה ד\"ה להבין וכו' ב' פי' בציץ פיסקא והנה כתיב. (לעיל בחלק המאמרים) מאמר ד\"ה להבין וכו' בענין הציץ פ\"ד. ד\"ה מגילה נקראת ספ\"ג ואילך."],["6120","9","<b>כותל דקדושה ך\"ו תל</b>: ראה זהר רע\"מ משפטים קטז, רע\"א. אוה\"ת ישעי' כרך א ע' רכט."],["6121","10","<b>ויסב חזקיה' פניו אל הקיר</b>: ישעי' לח, ב."],["6122","11","<b>יאר ה' פניו אליך</b>: נשא ו, כה."],["6123","12","<b>קיר בחי' שם אד'</b>: ראה גם לעיל הנחה ד\"ה להבין וכו' ב' פי' בציץ ובהערה 69."],["6124","13","<b>וזה</b>: כ\"ה בגוכתי\"ק."],["6125","14","<b>דלעו\"ז</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד."],["6126","15","<b>דהפסיק</b>: ראה גם ההנחה שלפנ\"ז על יד הערה 74."],["6127","16","<b>חומת ברזל . . שבשמים</b>: ראה ברכות לב, ב."]]],[2001910549,"התשובה<sup data-n=\"6128\">17</sup> שע\"י תשובה עושים חלונות וחרכים בהחומת ברזל<sup data-n=\"6129\">18</sup>, וכדי שיהי' תשובה לשבר החומה, הנה משה נותן כח ע\"ז וצ\"ל למה משה דוקא.\n<b>הענין</b> הוא דהנה שם משה הוא ע\"ש כי מן המים משיתיהו<sup data-n=\"6130\">19</sup> דשרשו מהמים, מהמים שמעל לרקיע המפסיק בין מ\"ע למ\"ת, וב' הבדלות יש דכתי' יהי רקיע ויהי מבדיל<sup data-n=\"6131\">20</sup> כו', ויעש את הרקיע ויבדל<sup data-n=\"6132\">21</sup> כו', הבדלה האחת היא כמ\"ש בזהר ע\"פ יהי רקיע כהדין קרומא דפסיק במיעוהי דבר נש<sup data-n=\"6133\">22</sup> והוא חצר הכבד שמפסיק בין אברי הנשימה לאברי המזון, אברי המזון נמצא בהם פסולת ואברי הנשימה הם דקים ורוחנים, וכמו\"כ למעלה הוא ההבדלה בין קדש לחול, חול הוא שמעורב טו\"ר ואפי' בעולם הבריאה מעורב רע<sup data-n=\"6134\">23</sup> רק שרובו טוב והטוב מתגבר על הרע אבל מ\"מ יש שם רע והוא בעולם הבריאה, ואין מדברים כאן מהספי', אבל בקדש אין שם רע לא יגורך רע<sup data-n=\"6135\">24</sup>, הגם שיש קליפה נגד אצי', מקומה בבריאה<sup data-n=\"6136\">25</sup> רק שהיא כנגד אצי' (בלק\"ת פ' שמיני ד\"ה למנצח על השמינית<sup data-n=\"6137\">26</sup> יעו\"ש), אבל באצי' לא יגורך רע לך יש פרסה<sup data-n=\"6138\">27</sup> המפסקת בין אצי' לבריאה, עוד הבדלה יש בין קדש לקדש ובנפש האדם הוא קרומא דחפיא על מוחא<sup data-n=\"6139\">28</sup> לבד קרום שהמוח מונח בו יש עוד קרום ונק' קרומא דאוירא<sup data-n=\"6140\">29</sup> והוא מפסיק בין האויר ובין המוח, למעלה הוא הפרסא בין חכ' דאצי' לח\"ס, דחכ' דאצי' מתפתח לל\"ב שבילין<sup data-n=\"6141\">30</sup> בז\"א אבל מו\"ס לא אתפתח והוא סתים ונעלם, ומשה שרשו ממים שממעל לפרסא הראשונה ג\"כ דשרשו מח\"ס, וקריאת שם משה קאי על הנשמה המלובשת בגוף, דנשמה עצמה אינו שייך לשם דקודם התלבשותה לא הי' שייכה לשם כלל והגוף ג\"כ אינו שייך לשם, א\"כ קריאת השם הוא להנשמה המלובשת בגוף<sup data-n=\"6142\">31</sup>, וקריאת שם משה הוא ע\"ש",[["6128","17","<b>אין לך דבר שעומד בפני התשובה</b>: ראה תניא פכ\"ה. אגה\"ת רפ\"ד ובמ\"מ הגהות והע\"ק לשם. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061066\" data-slug=\"likkutei-sichot\" data-id=\"1300061066\">לקו\"ש בא כרך ו ע' 66</a> הערה 54."],["6129","18","<b>חלונות וחרכים בהחומת ברזל</b>: ראה גם לעיל הנחה ד\"ה להבין וכו' ב' פי' בציץ ובהערה 93."],["6130","19","<b>כי מן המים משיתיהו</b>: שמות ב, י. ראה מאמרי אדה\"א שמות ח\"ב ע' שצד ואילך. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540049\" data-slug=\"torat-chaim\" data-id=\"2300540049\">תו\"ח שמות ח\"א מג, א</a>. וש\"נ. ראה גם פלח הרמון מג\"א כאן ע' שנו."],["6131","20","<b>יהי רקיע ויהי מבדיל</b>: בראשית א, ו [בדילוג] וברש\"י שם."],["6132","21","<b>ויעש את הרקיע ויבדל</b>: בראשית א, ז [בדילוג]. ראה גם לקו\"ת ואתחנן יא, ב ובהנסמן במ\"מ לשם."],["6133","22","<b>כהדין קרומא . . דבר נש</b>: ראה זהר בראשית לב, ב."],["6134","23","<b>בעולם הבריאה מעורב רע</b>: ראה ע\"ח שער הקליפות שמ\"ח, פ\"ג. ביאוה\"ז להצ\"צ בחוקותי כרך א ע' תמד. סה\"מ תר\"ם ח\"ב ע' תתו. וש\"נ."],["6135","24","<b>לא יגורך רע</b>: תהלים ה, ה. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380322\" data-slug=\"likkutei-torah\" data-id=\"4001380322\">לקו\"ת במדבר ג, ג</a>."],["6136","25","<b>קליפה נגד אצי' מקומה בבריאה</b>: ראה אוה\"ת ויצא כרך ה' ע' תתמה: ”כ\"מ בע\"ח שער הקליפות פ\"ב . . בשער ק\"נ פ\"ט\" ע\"ש. פ' שופטים ס\"ע תתל ואילך. לקו\"ת שבהערה הבאה ושבהערה שלפנ\"ז."],["6137","26","<b>בלק\"ת . . למנצח על השמינית</b>: כא, א."],["6138","27","<b>לך . . פרסה</b>: אוצ\"ל: לכך . . פרסא."],["6139","28","<b>קרומא דחפיא על מוחא</b>: ראה זהר אד\"ר נשא קכח, ב."],["6140","29","<b>קרומא דאוירא</b>: ראה זהר ספרא דצניעותא תרומה קעו, ב. אד\"ר שם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380672\" data-slug=\"likkutei-torah\" data-id=\"4001380672\">לקו\"ת מטות פז, ג</a>."],["6141","30","<b>מתפתח לל\"ב שבילין</b>: אד\"ר שם."],["6142","31","<b>השם הוא להנשמה המלובשת בגוף</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380254\" data-slug=\"likkutei-torah\" data-id=\"4001380254\">לקו\"ת בהר מא, ג</a>."]]],[2001910550,"מן המים משיתיהו וקאי הנשמה<sup data-n=\"6143\">32</sup> המחי' את גוף משה, א\"כ נשמת משה שנתלבשה בגוף להחיותו הוא מבחי' ח\"ס לכן הי' בכחו לדחות את עמלק דאור דוחה חשך, דקיר ברזל דעמלק הוא חשך העלם והסתר שמסתיר על הקדושה ומשה הוא שרש ומקור האור למעלה לכן הוא דוחה את חשך דעמלק, ועכשיו ע\"י התורה אפשר לדחות את הרע דעמלק.\n<b>והענין</b> דהנה התורה נק' ע\"ש משה כמ\"ש זכרו תורת משה עבדי<sup data-n=\"6144\">33</sup>, וצ\"ל למה נק' ע\"ש משה. והענין דנובלות חכ' שלמעלה תורה<sup data-n=\"6145\">34</sup> ויש בזה כמה פי', פעמים מבואר<sup data-n=\"6146\">35</sup> שקאי על תורה הנגלית שיתא סדרי משנה<sup data-n=\"6147\">36</sup> והוא הארת החכ' במדות לכן הם שיתא סדרי כו' שהם ו' מדות<sup data-n=\"6148\">37</sup>, וזהו כשר פסול טמא טהור כו', כשר הוא מצד החסד שיוכל להתעלות בקדושה ופסול הוא שא\"א להתעלות כ\"א צריך דחי' והוא מצד הגבו', וכן חייב זכאי כשר פסול<sup data-n=\"6149\">38</sup> כו', ומ\"מ הוא מצד השכל שמחייב כן ה\"ז הארת החכ' במדות ונק' נובלות חכ' כו' שאינו בערך לגבי חכ' שלמעלה, ופעמים מבואר<sup data-n=\"6150\">39</sup> דאורייתא מחכ' נפקת<sup data-n=\"6151\">40</sup> והוא נובלות לגבי בחי' ח\"ס, דהנה כתי' והחכ' מאין תמצא<sup data-n=\"6152\">41</sup> דהתהוות החכ' אינו בדרך עו\"ע כ\"א מאין דלמעלה מחכ' לא הי' בחי' חכ' ומה שנק' חכמ\"ה סתימאה מפני שנמשך מזה חכ' באצי' אבל שם אינו שייך שם חכ' כלל, וזהו שא' בזהר או\"א במזלא אתכלילו<sup data-n=\"6153\">42</sup> וענין המזלות הם י\"ג ת\"ד<sup data-n=\"6155\">44</sup> שערות<sup data-n=\"6154\">43</sup> וכשקוצץ<sup data-n=\"6156\">45</sup> השערות אינו מרגיש כאב אף דיניקתם מהמוח מ\"מ אם נקב קרום של מוח טריפה<sup data-n=\"6157\">46</sup> דתלוי בו החיות אבל כשקוצץ השערות אינו מרגיש כאב דהחיות בהם חיות מצומצם ולכן נק' נובלות חכ' שלמעלה שאינו בערך כו', וזהו ותרד העינה ותמלא כדה ותעל<sup data-n=\"6158\">47</sup>, וכדה על שכמה<sup data-n=\"6159\">48</sup>, כדה הם ך\"ד ספרים דאורייתא<sup data-n=\"6160\">49</sup> שהוא כמו",[["6143","32","<b>וקאי הנשמה</b>: אוצ\"ל: וקאי על הנשמה."],["6144","33","<b>זכרו תורת משה עבדי</b>: מלאכי ג, כב."],["6145","34","<b>דנובלות חכ' שלמעלה תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["6146","35","<b>פעמים מבואר</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381206\" data-slug=\"likkutei-torah\" data-id=\"4001381206\">לקו\"ת שה\"ש יט, ב</a>."],["6147","36","<b>שיתא סדרי משנה</b>: ראה זהר בראשית מב, א. במד\"ר פי\"ב, יז. פי\"ג, טוטז. שבת לא, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111064\" data-slug=\"likkutei-sichot\" data-id=\"1300111064\">לקו\"ש בשלח כרך יא ע' 56</a> הערה 13."],["6148","37","<b>שיתא סדרי . . ו' מדות</b>: ראה ת\"ז בהקדמה ה, א. לעיל הנחה ד\"ה ועבדתם את ה\"א ובהערה 87."],["6149","38","<b>כשר פסול</b>: יש להעיר שתיבות אלו כבר הובאו כאן לפנ\"ז."],["6150","39","<b>ופעמים מבואר</b>: לקו\"ת ברכה צה, ריש ע\"ב."],["6151","40","<b>דאורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["6152","41","<b>והחכ' מאין תמצא</b>: איוב כח, יב. ראה אגה\"ק סי\"ז קכו, רע\"א. מאמרי אדה\"א דברים ח\"ג ע' תשעט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670072\" data-slug=\"torat-chaim\" data-id=\"2300670072\">תו\"ח בראשית ז, ד</a> ובהערה 49. בא ח\"א קא, ג. וש\"נ. (לעיל בחלק המאמרים) מאמר ד\"ה והנה תורה היא בחי' קו האמצעי על יד הערה 224 ואילך."],["6153","42","<b>או\"א במזלא אתכלילו</b>: ראה זהר אדר\"ז רפט, ב. רצב, א."],["6155","44","<b>י\"ג ת\"ד</b>: ראה זהר תרומה ספדצ\"נ פ\"ת קעז, א. אד\"ר נשא קלא, א."],["6154","43","<b>המזלות . . שערות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380242\" data-slug=\"likkutei-torah\" data-id=\"4001380242\">לקו\"ת אמור לט, א</a>."],["6156","45","<b>וכשקוצץ</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן הלשון הוא: לגוזזם. ועד\"ז בכ\"מ."],["6157","46","<b>נקב קרום של מוח טריפה</b>: חולין מב, א (במשנה)."],["6158","47","<b>ותרד העינה ותמלא כדה ותעל</b>: ח\"ש כד, טז."],["6159","48","<b>וכדה על שכמה</b>: ח\"ש שם, טו."],["6160","49","<b>כדה הם ך\"ד ספרים דאורייתא</b>: ראה ת\"ז בהקדמה יד, א. תכ\"א מו, ב. מז, א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370084\" data-slug=\"torah-or\" data-id=\"3901370084\">תו\"א תולדות יז, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540697\" data-slug=\"torat-chaim\" data-id=\"2300540697\">תו\"ח וארא פ, א</a>. וש\"נ."]]],[2001910551,"כד מים או ממעיין ואינו בערך לגבי כללות הים או המעין [שהוא הארה] ומשה שרשו מבחי' ח\"ס, לכן הוא נתן את התורה, ונק' ע\"ש כמ\"ש זכרו תורת משה עבדי, תורה צוה לנו משה<sup data-n=\"6161\">50</sup>, תורת משה, שהוא למעלה מבחי' תורה, אך מ\"מ ה\"ז נובלות מחכ' שלמעלה, וגם ית\"ל בענין ופתחת כו' חותם שהוא בחי' אמת עצם ח\"ס לכן ע\"י התורה יכולים לדחות את הרע דעמלק אך שיהי' למוד התורה כמו משה בחי' מ\"ה<sup data-n=\"6162\">51</sup>, אך א\"א לדרוש מכ\"א שיהי' במדרי' משה, אבל מ\"מ כ\"א לפ\"ע דמה להלן באימה<sup data-n=\"6163\">52</sup> ויראה אף כאן באימה ויראה והוא ע\"י התבוננות כללות ודברי אשר שמתי בפיך<sup data-n=\"6164\">53</sup> תען לשוני אמרתך<sup data-n=\"6165\">54</sup>, וזהו\"ע הציץ שע\"י תשובה עושין חלונות וחרכים מהחומה<sup data-n=\"6166\">55</sup>, ומשה הוא העושה הציץ<sup data-n=\"6167\">56</sup> זהב טהור, זהב מצד הבינה<sup data-n=\"6168\">57</sup>, וזהו מה שנמשך מעלמא עילאה בחי' עונג העליון בעלמא תתאה.\n<b>ופתחת</b> עליו פתוחי חותם<sup data-n=\"6169\">58</sup>, הנה אמרז\"ל חותמו של הקב\"ה אמת<sup data-n=\"6170\">59</sup> ואין אמת אלא תורה<sup data-n=\"6171\">60</sup> א\"כ תורה הוא החותם והוא בחי' אמת, דכתי' אמת קנה ואל תמכור<sup data-n=\"6172\">61</sup>, תורת אמת היתה בפי'<sup data-n=\"6173\">62</sup>, דהנה על תורה כתי' כי באור פניך<sup data-n=\"6174\">63</sup> נתת לנו תורת חיים, פי' באור פניך הוא בחי' אור פני מלך חיים<sup data-n=\"6175\">64</sup>, אור פני הוא בחי' תקון ואמת<sup data-n=\"6176\">65</sup> הארת פנים ומלך חיים הוא בחי' ז\"א, וזהו תתן אמת<sup data-n=\"6178\">67</sup> ליעקב<sup data-n=\"6177\">66</sup> וכמ\"ש משה<sup data-n=\"6179\">68</sup> שהמשיך בחי' י\"ג ת\"ד דא\"א בז\"א<sup data-n=\"6180\">69</sup>, הגם דעיקר האמת הוא בח\"ס מ\"מ בז\"א שם ניכר האמת, ועוד דמז\"א נמשך למל', ואף דנת\"ל דז\"א מקור הגבול<sup data-n=\"6181\">70</sup>, מ\"מ",[["6161","50","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["6162","51","<b>משה בחי' מ\"ה</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה הוא אהרן ומשה ובהערה 140."],["6163","52","<b>דמה להלן באימה</b>: ברכות כב, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670248\" data-slug=\"torat-chaim\" data-id=\"2300670248\">תו\"ח נח מט, סע\"ג</a> ואילך ובהערה 25. יתרו ח\"ב רנג, ד ואילך. שע\"ת מא, א. מאמרי אדה\"א הנחות תקע\"ז ע' קכב."],["6164","53","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["6165","54","<b>תען לשוני אמרתך</b>: תהלים קיט, קעב."],["6166","55","<b>מהחומה</b>: אצ\"ל: בהחומה."],["6167","56","<b>ומשה הוא העושה הציץ</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן פיסקא ”לכאו'\" (אצל הערה נז) בסופה."],["6168","57","<b>זהב מצד הבינה</b>: ראה פרדס שער הגוונים ש\"י, פ\"ג. שעה\"כ שכ\"ג, פ\"ז מערכת זהב. מאו\"א מערכת זהב אות יא. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380455\" data-slug=\"likkutei-torah\" data-id=\"4001380455\">לקו\"ת בהעלותך לו, ב</a> ס\"ד. (יהל אור) אוה\"ת תהלים יט, יא."],["6169","58","<b>ופתחת עליו פתוחי חותם</b>: המשך הכתוב ועשית ציץ זהב טהור — תצוה כח, לו."],["6170","59","<b>חותמו של הקב\"ה אמת</b>: שבת נה, א."],["6171","60","<b>ואין אמת אלא תורה</b>: ראה ירושלמי ר\"ה פ\"ג, ה\"ח. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' שסט."],["6172","61","<b>אמת קנה ואל תמכור</b>: משלי כג, כג."],["6173","62","<b>תורת אמת היתה בפי'</b>: מלאכי ב, ו."],["6174","63","<b>כי באור פניך</b>: סיום תפלת העמידה."],["6175","64","<b>אור פני מלך חיים</b>: ע\"פ משלי טז, טו."],["6176","65","<b>תקון ואמת</b>: נסמן בסמוך."],["6178","67","<b>תתן אמת ליעקב</b>: מיכה ז, כ."],["6177","66","<b>ז\"א . . ליעקב</b>: ראה ע\"ח שער פרצופי זו\"ן של\"א, פ\"א. שער הקליפות שמ\"ח, פ\"ג. שער הפסוקים וישלח לב, כט. שער היחוד ע' קלג ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380698\" data-slug=\"likkutei-torah\" data-id=\"4001380698\">לקו\"ת מסעי צג, ג</a>."],["6179","68","<b>וכמ\"ש משה</b>: לעיל (בחלק המאמרים) בהמאמר כאן אומר: ”שז\"ע יגמדה\"ר שאמר משה\" — תשא לד, ו-ז."],["6180","69","<b>משה . . י\"ג ת\"ד דא\"א בז\"א</b>: ראה זהר אד\"ר נשא קלא, ב. קלח, א. סה\"מ תרל\"ח ע' תפב. וש\"נ."],["6181","70","<b>דז\"א מקור הגבול</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה להבין וכו' בענין הציץ קרוב לתחילתו."]]],[2001910552,"כשנמשך בו מבחי' תקון ואמ\"ת הוא בחי' בבע\"ג, וזהו\"ע חכמת אדם תאיר פניו<sup data-n=\"6182\">71</sup> חכ' אדם הוא בחי' ח\"ס וכמו ר\"א מצא תוס' חדתא צהבו פניו<sup data-n=\"6183\">72</sup> שנמשך ממשכיל מקור השכל, וזהו התורה נק' אמת בחי' תרין תפוחין תקון ואמת שפנוי משערות<sup data-n=\"6184\">73</sup> מפני שנמשך מעצם ח\"ס, והוא החותם של הקב\"ה אמת, וחותם אותיות תחום ואותיות חומת<sup data-n=\"6185\">74</sup>, תחום הוא הגבלה ומזה נעשה החומה וע\"י החותם שוברים החומה.\n<b>ומה</b> הי' כתוב על ציץ קדש לה' ויש בזה ב' פי', הפרדס מפרש שיומשך מקדש בש' הוי'<sup data-n=\"6186\">75</sup> וכמ\"ש שאו ידיכם קדש<sup data-n=\"6187\">76</sup> וברכו את הוי', דהנה יש קדש וקדוש, קדוש ו'<sup data-n=\"6188\">77</sup> הוא המשכה שיהי' ה' מקור ההתהוות בהבראם בה' בראם<sup data-n=\"6189\">78</sup> אות הוא בצבא דילי'<sup data-n=\"6190\">79</sup>, וזהו קדוש כו' ג\"פ הוי' צבאות<sup data-n=\"6191\">80</sup> אות הוא בצבא דילי'<sup data-n=\"6192\">81</sup>, וקדש הוא מה שקדוש ומובדל, ומבחי' קדש נמשך בשם הוי' וכמ\"ש שאו ידיכם קדש, ידיכם הוא יחו\"ע ויחו\"ת<sup data-n=\"6193\">82</sup> וברכו את הוי' שיתברך ויומשך בשם הוי' וכמו\"כ כאן מקדש יומשך בש' הוי' והוא שם הוי' דסדר השתל'. אך רבינו ז\"ל מפרש<sup data-n=\"6194\">83</sup> ונמשך אחר הגמ' דקדש ל' למטה והוי' למעלה<sup data-n=\"6195\">84</sup> א\"כ הוי' למעלה מקדש, וענין קדש ל' הם מ\"ע ומל\"ת<sup data-n=\"6196\">85</sup>, קדש הוא מ\"ע דמברכים אשר קדשנו במצותיו, ול' הם מל\"ת דלא תעשה הוא ל' ורוב מל\"ת כתי' בהם לא, אפי' אותן דלא כתי' בהם לא וכמארז\"ל כ\"מ השמר<sup data-n=\"6197\">86</sup> פן ואל אינו אלא ל\"ת<sup data-n=\"6198\">87</sup>, מ\"מ המכוון הוא בלא תעשה. ועוי\"ל דמקור מל\"ת בעה\"ד הוא מ\"ש ולא יהי'<sup data-n=\"6199\">88</sup>, דאנכי<sup data-n=\"6200\">89</sup> ולא יהי', אנכי הוא מקור מ\"ע לא יהי' לך מקור מל\"ת<sup data-n=\"6201\">90</sup> א\"כ",[["6182","71","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["6183","72","<b>ר\"א מצא . . צהבו פניו</b>: ראה ירושלמי שבת פ\"ח, ה\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380697\" data-slug=\"likkutei-torah\" data-id=\"4001380697\">לקו\"ת מסעי צג, ב</a>. מאמרי אדה\"א קונטרסים ע' שדמ. וש\"נ. ש\"א יב, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550424\" data-slug=\"torat-chaim\" data-id=\"2300550424\">תו\"ח יתרו ח\"ב רסז, ג</a>. הנסמן בסה\"מ תרכ\"ז ע' פז."],["6184","73","<b>תקון ואמת שפנוי משערות</b>: ראה זהר אד\"ר נשא קלא, א. קלג, ב. ע\"ח שער א\"א שי\"ג, פ\"ט. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת מסעי צג, א</a> ואילך."],["6185","74","<b>וחותם . . תחום . . חומת</b>: ראה ע\"ח שער הירח של\"ה, פ\"ג. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקצח. מאמרי אדה\"א נ\"ך ע' תסד. שע\"ת פב, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540863\" data-slug=\"torat-chaim\" data-id=\"2300540863\">תו\"ח בשלח ח\"א רלג, א</a>. סה\"מ תרל\"ח ריש ע' קפב. ובהנסמן בהנ\"ל."],["6186","75","<b>הפרדס . . מקדש בש' הוי'</b>: ראה שם שעה\"כ שכ\"ג, פי\"ח מערכת ציץ. אוה\"ת תצוה כאן ע' א'תשלב ואילך."],["6187","76","<b>שאו ידיכם קדש</b>: תהלים קלד, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">לקו\"ת שה\"ש כא, סע\"ב</a> ואילך."],["6188","77","<b>קדש . . קדוש וא\"ו</b>: ראה לעיל הנחה ד\"ה הקבצו ושמעו בנ\"י הערה 89."],["6189","78","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב. פרש\"י עה\"פ."],["6190","79","<b>אות הוא בצבא דילי'</b>: נסמן בסמוך."],["6191","80","<b>קדוש . . הוי' צבאות</b>: ישעי' ו, ג."],["6192","81","<b>צבאות . . בצבא דילי'</b>: ראה חגיגה טז, רע\"א [לגי' הע\"י]. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381022\" data-slug=\"likkutei-torah\" data-id=\"4001381022\">לקו\"ת האזינו עד, רע\"ד</a> ובהנסמן במ\"מ לשם. מאמרי אדה\"א שמות ח\"א ע' רפה. וש\"נ. סה\"מ מלוקט א' ע' שעט. וש\"נ."],["6193","82","<b>ידיכם הוא יחו\"ע ויחו\"ת</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381215\" data-slug=\"likkutei-torah\" data-id=\"4001381215\">לקו\"ת שה\"ש כא, ג</a>."],["6194","83","<b>רבינו ז\"ל מפרש</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370372\" data-slug=\"torah-or\" data-id=\"3901370372\">תו\"א תצוה כאן פג, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370374\" data-slug=\"torah-or\" data-id=\"3901370374\">פד, א</a>."],["6195","84","<b>דקדש ל' . . למעלה</b>: שבת סג, ב. סוכה ה, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550059\" data-slug=\"torat-chaim\" data-id=\"2300550059\">תו\"ח תצוה ח\"ב שנו, א</a> הערה 3."],["6196","85","<b>קדש ל' הם מ\"ע ומל\"ת</b>: ראה גם אוה\"ת תצוה כאן ע' א'תשי. מטות ע' א'רעט. פלח הרמון מג\"א כאן ע' שסה."],["6197","86","<b>כ\"מ השמר</b>: אוצ\"ל: כ\"מ שנאמר השמר."],["6198","87","<b>השמר פן ואל . . ל\"ת</b>: ראה ערובין צו, א."],["6199","88","<b>מ\"ש ולא יהי'</b>: יתרו כ, ג [ושם: לא — וכ\"ה בסמוך]."],["6200","89","<b>דאנכי</b>: שם כ, ב."],["6201","90","<b>אנכי . . מ\"ע לא יהי' . . מל\"ת</b>: ראה זח\"ב (תוספות) רעו, א. (יתרו) צא. א. של\"ה ר\"פ יתרו שטו, ב. תניא רפ\"כ."]]],[2001910553,"ה\"ז ל'. וההפרש בין מ\"ע למל\"ת, מ\"ע הוא בקום ועשה וכמו תפילין שע\"י שמניחם ומשעבד הלב והמוח<sup data-n=\"6202\">91</sup> נמשך למעלה ג\"כ המשכת מוחין לז\"א<sup data-n=\"6203\">92</sup>, ומל\"ת הם בלא תעשה מפני שהם למעלה ממ\"ע לכן כדי להמשיכם הוא ע\"י השלילה דלא<sup data-n=\"6204\">93</sup>. וזהו אני חומה ושדי כמגדלות<sup data-n=\"6205\">94</sup>, אני חומה זו תורה<sup data-n=\"6206\">95</sup>, זהו בד\"כ, ובדרך פרט אני חומה מ\"ע, ושדי כמגדלות הם מל\"ת<sup data-n=\"6207\">96</sup> דמגדל בראש החומה, וזהו שאמרז\"ל שדואג ואחיתופל שאלו ג' מאות אבעיות במגדל הפורח באויר<sup data-n=\"6208\">97</sup> פי' מגדל הם מל\"ת ופורח באויר דשרשו מאויר קדמאה<sup data-n=\"6209\">98</sup>, ומ\"מ כ\"ז למטה והוי' למעלה. והענין דהנה דקדש ל' הוא באתעדל\"ת אתעדל\"ע<sup data-n=\"6210\">99</sup> דמ\"ע הם באתעדל\"ת שע\"י שעושה המצוה למטה נמשך מלמעלה ג\"כ, ואפי' מל\"ת הם באתעדל\"ת והוא הכפי' שמבטל א\"ע שלא יעשה כו', והוי' הוא בחי' אתעדל\"ע שאין אתעדל\"ת מגעת לשם. וזהו כמו גשם וטל דכנס\"י שאלו שלא כהוגן<sup data-n=\"6211\">100</sup> ויבא כגשם לנו<sup data-n=\"6212\">101</sup> והקב\"ה הושיבם כהוגן אהי' כטל לישראל<sup data-n=\"6213\">102</sup>, דגשם הוא באתעדל\"ת אתעדל\"ע [ומ\"מ שרשו מג\"ר דעתיק<sup data-n=\"6214\">103</sup>] וטל הוא בחי' אתעדל\"ע שאין אתעדל\"ת מגעת לשם, וכמו\"כ יובן כאן דקדש ל' הוא באתעדל\"ת אתעדל\"ע והוי' הוא אתעדל\"ע שלמעלה מאתעדל\"ת. ושני הפי' אמת דכתי' ויקרא הוי' הוי'<sup data-n=\"6215\">104</sup> שיש ב' שמות הוי' אחד שם הוי' דסדר השתל' ב' שם הוי' דלמעלה מסדר השתל', מה שפי' הפרדס דקדש למעלה משם הוי' היינו שם הוי' דסדר השתל', ולפי' רבינו דשם הוי' למעלה מקדש היינו שם הוי' דלמעלה מסדר השתל'. וזהו\"ע הציץ שיש בו ב' פי' א' ל' הארה והוא בחי' אור אה\"ר דאהרן כה\"ר ממשיך בנש\"י, ב' ל' ראי' שיומשך עינא דלעילא בעינא דלתתא<sup data-n=\"6216\">105</sup>.",[["6202","91","<b>תפילין . . ומשעבד הלב והמוח</b>: ראה שו\"ע הל' תפילין סכ\"ה, ס\"ה. ובשו\"ע אדה\"ז שם סי\"א. תניא פמ\"א."],["6203","92","<b>תפילין . . המשכת מוחין לז\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370163\" data-slug=\"torah-or\" data-id=\"3901370163\">תו\"א מקץ לה, ג</a>. סה\"מ מלוקט ב' ע' צ."],["6204","93","<b>ומל\"ת הם . . ע\"י השלילה דלא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380067\" data-slug=\"likkutei-torah\" data-id=\"4001380067\">לקו\"ת פקודי ו, ד</a>."],["6205","94","<b>אני חומה ושדי כמגדלות</b>: שה\"ש ח, י."],["6206","95","<b>אני חומה זו תורה</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' א' ואילך. לקו\"ת ואתחנן י, א. סה\"מ תרל\"ח ע' קפב. וש\"נ."],["6207","96","<b>אני חומה מ\"ע . . מל\"ת</b>: ראה גם אוה\"ת תצוה כאן ע' א'תשי. פלח הרמון מג\"א כאן ע' שסה."],["6208","97","<b>שדואג ואחיתופל . . הפורח באויר</b>: חגיגה טו, סע\"ב."],["6209","98","<b>מאויר קדמאה</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 213."],["6210","99","<b>באתעדל\"ת אתעדל\"ע</b>: ראה זהר לך פח, א. מאמר ד\"ה לרוקע נדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' קצד [ובמקביליו ובהנסמן במ\"מ לשם]. מאמרי אדה\"א דברים ח\"א ע' קצח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a> ובהערה 189."],["6211","100","<b>דכנס\"י שאלו שלא כהוגן</b>: ראה תענית ד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381015\" data-slug=\"likkutei-torah\" data-id=\"4001381015\">לקו\"ת האזינו עג, א</a> ואילך. (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381020\" data-slug=\"likkutei-torah\" data-id=\"4001381020\">עד, ב</a>). מאמרי אדה\"א שמות ח\"א ס\"ע א' קצו ואילך. אוה\"ת האזינו ע' א'תרמח."],["6212","101","<b>ויבא כגשם לנו</b>: הושע ו, ג [ושם: ויבוא. ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 218]."],["6213","102","<b>אהי' כטל לישראל</b>: שם יד, ו."],["6214","103","<b>דגשם . . מג\"ר דעתיק</b>: להעיר מלעיל (בחלק המאמרים) מאמר ד\"ה אז ישיר משה ובהערה ד."],["6215","104","<b>ויקרא הוי' הוי'</b>: תשא לד, ו. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370277\" data-slug=\"torah-or\" data-id=\"3901370277\">תו\"א בשלח סא, ד</a> ואילך. (לעיל בחלק המאמרים) מאמר ד\"ה מגילה נקראת פ\"ה. וש\"נ."],["6216","105","<b>עינא דלעילא בעינא דלתתא</b>: ראה זהר אד\"ר נשא קל, א."]]],[2001910554,"<b>ועפ\"ז</b> יובן מ\"ש ויקרא אל משה<sup data-n=\"6217\">106</sup>, וכתי' ויקר אלקים אל בלעם<sup data-n=\"6218\">107</sup>, ויקרא הוא ל' אוקיר אנוש מפז<sup data-n=\"6219\">108</sup>, ויקר דבלעם אין ויקר אלא ל' טומאה<sup data-n=\"6220\">109</sup>, דיקר דמשה ומ\"ש גבי חזקי' ויסב פניו אל הקיר בגימ' כתר<sup data-n=\"6221\">110</sup>, וקרי דבלעם ועמלק שהם ענין א' וקיר ברזל דלעו\"ז הוא גימ' כרת<sup data-n=\"6222\">111</sup> דכמו בקדושה כדי שיומשך מעצמיות המאציל בנאצלים הוא ע\"י ממוצע בחי' כתר<sup data-n=\"6223\">112</sup> כמו\"כ בלעו\"ז שיומשך מקדושה בלעו\"ז הוא ע\"י ממוצע והוא כרת כתר<sup data-n=\"6225\">114</sup> דלעו\"ז<sup data-n=\"6224\">113</sup>, וע\"י כתר דקדושה מדחים כתר דלעו\"ז. וזהו מגלה נקראת באחד עשר בי\"ב כו' בט\"ו<sup data-n=\"6226\">115</sup>, דנס דפורים הי' מחיית עמלק לכן אז גילוי שם הוי' וזהו אחד עשר ו\"ה וט\"ו י\"ה<sup data-n=\"6227\">116</sup> דכתי' כי יד על כס יה<sup data-n=\"6228\">117</sup> אין השם שלם<sup data-n=\"6229\">118</sup>, והמן הי' מזרעו של עמלק<sup data-n=\"6230\">119</sup> ובפורים תלו אותו על העץ<sup data-n=\"6231\">120</sup> לכן הי' אז גילוי שם הוי', אך יש חילוקי' באופני הגילוים כרכים המוקפים חומה<sup data-n=\"6232\">121</sup> מימות יהושע בן נון קורין בט\"ו ולכאו' מה שייך זה ליהושע והלא משה הלוחם עם עמלק וכתי' בחר לנו אנשים<sup data-n=\"6233\">122</sup> הם אנשי משה, הענין הוא דגם יהושע הוא לעו\"ז דעמלק פני יהושע כפני לבנה<sup data-n=\"6234\">123</sup> שהוא בחי'<sup data-n=\"6236\">125</sup> מל'<sup data-n=\"6235\">124</sup> קיר דקדושה, לכן כשכבש את הארץ כרכים המוקפים חומה<sup data-n=\"6237\">126</sup> המשיך בחי' י\"ה שבעצם הם גבוהים יותר דמוקפים חומה הוא בחי' סוכ\"ע מקור המקיפים דמבינה<sup data-n=\"6238\">127</sup>, וכפרים ועירות גדולות קורין בי\"א שנמשך ג\"כ בחי' י\"ה אך כמו שמלובש בו\"ה. וזהו מגלה נקראת באחד עשר כו' ובט\"ו דלכרכים המוקפים חומה כו' קורין בט\"ו הוא בחי' י\"ה וכפרים נמשך ג\"כ בחי' י\"ה אך כמו שמלובש בו\"ה כו'.",[["6217","106","<b>ויקרא אל משה</b>: ויקרא א, א."],["6218","107","<b>ויקר אלקים אל בלעם</b>: בלק כג, ד."],["6219","108","<b>אוקיר אנוש מפז</b>: ישעי' יג, יב."],["6220","109","<b>ויקר אלא ל' טומאה</b>: ראה רש\"י ולקח טוב בלק שם. ב\"ר פנ\"ב, ה. ויק\"ר פ\"א, יג."],["6221","110","<b>דיקר דמשה . . הקיר בגימ' כתר</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 245."],["6222","111","<b>וקרי . . וקיר . . גימ' כרת</b>: ראה גם לעיל בהמאמר שם."],["6223","112","<b>ממוצע בחי' כתר</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תס. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540828\" data-slug=\"torat-chaim\" data-id=\"2300540828\">תו\"ח שמות ח\"א יא, ג</a>. וש\"נ."],["6225","114","<b>כרת כתר</b>: נסמן לעיל שם הערה 244."],["6224","113","<b>ממוצע . . כרת כתר דלעו\"ז</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 247."],["6226","115","<b>מגילה נקראת . . בט\"ו</b>: ראה מגילה פ\"א, מ\"א."],["6227","116","<b>אחד עשר ו\"ה וט\"ו י\"ה</b>: של\"ה תצוה שכט, א. פ' זכור של, ב. (לעיל בחלק המאמרים) מאמר ד\"ה מגילה נקראת ובהערה 252."],["6228","117","<b>כי יד על כס יה</b>: בשלח יז, טז."],["6229","118","<b>אין השם שלם</b>: ראה תנחומא ס\"פ תצא. רש\"י ולקח טוב ס\"פ בשלח. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231268\" data-slug=\"likkutei-sichot\" data-id=\"1300231268\">לקו\"ש</a> י\"ג סיון כרך כג ע' 268 הערה 33."],["6230","119","<b>והמן . . של עמלק</b>: אסתר ג, א ובתרגום שם. ראה לקו\"ש פ' זכור כרך ג ע' 913 הערות 1-2."],["6231","120","<b>ובפורים תלו אותו על העץ</b>: תלאוהו ביום ב' דפסח — ראה שו\"ע אדה\"ז הל' פסח סת\"צ, ס\"ב."],["6232","121","<b>כרכים המוקפים חומה</b>: ראה מגילה פ\"א, מ\"א."],["6233","122","<b>בחר לנו אנשים</b>: בשלח יז. ט. ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470193\" data-slug=\"or-hatorah-hb\" data-id=\"8316470193\">אוה\"ת בשלח ע' תרסא</a>."],["6234","123","<b>פני יהושע כפני לבנה</b>: ב\"ב עה, סע\"א. ראה מאמרי אדה\"א נ\"ך ע' תסא ואילך."],["6236","125","<b>לבנה שהוא בחי' מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"ב מערכת לבנה."],["6235","124","<b>יהושע . . מל'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540749\" data-slug=\"torat-chaim\" data-id=\"2300540749\">תו\"ח בשלח ח\"א קנח, ב</a>."],["6237","126","<b>כשכבש . . המוקפים חומה</b>: ראה הלשון (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 263."],["6238","127","<b>מקור המקיפים דמבינה</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"ג. לקו\"ת להאריז\"ל תהלים סנ\"ג."]]],[2001910555,"<h3>קא מיפלגי במתיבתא דרקיע</h3>\n<b>ש\"פ תזריע</b>\n<b>קא</b> מיפלגי במתיבתא דרקיע<sup data-n=\"6239\">1</sup>, בהרת קדמה לשער לבן טמא שער לבן קדמה לבהרת טהור ספק קוב\"ה אומר טהור וכולהו מתיבתא דרקיע אמרי טהור<sup data-n=\"6241\">3</sup><sup data-n=\"6240\">2</sup>, וצ\"ל איך שייך דמתיבתא דרקיע שהם נבראים יפלגו עם הקב\"ה דהקב\"ה אומר טהור והם אומרים טמא, וכמו\"כ צ\"ל מ\"ש בזהר קוב\"ה אתי לאשתעשע<sup data-n=\"6242\">4</sup> עם צדיקיא בגינתא דעדן איך שייך דקוב\"ה בא לשמוע פנימיות התורה מצדיקים דקוב\"ה אתי לאשתעשע (בלקו\"ת שה\"ש בד\"ה באתי לגני<sup data-n=\"6243\">5</sup> מבואר מאחר שהכל הי' גלוי וידוע לפניו<sup data-n=\"6244\">6</sup> ית' מקודם לכן וא\"כ מהו השעשועים כ\"כ יעו\"ש, ומ\"ש לשמוע פנימיות התורה כו' אפ\"ל דקושטא דמילתא כן דבג\"ע עיקר הלימוד ברוחניות דהלכה<sup data-n=\"6245\">7</sup> וכמבואר במ\"א באריכות וזה נק' פנימיות התורה וכמ\"ש בלקו\"ת בד\"ה ולא תשבית מלח<sup data-n=\"6246\">8</sup> כו'). והנה צלה\"ק תחילה מהו הקב\"ה<sup data-n=\"6247\">9</sup> ומתיבתא דרקיע וצדיקים שיושבים שם, והענין דהנה בגמ' ובמדרש ובזהר כינו את השי\"ת בשם הקב\"ה וצ\"ל והלא שם זה לא נמצא בתורה כ\"א שם אל אלקים הוי', ומשה אמר ואמרו לי מה שמו מה אומר אליהם כו' וא\"ל אהי'<sup data-n=\"6248\">10</sup> ואמרז\"ל לפי מעשיו הוא נק'<sup data-n=\"6249\">11</sup>, אבל שם הקב\"ה מהו (דמה שנק' רחום חנון<sup data-n=\"6250\">12</sup> וכדומה הוא כמארז\"ל לפי מעשיו כו' אבל כו').\n<b>וצ\"ל</b> ענין קדוש וברוך, הנה קדוש הוא שא\"ס קדוש ומובדל<sup data-n=\"6251\">13</sup> מגדר עולמות לא כמו הנשמה שמתפעלת ממקרי הגוף<sup data-n=\"6252\">14</sup> מפני שמתלבשת אבל למעלה כתי' אני הוי' לא שניתי<sup data-n=\"6253\">15</sup> שלא יש שום שינוי בין קודם הבריאה לאחר הבריאה, אתה הוא קודם שנבה\"ע<sup data-n=\"6254\">16</sup> ואתה הוא לאחר שנבה\"ע, דכללות העולמות אינם שייכים שיפעלו",[["6239","1","<b>קא מיפלגי במתיבתא דרקיע</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ."],["6241","3","<b>טהור</b>: וכ\"ה לקמן הנחה ד\"ה זאת תהי' תורת המצורע על יד הערה 10. ואוצ\"ל (כמו שהובא בסמוך): טמא."],["6240","2","<b>קא מיפלגי . . אמרי טהור</b>: ראה ב\"מ פו, א."],["6242","4","<b>קוב\"ה אתי לאשתעשע</b>: ראה זהר אחרי סז, ב. לך עז, א. (לעיל בחלק המאמרים) בהמאמר כאן הערה 5."],["6243","5","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381256\" data-slug=\"likkutei-torah\" data-id=\"4001381256\">לקו\"ת שה\"ש</a> בד\"ה באתי לגני</b>: לא, ד ואילך."],["6244","6","<b>גלוי וידוע לפניו</b>: ע\"פ שבת נה, א. ערובין יג, ב."],["6245","7","<b>דבג\"ע . . ברוחניות דהלכה</b>: ראה גם לקו\"ת ואתחנן ו, ב ואילך. סהמ\"צ להצ\"צ ע' 334. סה\"מ תרל\"ח ע' קמו. וש\"נ. ע' קסא ואילך. וש\"נ."],["6246","8","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380095\" data-slug=\"likkutei-torah\" data-id=\"4001380095\">לקו\"ת</a> בד\"ה ולא תשבית מלח</b>: ויקרא ה, ב ואילך."],["6247","9","<b>מהו הקב\"ה</b>: אוצ\"ל: מהו שם הקב\"ה. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 6."],["6248","10","<b>ואמרו לי מה שמו . . אהי'</b>: שמות ג, יג. יד."],["6249","11","<b>לפי מעשיו הוא נק'</b>: ראה שמו\"ר פ\"ג, ו. תנחומא שמות כ. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380299\" data-slug=\"likkutei-torah\" data-id=\"4001380299\">לקו\"ת ויקרא בהוספות נא, ד</a>. סהמ\"צ להצ\"צ קטז, ב."],["6250","12","<b>רחום חנון</b>: ראה תשא לד, ו."],["6251","13","<b>קדוש . . ומובדל</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא פמ\"ו (סו, א</a>). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380210\" data-slug=\"likkutei-torah\" data-id=\"4001380210\">לקו\"ת אמור לא, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540089\" data-slug=\"torat-chaim\" data-id=\"2300540089\">תו\"ח וארא ח\"א נא, ד</a> ובהערה 10. (לעיל בחלק המאמרים) בהמאמר כאן הערה 6."],["6252","14","<b>הנשמה שמתפעלת ממקרי הגוף</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב (ס, ב</a>). שער היחוד והאמונה פ\"ז (פג, ב). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370061\" data-slug=\"torah-or\" data-id=\"3901370061\">תו\"א וירא יג, ג</a>. לקו\"ת שם. ואתחנן ד, ב. סה\"מ תרל\"ד ס\"ע צח ואילך. תרל\"ט ח\"א ע' שמז."],["6253","15","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם לקו\"ת אמור שם ואילך. סה\"מ תר\"ם ח\"א ע' שסט ואילך. וש\"נ."],["6254","16","<b>אתה הוא קודם שנבה\"ע</b>: ראה נוסח תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."]]],[2001910556,"שינוי ח\"ו, דבחי' זו הוא בחי' סוכ\"ע שסובב ומקיף לבד (נר' דאין ר\"ל שסובב ומקיף למעלה דמבואר בלקו\"ת פ' נצבים ד\"ה שוש אשיש<sup data-n=\"6255\">17</sup> דאין הפי' סובב מלמעלה אלא שהוא בהעלם וא\"כ אין העולמות פועלים שום שינוי ח\"ו, דממכ\"ע הוא השפעה בפנימיות וכמשית\"ל אי\"ה לכן לפ\"ע העולם ה\"ז שינוי אבל בחי' סוכ\"ע הוא שוה בכל העולמות וכמו בחי' מחה\"ק<sup data-n=\"6256\">18</sup> שכולל כל העולמות בהשוואה אחת אצי' ועשי' שוין ונק' אור כללי<sup data-n=\"6257\">19</sup> וכמבו' במ\"א) אך מ\"מ נק' סובב כל עלמי\"ן ששייך קצת להעולמות וכמו השמים שמקיף להארץ וגבוה הרבה מהארץ וכמ\"ש שמים לרום<sup data-n=\"6258\">20</sup>, כגבוה שמים מארץ<sup data-n=\"6259\">21</sup>, ומ\"מ הוא במדה וגבול דהארץ מקבל מהשמים וכמ\"ש ממגד תבואת שמש<sup data-n=\"6260\">22</sup> וממגד גרש ירחים ואם לא הי' מוגבל איך יקבל מהשמים, ואם הי' רצון הבורא בא\"א<sup data-n=\"6261\">23</sup> הי' בא\"א ג\"כ, אבל כפי שהי' הרצון שיקבל בכך וכך א\"כ צ\"ל הריחוק ג\"כ במדה וכמארז\"ל מן הארץ לרקיע<sup data-n=\"6262\">24</sup> ת\"ק שנה כו', וכמו\"כ יובן בענין הסוכ\"ע הנ\"ל שיש לו ערך להעולם (דגם בחי' אור הכללי הנ\"ל הרי הי' בו בכלל כל העולמות שנתהווה אח\"כ בפרט וכמו\"כ יובן עד רום המעלות) ובחי' זו נק' קדוש ו', דיש קדוש וקדש<sup data-n=\"6263\">25</sup>, קדש הוא קדש מילי' בגרמי'<sup data-n=\"6264\">26</sup> שאף שלא היו העולמות כלל שייך בחי' זו (אפ\"ל הוא בחי' א\"ס שלפני הצמצום הראשון<sup data-n=\"6265\">27</sup> שהי' אוא\"ס ממלא את כל מקום החלל<sup data-n=\"6266\">28</sup> וע' בד\"ה ביום ההוא יגלח אד'<sup data-n=\"6267\">29</sup> בתער השכירה, וע' בש\"ת ח\"א ד\"ה אחרי ה' אלקיכם תלכו<sup data-n=\"6268\">30</sup>), ובחי' קדוש ו' הוא ההמשכה מבחי' כתר לז\"א, ואות",[["6255","17","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380915\" data-slug=\"likkutei-torah\" data-id=\"4001380915\">לקו\"ת</a> פ' נצבים ד\"ה שוש אשיש</b>: מט, רע\"א. וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא פמ\"ח סז, סע\"ב</a> (ובמ\"מ הגהות והע\"ק לשם). מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשלא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550287\" data-slug=\"torat-chaim\" data-id=\"2300550287\">תו\"ח ויקהל ח\"ב שפח, ב</a>. וש\"נ. פלח הרמון תזריע ע' קס. וש\"נ. (לעיל בחלק המאמרים) מאמר ד\"ה הים ראה וינוס על יד הערה 47."],["6256","18","<b>מחה\"ק</b>: ראה גם מאמרי אדה\"ז מארז\"ל ס\"ע קלז. מאמרי אדה\"א דברים ח\"ג ס\"ע תתפז (ובהנסמן שם ע' תתפח)."],["6257","19","<b>אור כללי</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830084\" data-slug=\"or-hatorah-hb\" data-id=\"8158830084\">אוה\"ת ענינים ע' פד</a> (בלק ע' תתקסח): ”כן אמר רבינו הגדול נ\"ע בשם הרב המגיד ממעזריטש נ\"ע שהי' מרגלא בפומי' דבחי' א\"ק הוא אור כללי\" (סהמ\"צ להצ\"צ ע' 116. ע' סח. ע' 186) ”וכן מצאתי ג\"כ בפירוש לתלמיד ר' ישראל סרוג תלמיד האריז\"ל\"."],["6258","20","<b>שמים לרום</b>: משלי כה, ג."],["6259","21","<b>כגבוה שמים מארץ</b>: ע\"פ ישעי' נה, ט. תהלים קג, יא [ראה גם סה\"מ תר\"ם ח\"א ע' ב]."],["6260","22","<b>ממגד תבואת שמש</b>: ברכה לג, יד [ושם: וממגד] ובפרש\"י שם. ראה סידור שער המילה קמב, א [אוה\"ת שבועות ריש ע' קי. סידור ס\"ע שיג ואילך]. מאמרי אדה\"ז הנחות הר\"פ ע' קלה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670200\" data-slug=\"torat-chaim\" data-id=\"2300670200\">תו\"ח בראשית כא, ג</a> ואילך. מאמרי אדה\"א במדבר ח\"ג ע' א'קצ. דברים ח\"ד ע' א'תמא. נ\"ך ע' קכב וע' קכז ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830004\" data-slug=\"or-hatorah-hb\" data-id=\"8158830004\">אוה\"ת</a> על מארז\"ל ע' ד [שלח ע' תקל]."],["6261","23","<b>בא\"א</b>: באופן אחר."],["6262","24","<b>מן הארץ לרקיע</b>: ראה חגיגה יג, א. ראה גם לעיל הנחה ד\"ה ועבדתם את ה\"א ובהערה 44."],["6263","25","<b>קדוש ו' . . וקדש</b>: ראה זהר אמור צג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380432\" data-slug=\"likkutei-torah\" data-id=\"4001380432\">לקו\"ת בהעלותך ל, סע\"ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380920\" data-slug=\"likkutei-torah\" data-id=\"4001380920\">נצבים נ, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">יו\"כ סט, ב</a> ואילך. שה\"ש כא, ב ואילך. לו, ד. אוה\"ת תזריע כרך ד ע' א'נג."],["6264","26","<b>קדש מילי' בגרמי'</b>: זהר שם צד, ב."],["6265","27","<b>הצמצום הראשון</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב."],["6266","28","<b>ממלא את כל מקום החלל</b>: ראה גם שעה\"י קיד, א הערה 17. סה\"מ תר\"ם ח\"א ע' קכח. וש\"נ."],["6267","29","<b>בד\"ה ביום ההוא יגלח אד'</b>: ראה מאמרי אדה\"ז נביאים ע' מח ואילך. אוה\"ת ישעי' כרך ב ע' תשסט ואילך."],["6268","30","<b>בש\"ת ח\"א . . תלכו</b>: שערי תשובה שער התפלה כו, א ואילך."]]],[2001910557,"ו' הוא תמונת שערה<sup data-n=\"6270\">32</sup><sup data-n=\"6269\">31</sup> והשערות אף שהם חיות מצומצם מ\"מ יונקים מעצם המוחין<sup data-n=\"6271\">33</sup> (ע' במאו\"א ע' ק' ס\"ז קדוש בעתיקא (ע' שם בע' ע' סנ\"ה) ת\"י נימין גי' קדוש והוא בא\"א עכ\"ל, וע' בד\"ה ביום ההוא כו' ומ\"ש ת\"י נימין הוא כמ\"ש באד\"ר דקך\"ח ע\"ב וכל קוצא וקוצא אית בי' ת\"י נימי דשערי כחושבן קדוש עכ\"ל וכמ\"ש ביא\"נ<sup data-n=\"6272\">34</sup> שם, וכ\"ע<sup data-n=\"6273\">35</sup> במאו\"א שם קדוש<sup data-n=\"6274\">36</sup> בת\"ת בקבלתו מחכ' הנק' קדש כו' עכ\"ל, ועי\"ל כמ\"ש בלקו\"ת ד\"ה קא מיפלגי<sup data-n=\"6275\">37</sup> כו' דת\"ת בקו האמצעי ומקבל מהכתר לכן נק' קדוש וז\"ש קדוש ו' המשכה מכתר לז\"א ונק' שניהם קדוש ע' בלקו\"ת ד\"ה הנ\"ל וכמשנת\"ל), ועל ל' הקבלה ו' הוא הקו<sup data-n=\"6276\">38</sup> שנמשך מא\"ס ונק' בזהר חוטא יקירא קדישא<sup data-n=\"6277\">39</sup>.\n<b>ברוך</b> הוא ההמשכה בפנימיות וכמ\"ש בגמ' מה הקב\"ה ממלא כל העולם כך הנשמה<sup data-n=\"6278\">40</sup> ממלא את כל הגוף, ובמ\"ת אי' מה הנשמה<sup data-n=\"6279\">41</sup> ממלא את כל הגוף כך הקב\"ה ממלא את כל העולמות ואין נ\"מ בהשינוי, ופי' ברוך ל' בריכות המים<sup data-n=\"6280\">42</sup> וכמו המבריך את הגפן<sup data-n=\"6281\">43</sup> שמטה אותו שממשיכו למטה. והנה בתי' ברוך יש ב' פי'<sup data-n=\"6282\">44</sup>, הא' שהוא מקור הברכות וכמ\"ש בפרד\"ס<sup data-n=\"6283\">45</sup> ברו\"ך ר\"ת ראש ומקור<sup data-n=\"6284\">46</sup> כל ברכה<sup data-n=\"6285\">47</sup> והוא בחי' יסוד אבא<sup data-n=\"6286\">48</sup>, ב' כמ\"ש והמלך שלמה ברוך<sup data-n=\"6287\">49</sup> שנתברך פי' מקבל הברכה, ובמלך",[["6270","32","<b>שערה</b>: אולי כתוב: שער."],["6269","31","<b>ו' הוא תמונת שערה</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה להבין וכו' בענין הציץ ובהערה 166."],["6271","33","<b>והשערות . . יונקים מעצם המוחין</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370367\" data-slug=\"torah-or\" data-id=\"3901370367\">תו\"א תצוה פב, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370490\" data-slug=\"torah-or\" data-id=\"3901370490\">קי, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380526\" data-slug=\"likkutei-torah\" data-id=\"4001380526\">לקו\"ת קרח נג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380871\" data-slug=\"likkutei-torah\" data-id=\"4001380871\">תצא לח, סע\"ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380874\" data-slug=\"likkutei-torah\" data-id=\"4001380874\">לט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381275\" data-slug=\"likkutei-torah\" data-id=\"4001381275\">שה\"ש לו, ד</a>. לעיל הנחה ד\"ה להבין וכו' ב' פי' בציץ הערה 19."],["6272","34","<b>ביא\"נ</b>: ביאיר נתיב — ושם: דף קכ\"ט ע\"ב. ולכאורה צ\"ל כבפנים."],["6273","35","<b>וכ\"ע</b>: וכתב עוד."],["6274","36","<b>קדוש</b>: במאו\"א: וכן."],["6275","37","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת</a> ד\"ה קא מיפלגי</b>: תזריע כב, ג."],["6276","38","<b>ו' הוא הקו</b>: ראה גם סה\"מ תרכ\"ו ע' רו ואילך. תרל\"ב ח\"א ריש ע' רלג. תר\"ם ח\"א ע' רנה."],["6277","39","<b>הקו . . בזהר חוטא יקירא קדישא</b>: אד\"ר נשא קלד, א."],["6278","40","<b>מה הקב\"ה . . כך הנשמה</b>: ראה ברכות י, א. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשצא וע' תשצה."],["6279","41","<b>ובמ\"ת אי' מה הנשמה</b>: ובמדרש תהלים — ראה שם קג, א. שע\"ת כט, א."],["6280","42","<b>ברוך ל' בריכות המים</b>: ע\"פ קהלת ב, ו. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה קדש ישראל לה' רפ\"ג. וש\"נ."],["6281","43","<b>המבריך את הגפן</b>: כלאים פ\"ז, מ\"א. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370171\" data-slug=\"torah-or\" data-id=\"3901370171\">תו\"א מקץ לז, ג</a>. סה\"מ תר\"ם ח\"א ע' רלח. וש\"נ."],["6282","44","<b><a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">בתי' ברוך יש ב</a>' פי'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת תזריע כאן כב, ג</a>. שה\"ש כח, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תמה. וש\"נ. (לעיל בחלק המאמרים) בהמאמר כאן פ\"ב ובהנסמן בהערה 1."],["6283","45","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["6284","46","<b>בפרד\"ס ברו\"ך ר\"ת ראש ומקור</b>: בלקו\"ת תזריע כאן מציין [שעה\"כ שכ\"ג, פ\"ב] בערך ברוך. מת\"ז ת\"ע קכ, ב. ראה גם פרדס שער אם הא\"ס הוא הכתר ש\"ג, פ\"ה."],["6285","47","<b>ברכה</b>: בת\"ז ובפרדס שם: ברכות. אבל כ\"ה גם בלקו\"ת שם."],["6286","48","<b>והוא בחי' יסוד אבא</b>: פע\"ח שער הברכות ש\"ב, פ\"א. מאו\"א מערכת ברוך אות לט."],["6287","49","<b>והמלך שלמה ברוך</b>: מלכים-א ב, מה. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש כח, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540841\" data-slug=\"torat-chaim\" data-id=\"2300540841\">תו\"ח בשלח ח\"א קס, ג</a>. וש\"נ."]]],[2001910558,"שלמה יש ג\"כ ב' פי' א' שהוא בחי' מל'<sup data-n=\"6288\">50</sup>, ב' בחי' יסוד<sup data-n=\"6289\">51</sup> שמקבל ומקשר<sup data-n=\"6290\">52</sup>, ושלמה גימ' שע\"ה והן שע\"ה נהורין<sup data-n=\"6291\">53</sup> כמו שהם בז\"א והיסוד מקבל ומקשר, וזהו מ\"ש ברכו את ה' המבורך<sup data-n=\"6292\">54</sup> ומדקדקי' הפשטנים מה שייך ברכו את ה' לכן פי' דשם הוי' הוא מקור כל הברכות אך זה אינם מדקדקים מהו המבורך, אך פי' המבורך שמקבל הברכה, וזהו חייב אדם לברך<sup data-n=\"6293\">55</sup> מאה ברכות בכ\"י הוא בחי' השפעה בפנימיות, ולכן בריאת העולמות הי' בבי\"ת אף דאל\"ף למעלה מב' אי' בזהר דאל\"ף ר\"ת ארור<sup data-n=\"6294\">56</sup> ויוכל לקבל גם ארור כנען<sup data-n=\"6295\">57</sup> לכן הי' ברה\"ע בבי\"ת שהוא ר\"ת ברכה<sup data-n=\"6296\">58</sup> (ע' בלקו\"ת ד\"ה קא מיפלגי<sup data-n=\"6297\">59</sup> כו' בשם הזהר<sup data-n=\"6298\">60</sup> שהוא בחי' מל' וא\"כ הו\"ע חותם בברוך<sup data-n=\"6299\">61</sup> וכ\"כ שם<sup data-n=\"6300\">62</sup> ע' בתו\"א ד\"ה להבין ענין הברכות<sup data-n=\"6301\">63</sup>), וזהו איהו ברוך ואיהי ברכה<sup data-n=\"6302\">64</sup> בחי' מל' דכנס\"י<sup data-n=\"6303\">65</sup> כלי לקבל הברכה וכמו המוח שהוא כלי לקבל השכל בפנימיות דאפשר לכתוב שכל ביד ג\"כ אך הוא בדרך מעבר אבל בפנימיות הוא במוח דוקא וכמו\"כ הכלי להברכה הם כנס\"י, וא\"כ קדוש וברוך קדוש הוא סוכ\"ע וברוך ממכ\"ע, והקב\"ה הוא יחוד סוכ\"ע וממכ\"ע<sup data-n=\"6304\">66</sup>, וז\"ש בזהר קוב\"ה דאתכלל<sup data-n=\"6305\">67</sup> מאתר עילאה סדכ\"ס ברזא דמאה ברכאן ופי' המק\"מ קוב\"ה מל' דאתכלל מאתר עילאה בחי' קדוש ו'<sup data-n=\"6306\">68</sup> הנ\"ל וישראל בכוחם להמשיך בחי' זו וזהו ענין ג\"פ קדוש<sup data-n=\"6307\">69</sup> כו' הוי' צבאות. וזהו והייתם קדושים כי קדוש אני<sup data-n=\"6308\">70</sup>, ולכאו' מהו הנתינות טעם, אך הפי' מפני שצריכים להמשיך בחי' קדוש אני בחי' סוכ\"ע לכן והייתם קדושים שתהיו כלי כו'. וזהו שכינו רז\"ל",[["6288","50","<b>ובמלך שלמה . . מל'</b>: ראה ע\"ח שער פנימיות וחצוניות ש\"מ, דרוש יג."],["6289","51","<b>ובמלך שלמה . . יסוד</b>: ראה זהר רע\"מ ויקרא ד, א. מאו\"א מערכת שלמה אות מה. המשך מים רבים תרל\"ו פקל\"ז. תרל\"ה כאן ריש ע' רכג. ע' רד ואילך."],["6290","52","<b>יסוד שמקבל ומקשר</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן פ\"ב בשולי הגליון ובהנסמן שם."],["6291","53","<b>ושלמה גימ' שע\"ה . . נהורין</b>: ראה לעיל שם ובהערה ז."],["6292","54","<b>ברכו את ה' המבורך</b>: נוסח התפלה. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380778\" data-slug=\"likkutei-torah\" data-id=\"4001380778\">לקו\"ת עקב טז, א</a>."],["6293","55","<b>חייב אדם לברך</b>: מנחות מג, ב."],["6294","56","<b>דאלף ר\"ת ארור</b>: זהר ויגש רה, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380793\" data-slug=\"likkutei-torah\" data-id=\"4001380793\">לקו\"ת פ' ראה יט, ב</a>. סה\"מ תר\"ם ח\"א ע' שו. וש\"נ."],["6295","57","<b>ארור כנען</b>: נח ט, כה. ראה גם סה\"מ תרל\"א ח\"א ע' סב."],["6296","58","<b>בבי\"ת שהוא ר\"ת ברכה</b>: ראה זהר ויגש שם. בהקדמה ג, סע\"א (צויין ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כאן כב, ג</a>)."],["6297","59","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת</a> ד\"ה קא מיפלגי</b>: תזריע כב, ג."],["6298","60","<b>בשם הזהר</b>: בלקו\"ת שם: ”ועיין בזהר ר\"פ בראשית ד\"ג סע\"א בענין אות ב' דהוא סימן ברכה ובזהר הרקיע שם דהוא בחי' מלכות\" עיי\"ש."],["6299","61","<b>חותם בברוך</b>: ירושלמי ברכות פ\"א, ה\"ה קרוב לסופה."],["6300","62","<b>וכ\"כ שם</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380171\" data-slug=\"likkutei-torah\" data-id=\"4001380171\">לקו\"ת תזריע כב, ד</a>."],["6301","63","<b>ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370024\" data-slug=\"torah-or\" data-id=\"3901370024\">תו\"א</a> ד\"ה להבין ענין הברכות</b>: בראשית ו, ג."],["6302","64","<b>איהו ברוך ואיהי ברכה</b>: ראה זהר תרומה קסב, א. ואתחנן רסד, ב. סידור ערב שבת קסה, סע\"ב ואילך. שער הל\"ג בעומר שה, ד."],["6303","65","<b>מל' דכנס\"י</b>: ראה זהר בלק קצז, א."],["6304","66","<b>והקב\"ה הוא יחוד סוכ\"ע וממכ\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381151\" data-slug=\"likkutei-torah\" data-id=\"4001381151\">לקו\"ת שה\"ש ה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">כא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381290\" data-slug=\"likkutei-torah\" data-id=\"4001381290\">מ, ג</a>."],["6305","67","<b>בזהר קוב\"ה דאתכלל</b>: ח\"ש קכג, א."],["6306","68","<b>בחי' קדוש ו'</b>: במק\"מ: הוא אריך. ראה (לעיל בחלק המאמרים) בהמאמר כאן ספ\"ב."],["6307","69","<b>ענין ג\"פ קדוש</b>: ישעי' ו, ג. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380217\" data-slug=\"likkutei-torah\" data-id=\"4001380217\">לקו\"ת אמור לב, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380222\" data-slug=\"likkutei-torah\" data-id=\"4001380222\">לד, א</a> ואילך."],["6308","70","<b>והייתם קדושים כי קדוש אני</b>: שמיני יא, מד."]]],[2001910559,"אותו בשם הקב\"ה מפני שכולל כללות השתל', דשם אל בחסד לבד ושם אלקים בגבו' והם שמות פרטים<sup data-n=\"6309\">71</sup>, אבל שם הקב\"ה כולל כללות השתל'.\n<b>וענין</b> מתיבתא דרקיע הנה צ\"ל מהו רקיע דיש ז' רקיעים<sup data-n=\"6310\">72</sup> ורקיע זה למעלה מכולם<sup data-n=\"6311\">73</sup>, ועז\"נ ועל ראשי החיה<sup data-n=\"6312\">74</sup> דחיון עילאין<sup data-n=\"6313\">75</sup> רקיע כעין הקרח כו'. דהנה יש אור מים רקיע<sup data-n=\"6314\">76</sup> דמע\"ב<sup data-n=\"6315\">77</sup> כתי' ה\"פ אור<sup data-n=\"6316\">78</sup> וה\"פ מים<sup data-n=\"6317\">79</sup> וה\"פ רקיע<sup data-n=\"6318\">80</sup>, ובנפש האדם אור הוא המשכיל מקור ששם אין השכל מושג ואפי' אינו מורגש, ואח\"כ כשבא לידי השכלה והוא ברק המבריק<sup data-n=\"6319\">81</sup> נק' מים, דמים יורדים מגבוה לנמוך<sup data-n=\"6320\">82</sup> פי' מגבוה מהמשכיל ששם אינו מורגש כלל לנמוך להשגה והבנה שיושג השכל, ומים ניידי<sup data-n=\"6321\">83</sup> והיינו כמו שהשכל עדיין מרופף שיוכל להטותו לכל צד<sup data-n=\"6322\">84</sup>, דכל ענין השכל הוא שיכולים להטותו, וכמ\"ש אמחה את האדם<sup data-n=\"6323\">85</sup> אשר בראתי כו' כי יצר מחשבות לבו<sup data-n=\"6324\">86</sup> רק רע כל היום, כי נחמתי אשר עשיתיו<sup data-n=\"6325\">87</sup>, ואחר המבול כתי' וירח את ריח הנחוח ויאמר לא אוסיף עוד לקלל את האדמה כו' כי יצר<sup data-n=\"6326\">88</sup> לב האדם רע מנעוריו הרי אותו השכל שחייב קודם לחוב חייב אח\"כ לזכות, וכשהשכל עדיין בברק המבריק נק' מים דניידי שהוא מרופף, וכשבא לידי השגה והבנה נק' רקיע שהוא כשנגלד וכמ\"ש רקיע כעין הקרח דבר קשה וגוש, ולמעלה הם כח\"ב אור בחי' כתר מים חכ' רקיע בינה. והנה על רקיע זה כתי' מבטן מי יצא הקרח<sup data-n=\"6327\">89</sup>, מי הוא דבר שאינו מושג<sup data-n=\"6328\">90</sup>, וכמ\"ש מי יתן מציון",[["6309","71","<b>דשם אל . . אלקים . . פרטים</b>: ראה גם לעיל הנחה ד\"ה ועבדתם את ה\"א הערות 96-97. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כאן כג, ג</a>. סה\"מ תר\"ם ח\"א ע' רלא ואילך."],["6310","72","<b>ז' רקיעים</b>: חגיגה יב, ב. ראה סה\"מ תרל\"ח ע' קיז הערה 431."],["6311","73","<b>ורקיע זה למעלה מכולם</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן רפ\"ג ובהנסמן שם."],["6312","74","<b>ועל ראשי החיה</b>: יחזקאל א, כב [ושם: ודמות על]. ראה סה\"מ תרל\"ט ח\"א ע' קס וע' רסד."],["6313","75","<b>דחיון עילאין</b>: ראה להלן הערה 116."],["6314","76","<b>אור מים רקיע</b>: ראה זהר תרומה קלו, ב. קסז, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540634\" data-slug=\"torat-chaim\" data-id=\"2300540634\">תו\"ח שמות ח\"א לג, ג</a>. וש\"נ. סה\"מ תרל\"ח ע' קמג ואילך. ע' קסא ואילך ובהנסמן שם."],["6315","77","<b>דמע\"ב</b>: אוצ\"ל: דבמע\"ב."],["6316","78","<b>ה\"פ אור</b>: בראשית א, ג-ה."],["6317","79","<b>וה\"פ מים</b>: שם א, ו-ז."],["6318","80","<b>וה\"פ רקיע</b>: שם א, ו-ח."],["6319","81","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק אגה\"ק סוסט\"ו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670214\" data-slug=\"torat-chaim\" data-id=\"2300670214\">תו\"ח בראשית י, א</a> ובהערה 4. סה\"מ תרל\"ח ע' פא. וש\"נ. תר\"ם ח\"ב ע' תצג. וש\"נ. (לעיל בחלק המאמרים) מאמר ד\"ה להבין וכו' זאת תהי' תורת המצורע על יד הערה 113. לקמן הנחה ד\"ה כי תבואו וכו' ושבתה הארץ על יד הערה 63. (בחלק ההנחות) הנחה ד\"ה בעשרה מאמרות נברא העולם על יד הערה 36."],["6320","82","<b>דמים יורדים מגבוה לנמוך</b>: ראה תענית ז, א."],["6321","83","<b>ומים ניידי</b>: ראה ערובין מו, א."],["6322","84","<b>שהשכל . . להטותו לכל צד</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה להבין וכו' בענין הציץ ובהערה 232."],["6323","85","<b>אמחה את האדם</b>: בראשית ו, ז."],["6324","86","<b>כי יצר מחשבות לבו</b>: שם ו, ה [ושם: וכל יצר — הלשון שבפנים: קהלת זוטא פ\"ב פסוק כג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541017\" data-slug=\"torat-chaim\" data-id=\"2300541017\">תו\"ח בשלח ח\"א קפא, ג</a>. המשך תער\"ב ח\"ב ע' תתפא. ח\"ג ע' א'רלד]."],["6325","87","<b>כי נחמתי אשר עשיתיו</b>: שם ו, ז [ושם: כי עשיתם]."],["6326","88","<b>וירח . . לא אוסיף . . כי יצר</b>: נח ח, כא [בדילוגים]."],["6327","89","<b>מבטן מי יצא הקרח</b>: איוב לח, כט. ראה זהר לך פה, סע\"ב. סה\"מ תרל\"ה כאן ע' רכה בהערה."],["6328","90","<b>מי הוא דבר שאינו מושג</b>: ראה סה\"מ עזר\"ת כאן ע' קפ: ובזהר [תרומה קלט, ב] אי' מי הוא טמירא דכל טמירין דלא אתייעדא ולא אתגלי'."]]],[2001910560,"ישועת ישראל<sup data-n=\"6329\">91</sup>, מי גילה לבני רז זה<sup data-n=\"6330\">92</sup>. והענין דכתי' שאו מרום עיניכם וראו מי ברא אלה<sup data-n=\"6331\">93</sup> פי' אלה הם ו\"ק<sup data-n=\"6332\">94</sup>, ויש ו\"ק רוחנים ויש ו\"ק גשמים<sup data-n=\"6333\">95</sup>, ואלה הוא גילוי ולפי שיש כמה מדרי' בו\"ק ו\"ק דעשי' ו\"ק דיצי' ו\"ק דבריאה ו\"ק דאצי' וכולם הם גילוי נק' אלה, ומי הוא בחי' שאינו מושג, אך שאו מרום עיניכם וראו מי ברא אלה איך שנמשך ממי באלה שנמשך תמיד להחיות כו', וזהו\"ע ה' אחד<sup data-n=\"6334\">96</sup> דק\"ש דכל המאריך<sup data-n=\"6335\">97</sup> באחד מאריכין לו ימיו ושנותיו פי' מאריך באחד ח\"ד הם ד' רוחות ומעלה ומטה<sup data-n=\"6336\">98</sup> ומאריך באחד הוא להמשיך מא' לח\"ד (אפ\"ל ע\"ד מ\"ש בלקו\"א<sup data-n=\"6337\">99</sup> מהמגיד ממעזריטש נ\"ע ע\"פ אלה הדברים אשר דבר משה<sup data-n=\"6338\">100</sup> אלה א' הוא בחי' אלף<sup data-n=\"6339\">101</sup> בינה, וכמו\"כ יובן כאן וזהו מי ברא אלה). וזהו מ\"ש מי יתן והי' לבבם זה ליראה<sup data-n=\"6341\">103</sup> זה ליראה אותי כל הימים<sup data-n=\"6340\">102</sup> ודרשו רז\"ל הכל בידי שמים<sup data-n=\"6342\">104</sup> חוץ מיראת שמים וא\"כ צ\"ל מ\"ש מי יתן כו' (בלקו\"ת בד\"ה בשעה שהקדימו<sup data-n=\"6343\">105</sup> בביאור שם מבואר הקושי' כך מ\"ש במדרש<sup data-n=\"6344\">106</sup> הי' להשיבו תן אתה כו' וקשיא והלא הכל בידי שמים חוץ מי\"ש וא\"כ מהו תן אתה יעו\"ש וכמו\"כ צ\"ל כאן ג\"כ). והענין דהנה שמים הוא אש ומים<sup data-n=\"6345\">107</sup> מדות העליונות<sup data-n=\"6346\">108</sup>, וכל הנהגות העולמות הוא ע\"פ המדות, אבל י\"ש אינו תלוי בשמים כ\"א בבחי' מי וז\"ש מי יתן, וכמו\"כ יובן כאן שמבחי' מי יצא הקרח. ועל ל' הקבלה מי הוא בחי' ע\"י<sup data-n=\"6347\">109</sup> וגם בינה נק' מי<sup data-n=\"6348\">110</sup> וקאי שער<sup data-n=\"6349\">111</sup> הנו\"ן דבינה מספר מי<sup data-n=\"6350\">112</sup>, דהתגלות עתיק בבינה<sup data-n=\"6351\">113</sup>, וכמו עיקר",[["6329","91","<b>מי יתן מציון ישועת ישראל</b>: תהלים יד, ז. נג, ז."],["6330","92","<b>מי גילה לבני רז זה</b>: שבת פח, א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380335\" data-slug=\"likkutei-torah\" data-id=\"4001380335\">לקו\"ת במדבר ו, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380367\" data-slug=\"likkutei-torah\" data-id=\"4001380367\">יד, ד</a> ואילך."],["6331","93","<b>שאו מרום . . מי ברא אלה</b>: ישעי' מ, כו. ראה גם מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרל."],["6332","94","<b>אלה הם ו\"ק</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת פקודי ד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380068\" data-slug=\"likkutei-torah\" data-id=\"4001380068\">ז, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670519\" data-slug=\"torat-chaim\" data-id=\"2300670519\">תו\"ח נח נו, ב</a> ובהערה 15. משפטים ח\"ב רצא, ד ובהערה 268."],["6333","95","<b>ו\"ק רוחנים . . גשמים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380283\" data-slug=\"likkutei-torah\" data-id=\"4001380283\">לקו\"ת בחוקותי מח, ב</a>. מאמרי אדה\"ז תקס\"ב ח\"א ע' קמב ואילך. שע\"ת קכה, ג. אמרי בינה פתח השער ובהנסמן לשם."],["6334","96","<b>ה' אחד</b>: ואתחנן ו, ד."],["6335","97","<b>דכל המאריך באחד</b>: ברכות יג, ב."],["6336","98","<b>ח\"ד הם ד' רוחות ומעלה ומטה</b>: ראה שו\"ע אדה\"ז הל' ק\"ש סס\"א, ס\"ו. סה\"מ תר\"ם ח\"א ע' קט הערה 50."],["6337","99","<b>בלקו\"א</b>: סק\"ח (כד, ב). או\"ת ר\"פ דברים (נא, א)."],["6338","100","<b>אלה הדברים אשר דבר משה</b>: דברים א, א."],["6339","101","<b>אלף</b>: כ\"ה באו\"ת. ובלקו\"א: אלוף."],["6341","103","<b>זה ליראה</b>: לכאורה תיבות אלו הם מיותרות."],["6340","102","<b>מי יתן . . כל הימים</b>: ואתחנן ה, כו [בדילוגים]. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380368\" data-slug=\"likkutei-torah\" data-id=\"4001380368\">לקו\"ת במדבר טו, א</a> ואילך [צויין אליו בסמוך בפנים]. אוה\"ת ואתחנן ע' קצה ואילך. סה\"מ תר\"ם ח\"א ע' קיד וע' שלה."],["6342","104","<b>הכל בידי שמים</b>: ברכות לג, ב."],["6343","105","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380368\" data-slug=\"likkutei-torah\" data-id=\"4001380368\">לקו\"ת</a> בד\"ה בשעה שהקדימו</b>: במדבר טו, א."],["6344","106","<b>במדרש</b>: בלקו\"ת שם: ס\"פ כי תבא — פ\"ז, י."],["6345","107","<b>שמים הוא אש ומים</b>: ראה חגיגה יב, סע\"א. רש\"י בראשית א, ח."],["6346","108","<b>שמים . . מדות העליונות</b>: ראה גם לקו\"ת שם. שער היחוד קי, ב ובהערה 24."],["6347","109","<b>מי הוא בחי' ע\"י</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380293\" data-slug=\"likkutei-torah\" data-id=\"4001380293\">לקו\"ת בחוקותי נ, ד</a>. ניצוצי אורות לזהר תרומה קלט, ב אות א."],["6348","110","<b>בינה נק' מי</b>: זהר משפטים קיז, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת פקודי ד, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550228\" data-slug=\"torat-chaim\" data-id=\"2300550228\">תו\"ח פקודי ח\"ב תמג, ד</a> ובהערה 78."],["6349","111","<b>וקאי שער</b>: אוצ\"ל: וקאי על שער."],["6350","112","<b>הנו\"ן . . מספר מי</b>: ראה גם פרדס שעה\"כ שכ\"ג, פי\"ג מערכת מי. שער ההקדמות דרוש ו בכניסת המוחין ובהגדלת ז\"א (קע, ב). מאו\"א מערכת מי אות סח."],["6351","113","<b>דהתגלות עתיק בבינה</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670111\" data-slug=\"torat-chaim\" data-id=\"2300670111\">תו\"ח לך פא, ב</a>. ביאוה\"ז להצ\"צ אחרי כרך א ע' שסד."]]],[2001910561,"התענוג לאחר שמשיגו השכל אבל לא קודם לכן, וזהו\"ע הרקיע בחי' בינה<sup data-n=\"6352\">114</sup> שהתגלות עתיק בבינה גילוי התענוג, וזהו ועל דמות ראשי החי'<sup data-n=\"6353\">115</sup> רקיע כעין הקרח דיש חיון עילאין וחיון תתאין<sup data-n=\"6354\">116</sup>, חיון תתאין הם ד' מחנה שכינה<sup data-n=\"6355\">117</sup> וחיון הם<sup data-n=\"6356\">118</sup> האבות הם המרכבה<sup data-n=\"6357\">119</sup> חג\"ת<sup data-n=\"6358\">120</sup>, וראשי החיות הם מוחין דז\"א, ועל ראשי החיות הוא הרקיע בינה גילוי התענוג, וברקיע הזה יש מתיבתא דרקיע.",[["6352","114","<b>הרקיע בחי' בינה</b>: ראה לעיל הערה 73."],["6353","115","<b>ועל דמות ראשי החי'</b>: יחזקאל א, כב [ושם: ודמות על ראשי החיה]. ראה גם לעיל הערה 74."],["6354","116","<b>חיון עילאין וחיון תתאין</b>: ראה זהר ויקהל ריא, א. ריג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380171\" data-slug=\"likkutei-torah\" data-id=\"4001380171\">לקו\"ת תזריע כב, ד</a>. לעיל הנחה ד\"ה הוא אהרן ומשה ובהערה 64."],["6355","117","<b>ד' מחנה שכינה</b>: זהר במדבר קיח, ב."],["6356","118","<b>וחיון הם</b>: אוצ\"ל: וחיון עילאין הם."],["6357","119","<b>האבות הם המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670263\" data-slug=\"torat-chaim\" data-id=\"2300670263\">תו\"ח נח מט, ד</a> ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."],["6358","120","<b>האבות . . חג\"ת</b>: ראה מאו\"א מערכת אבות סכ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540325\" data-slug=\"torat-chaim\" data-id=\"2300540325\">תו\"ח וארא ח\"א סא, ד</a>. וש\"נ."]]],[2001910562,"<h3>זאת תהי' תורת המצורע</h3>\n<b>ש\"פ מצורע</b>\n(ב) <b>זאת</b> תהי' תורת<sup data-n=\"6360\">2</sup> המצורע<sup data-n=\"6359\">1</sup> ואי' במדרש מצורע ר\"ת<sup data-n=\"6361\">3</sup> מוציא שם רע, דהעונש דמוציא ש\"ר הוא שנלקה בצרעת, וכן מצינו בנחש שהוציא ש\"ר על הבורא נלקה בצרעת<sup data-n=\"6362\">4</sup>, הדין סלעיא דבי' הוא צרעת, ופי' המת\"כ דהחברבורות והסלעים שבנחש הוא צרעת, וכן על כל פגמי הדיבור<sup data-n=\"6363\">5</sup> כמו לה\"ר ורכילות לוקה בצרעת, וכן על פגמי המח' כמ\"ש לב חורש מח' עון<sup data-n=\"6364\">6</sup> לוקה בצרעת, וצ\"ל למה כשפגם במח' או בדיבור לוקה בצרעת, ועוד צ\"ל דטהרת המצורע הי' שתי צפרים<sup data-n=\"6365\">7</sup> וכתי' ושלח את הצפור החי' על פני המים<sup data-n=\"6366\">8</sup> מה שלא מצינו כן בשאר טהרה.",[["6360","2","<b>זאת תהי' תורת המצורע</b>: מצורע יד, ב."],["6359","1","<b>זאת תהי' תורת המצורע</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה וענין מתיבתא דרקיע [וכן ממאמר ד\"ה להבין ענין טהרת המצורע וכו' זאת תהי' תורת המצורע שבו יש חלק נוסף — וכנראה מכאן שחלק נוסף זה לא נאמר. ראה גם לעיל שם בהערה 1] שנדפס לעיל בחלק המאמרים. וש\"נ.\nאות ב הנרשם כאן בתחילת המאמר כנראה הכוונה שמאמר זה הוא המשך להמאמר שנדפס לפנ\"ז."],["6361","3","<b>במדרש מצורע ר\"ת</b>: ראה תנחומא מצורע א [ושם: אל תקרי]. ויק\"ר פט\"ז, ב. ו. ערכין טו, ב. ירושלמי סוטה פ\"ב, ה\"א."],["6362","4","<b>בנחש . . בצרעת</b>: ראה ב\"ר פ\"כ, ד."],["6363","5","<b>וכן על כל פגמי הדיבור</b>: ראה ויק\"ר פט\"ז, א."],["6364","6","<b>לב חורש מח' עון</b>: משלי ו, יח [ושם: און]."],["6365","7","<b>דטהרת. . שתי צפרים</b>: מצורע יד, ד."],["6366","8","<b>ושלח את הצפור . . המים</b>: שם, שם, ז [ושם: השדה]."]]],[2001910563,"<b>והנה</b> צ\"ל תחילה ענין טומאת הנגעים דכשספק אם בהרת קדמה או שער לבן קדמו קוב\"ה אומר טהור וכולהו מתיבתא דרקיע אמרי טהור<sup data-n=\"6368\">10</sup><sup data-n=\"6367\">9</sup> ונת\"ל<sup data-n=\"6369\">11</sup> ענין הרקיע שהוא למעלה<sup data-n=\"6370\">12</sup> מהז\"ר<sup data-n=\"6371\">13</sup> והוא הרקיע שע\"ג ראשי חיון עילאין<sup data-n=\"6372\">14</sup> שעז\"נ רקיע כעין הקרח הנורא<sup data-n=\"6373\">15</sup>, וכתי' מבטן מי יצא הקרח<sup data-n=\"6374\">16</sup>, מי הוא שער הנו\"ן<sup data-n=\"6375\">17</sup> שער האיתן<sup data-n=\"6376\">18</sup>, וצריכים להמשיך מבחי' מי ברקיע, והוא לפי' שנת\"ל דמי הוא בחי' עתיק<sup data-n=\"6377\">19</sup> והו\"ע התגלות עתיק בבינה<sup data-n=\"6378\">20</sup> דעיקר התענוג כשהשכל בא לידי השגה והבנה אבל לא קודם לכן, והנה מרקיע זה נמשך במתיבתא דרקיע שהוא געה\"ע<sup data-n=\"6379\">21</sup>, דיש געה\"ע וגעה\"ת<sup data-n=\"6380\">22</sup> הגם דיש כמה מדרי' בג\"ע כמ\"ש ילכו מחיל אל חיל<sup data-n=\"6381\">23</sup> שיש עליות עד אין שיעור, אך בד\"כ הם ב' מדרי' געה\"ע וגעה\"ת וכמ\"ש בזהר שיש מתיבתא דרקיע ומתיבתא דמט\"ט<sup data-n=\"6382\">24</sup> (ע' בלקו\"ת פ' אמור<sup data-n=\"6384\">26</sup> ד\"ה ונקדשתי רפ\"ב ולקמן בד\"ה את חג המצות תשמור<sup data-n=\"6383\">25</sup>)<sup data-n=\"6385\">27</sup> ולמטה הוא מתיבתא דסוריא<sup data-n=\"6386\">28</sup> ומתיבתא דנהרדעא<sup data-n=\"6387\">29</sup>, והזוכים לישב במתיבתא דרקיע הם הצדיקים הגדולים תנאים ואמוראים, דכתי' והאיתנים מוסדי ארץ<sup data-n=\"6388\">30</sup>, איתנים אותיות תנאים<sup data-n=\"6389\">31</sup>,",[["6368","10","<b>טהור</b>: וכ\"ה לעיל הנחה ד\"ה קא מיפלגי במתיבתא דרקיע על יד הערה 3. ואוצ\"ל: טמא."],["6367","9","<b>דכשספק . . אמרי טהור</b>: ראה ב\"מ פו, א."],["6369","11","<b>ונת\"ל</b>: הנחה ד\"ה קא מיפלגי על יד הערה 72 ואילך."],["6370","12","<b>הרקיע שהוא למעלה</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה בגמ' וכו' קא מפלגי במתיבתא דרקיע רפ\"ג ובהנסמן שם."],["6371","13","<b>מהז\"ר</b>: חגיגה יב, ב. ראה סה\"מ תרל\"ח ע' קיז הערה 431."],["6372","14","<b>חיון עילאין</b>: ראה לעיל הנחה ד\"ה הוא אהרן ומשה ובהערה 64."],["6373","15","<b>רקיע כעין הקרח הנורא</b>: יחזקאל א, כב."],["6374","16","<b>מבטן מי יצא הקרח</b>: איוב לח, כט. ראה זהר לך פה, סע\"ב. סה\"מ תרל\"ה כאן ע' רכה בהערה."],["6375","17","<b>מי הוא שער הנו\"ן</b>: ראה גם פרדס שעה\"כ שכ\"ג, פי\"ג מערכת מי. שער ההקדמות דרוש ו בכניסת המוחין ובהגדלת ז\"א (קע, ב). מאו\"א מערכת מי אות סח."],["6376","18","<b>שער הנו\"ן שער האיתן</b>: מגלה עמוקות אופן נ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380369\" data-slug=\"likkutei-torah\" data-id=\"4001380369\">לקו\"ת במדבר טו, ב</a>."],["6377","19","<b>שנת\"ל דמי . . עתיק</b>: הנחה ד\"ה קא מיפלגי ובהערה 109."],["6378","20","<b>התגלות עתיק בבינה</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670111\" data-slug=\"torat-chaim\" data-id=\"2300670111\">תו\"ח לך פא, ב</a>. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["6379","21","<b>במתיבתא דרקיע שהוא געה\"ע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380171\" data-slug=\"likkutei-torah\" data-id=\"4001380171\">לקו\"ת תזריע כאן כב, ד</a>. סהמ\"צ להצ\"צ קג, ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940116\" data-slug=\"or-hatorah-hb\" data-id=\"8159940116\">אוה\"ת תזריע כרך ב ע' תקלב</a>. ויקרא כרך א ע' רנג ואילך."],["6380","22","<b>געה\"ע וגעה\"ת</b>: ראה גם לקמן הנחה ד\"ה כתר יתנו לך ובהערה 85."],["6381","23","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["6382","24","<b>מתיבתא דרקיע . . דמט\"ט</b>: ראה זח\"א בהשמטות רסו, א. שלח קסג, א. ז\"ח יתרו לו, ב ובניצוצי זהר שם.\nראה גם הגהות הרח\"ו לזהר שלח שם. אוה\"ת תזריע שם."],["6384","26","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380211\" data-slug=\"likkutei-torah\" data-id=\"4001380211\">לקו\"ת פ' אמור</b>: לא, ב</a>."],["6383","25","<b>(ע' בלקו\"ת . . תשמור)</b>: הערה זו ניתוספה לאחר אמירת המאמר את חג המצות תשמור דלקמן ונרשמה עה\"ג."],["6385","27","<b>בד\"ה את חג המצות תשמור</b>: ראה שם על יד הערה 104."],["6386","28","<b>דסוריא</b>: וכ\"ה (לעיל בחלק המאמרים) בהמאמר כאן. סה\"מ עזר\"ת ע' קפ. בסה\"מ תרל\"ה כאן ע' רכז העיר לכאו' צ\"ל: דסורא."],["6387","29","<b>דסוריא . . דנהרדעא</b>: ראה אגרת רב שרירא גאון ח\"ג, פ\"ב. ועוד. סדר הדורות ג\"א תתקע\"ט ד\"ה רב ושמואל."],["6388","30","<b>והאיתנים מוסדי ארץ</b>: מיכה ו, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370222\" data-slug=\"torah-or\" data-id=\"3901370222\">תו\"א שמות מט, ב</a>-ג."],["6389","31","<b>איתנים אותיות תנאים</b>: זהר סבא משפטים קי, ב. רע\"מ תצא רעח ב. ת\"ז תכ\"א מג, סע\"ב. מו, ב."]]],[2001910564,"איתן או' תניא<sup data-n=\"6390\">32</sup>, ואמורא<sup data-n=\"6391\">33</sup> הוא מל' את ה' האמרת היום<sup data-n=\"6392\">34</sup> וכתי' כי אמרתי עולם חסד יבנה<sup data-n=\"6393\">35</sup>, והם מוסדי ארץ דממשיכים מבחי' מי, דהנה כתי' משכיל לאיתן האזרחי<sup data-n=\"6394\">36</sup>, משכיל הוא מקור השכל ששם אינו מורגש עדיין וכמו אור שאינו מורגש אפי' במישוש, ואיתן כמשמעו קשה<sup data-n=\"6395\">37</sup> שהוא כשהשכל בא לידי השגה והבנה, משכיל לאיתן ההמשכה ממשכיל לאיתן היינו מאור לרקיע, ותנאים ואמוראים המשיכו בחי' זו לכן הראו נסים<sup data-n=\"6396\">38</sup> שיוצאים מדרכי הטבע כמו רפב\"י שא' גינאי נהרא חלוק למימיך<sup data-n=\"6397\">39</sup> וחלק למימיו, ודבר הי'<sup data-n=\"6398\">40</sup> גבי משה וס\"ר ישראל נס שיוצא מדרכי הטבע דיש נסים מוסתרי' ונסים נגלים<sup data-n=\"6399\">41</sup>, נסים מוסתרים הם שמוסתרים בדרכי הטבע ונסים נגלים היינו שיוצאים מדרכי הטבע לגמרי, אך זהו מפני שהמשיכו מבחי' מי.\n<b>וביאור</b> הענין צ\"ל ענין תורה ותפלה, דאורייתא מחכ' נפקת<sup data-n=\"6400\">42</sup>, אלפך חכ'<sup data-n=\"6401\">43</sup>, וירדה למטה בשיתא סדרי משנה<sup data-n=\"6402\">44</sup> [ששה מדות<sup data-n=\"6403\">45</sup>] והוא נובלות חכ', וצריכים להמשיך ממקור התורה והוא ע\"י התפלה. דהנה ארז\"ל על מה אבדה הארץ<sup data-n=\"6404\">46</sup> על שלא ברכו בתורה<sup data-n=\"6405\">47</sup> תחילה, וא\"ל על שלא אמרו ברכת התורה שהרי אמרז\"ל<sup data-n=\"6406\">48</sup> דבר זה נשאל לחכמים ולא פי' לנביאים ולא פי' עד שפי' הקב\"ה בעצמו, אלא ר\"ל שלא המשיכו המשכת אוא\"ס בתורה, והוא ע\"י תפלה, דתפלה הוא התבוננות איך דלגדולתו עצמיות אין חקר<sup data-n=\"6407\">49</sup> דכללות השתל' העולמות הם הארה בעלמא לכן אני ה' לא שניתי<sup data-n=\"6408\">50</sup> שלא יש שום שינוי בין קודם הבריאה לאחר הבריאה, אתה הוא",[["6390","32","<b>איתן או' תניא</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 32."],["6391","33","<b>ואמורא</b>: ראה אוה\"ת תזריע כרך ב ע' תקלא. סה\"מ עזר\"ת ע' קפא."],["6392","34","<b>את ה' האמרת היום</b>: תבוא כו, יז."],["6393","35","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["6394","36","<b>משכיל לאיתן האזרחי</b>: שם פט, א."],["6395","37","<b>ואיתן כמשמעו קשה</b>: סוטה מה, ב במשנה. מו, סע\"א ואילך."],["6396","38","<b>ותנאים ואמוראים . . נסים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כב, ג</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תמג. וש\"נ. ס\"ע תנו ואילך. שמות ח\"א ע' קע ואילך. תקע\"ז ע' רכח ואילך. סהמ\"צ להצ\"צ קג, ב. סה\"מ תרל\"ה כאן ע' רכז. תרל\"ט ח\"א ע' קנט. וש\"נ. ע' רסג. ע' שמו. פלח הרמון ויקרא ע' ק."],["6397","39","<b>גינאי נהרא חלוק למימיך</b>: ראה חולין ז, א. ראה גם סה\"מ תרל\"ח ע' שעט. וש\"נ."],["6398","40","<b>ודבר הי'</b>: אוצ\"ל: ודבר זה הי'."],["6399","41","<b>נסים מוסתרי' . . נגלים</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה מגילה נקראת פ\"ג ובהנסמן שם."],["6400","42","<b>דאורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["6401","43","<b>אלפך חכ'</b>: איוב לג, לג [ושם: ואאלפך]. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380217\" data-slug=\"likkutei-torah\" data-id=\"4001380217\">לקו\"ת אמור לב, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380836\" data-slug=\"likkutei-torah\" data-id=\"4001380836\">פ' ראה ל, א</a>."],["6402","44","<b>בשיתא סדרי משנה</b>: ראה זהר בראשית מב, א. במד\"ר פי\"ב, יז. פי\"ג, טוטז. שבת לא, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111064\" data-slug=\"likkutei-sichot\" data-id=\"1300111064\">לקו\"ש בשלח כרך יא ע' 56</a> הערה 13."],["6403","45","<b>בשיתא . . ששה מדות</b>: ראה לעיל הנחה ד\"ה ועבדתם את ה\"א הערה 87."],["6404","46","<b>על מה אבדה הארץ</b>: ירמי' ט, יא."],["6405","47","<b>שלא ברכו בתורה</b>: ב\"מ פה, ב. נדרים פא, א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380832\" data-slug=\"likkutei-torah\" data-id=\"4001380832\">לקו\"ת פ' ראה כט, א</a>."],["6406","48","<b>שהרי אמרז\"ל</b>: ראה הערה שלפנ\"ז."],["6407","49","<b>דלגדולתו . . אין חקר</b>: ע\"פ תהלים קמה, ג."],["6408","50","<b>אני ה' לא שניתי</b>: מלאכי ג, ו. ראה גם לקו\"ת אמור שם ואילך. סה\"מ תר\"ם ח\"א ע' שסט ואילך. וש\"נ."]]],[2001910565,"קודם שנבה\"ע<sup data-n=\"6409\">51</sup> ואתה הוא לאחר שנבה\"ע, דכללות השתל' העולמות מרכ\"ד עד סכ\"ד אינם תופסים מקום כלל וזהו\"ע ה' אחד דק\"ש יחו\"ע<sup data-n=\"6410\">52</sup> דכולי' קמי' כ\"ח<sup data-n=\"6411\">53</sup>, ואי לזאת מי לי בשמים<sup data-n=\"6412\">54</sup> ועמך לא חפצתי בארץ, שו\"א הם געה\"ע וגעה\"ת<sup data-n=\"6413\">55</sup>, שאיני חפץ לא געה\"ע ולא געה\"ת ולא עוה\"ב כ\"א אוא\"ס עצומ\"ה. וז\"ש אח\"כ ואהבת פי' רצון<sup data-n=\"6414\">56</sup> שיש לו רצון ותשוקה לכלול באלקות, והיכן ימצא רצון וחפץ זה, ז\"ש והיו הדברים האלה<sup data-n=\"6415\">57</sup> בד\"ת הכתוב מדבר, אלה מספר ל\"ו<sup data-n=\"6416\">58</sup> הוא ופ\"ו, ותורה הוא שיתא סדרי משנה וכל סדר כלול מכולם כמו זרעים כלול ממועד כו' מועד כלול מזרעים כו' וכן כולם הם ופ\"ו גימ' אלה, וזהו אף דוהיו הדברים האלה ופ\"ו מ\"מ<sup data-n=\"6417\">*59</sup> אשר אנכי מצוך היום שנמשך בתורה בחי' אנכי מי שאנכי<sup data-n=\"6418\">59</sup>. וזשארז\"ל על אבא בנימין כל ימיו הי' מצטער על תפלתו שתהא סמוכה למטתו<sup data-n=\"6419\">60</sup> פי' שיהי' למוד התורה דמעלה<sup data-n=\"6420\">61</sup> יש בה שנמשך המשכות אוא\"ס בתורה ע\"י התפלה, וממילא נמשך גם בתורה שלמטה. וזהו ודברת בם ל' הנהגה<sup data-n=\"6421\">62</sup> וגם ל' דיבור, דדיבור ג\"כ ל' הנהגה<sup data-n=\"6422\">63</sup> כמו ידבר עמים<sup data-n=\"6423\">64</sup>, דעיקר מצות לימוד התורה בדיבור<sup data-n=\"6424\">65</sup> דשרש הדיבור גבוה מאד, וכמ\"ש ויהי האדם לנפש חי' ומתרגמינן לרוח ממללא<sup data-n=\"6425\">66</sup> א\"כ שרש הדיבור מבחי' חי'<sup data-n=\"6426\">67</sup> שלמעלה מנשמה, שיש נר\"ן וחי' למעלה מהם, ועוד שרש הדיבור למעלה גם",[["6409","51","<b>אתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["6410","52","<b>ה' אחד דק\"ש יחו\"ע</b>: ואתחנן ו, ד. זהר בראשית יח, ב."],["6411","53","<b>דכולי' קמי' כ\"ח</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["6412","54","<b>מי לי בשמים</b>: תהלים עג, כה. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370037\" data-slug=\"torah-or\" data-id=\"3901370037\">תו\"א נח ט, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550091\" data-slug=\"torat-chaim\" data-id=\"2300550091\">תו\"ח תצוה ח\"ב שנו, ב</a>. וש\"נ. סה\"מ תרל\"ח ע' מו. וש\"נ. תר\"ם ח\"א ע' שסא. וש\"נ."],["6413","55","<b>שו\"א הם געה\"ע וגעה\"ת</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת פ' ראה כה, א</a>. סה\"מ תרל\"ח ע' מו. וש\"נ."],["6414","56","<b>ואהבת פי' רצון</b>: ואתחנן ו, ה. ראה גם לעיל הנחה ד\"ה ועבדתם את ה\"א ובהערה 81."],["6415","57","<b>והיו הדברים האלה</b>: ואתחנן ו, ו. ראה הנסמן (לעיל בחלק המאמרים) במאמר ד\"ה הקבצו ושמעו בנ\"י הערה 113."],["6416","58","<b>אלה מספר ל\"ו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת פקודי ד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380068\" data-slug=\"likkutei-torah\" data-id=\"4001380068\">ז, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670519\" data-slug=\"torat-chaim\" data-id=\"2300670519\">תו\"ח נח נו, ב</a> ובהערה 15. משפטים ח\"ב רצא, ד ובהערה 268."],["6417","*59","<b>ופ\"ו מ\"מ</b>: אולי נרשם איזה תיבה שא\"א לפענחה ממעל לתיבת מ\"מ."],["6418","59","<b>אנכי מי שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["6419","60","<b>אבא בנימין . . סמוכה למטתו</b>: ראה ברכות ה, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381212\" data-slug=\"likkutei-torah\" data-id=\"4001381212\">לקו\"ת שה\"ש כ, רע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381112\" data-slug=\"likkutei-torah\" data-id=\"4001381112\">ברכה צו, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550507\" data-slug=\"torat-chaim\" data-id=\"2300550507\">ואתחנן ד, א</a>. תו\"ח תצוה ח\"ב שנ, ב ואילך. סה\"מ תרכ\"ז ע' רפח בשולי הגליון."],["6420","61","<b>התורה דמעלה</b>: אוצ\"ל: התורה אחר התפלה דמעלה."],["6421","62","<b>ודברת בם ל' הנהגה</b>: ואתחנן ו, ז. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370002\" data-slug=\"torah-or\" data-id=\"3901370002\">תו\"א בראשית א, סע\"א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380218\" data-slug=\"likkutei-torah\" data-id=\"4001380218\">לקו\"ת אמור לג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380834\" data-slug=\"likkutei-torah\" data-id=\"4001380834\">ואתחנן ב, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381019\" data-slug=\"likkutei-torah\" data-id=\"4001381019\">ט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381197\" data-slug=\"likkutei-torah\" data-id=\"4001381197\">פ' ראה כט, ג</a>. האזינו עד, א. שה\"ש יז, א. סה\"מ תר\"ם ח\"א ע' רצז. וש\"נ."],["6422","63","<b><a class=\"ft-cite\" href=\"#/read/torah-or/3901370251\" data-slug=\"torah-or\" data-id=\"3901370251\">דדיבור ג</a>\"כ ל' הנהגה</b>: ראה מפרשים לתהלים מז, ד. תו\"א וארא נו, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670048\" data-slug=\"torat-chaim\" data-id=\"2300670048\">תו\"ח לך צא, ב</a>. הנסמן במאמרי אדה\"א בראשית ע' תיט־ שמות ח\"ב ע' שסח."],["6423","64","<b>ידבר עמים</b>: תהלים מז, ד."],["6424","65","<b>דעיקר מצות לימוד התורה בדיבור</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב. מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540721\" data-slug=\"torat-chaim\" data-id=\"2300540721\">תו\"ח וארא ח\"א פ, ג</a>. וש\"נ. סה\"מ תר\"ם ח\"א ע' פח. וש\"נ."],["6425","66","<b>ויהי האדם . . לרוח ממללא</b>: בראשית ב, ז ובתרגום אונקלוס שם."],["6426","67","<b>שרש הדיבור מבחי' חי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370014\" data-slug=\"torah-or\" data-id=\"3901370014\">תו\"א בראשית ד, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">מקץ מב, ב</a>."]]],[2001910566,"מחי', דלדיבור יש מדבר שהוא בחי' קוש\"י<sup data-n=\"6427\">68</sup> ומ\"ש לנפש חי' אפ\"ל דחי' כולל יחידה ג\"כ<sup data-n=\"6428\">69</sup>, ומ\"ש התרגום רוח ממללא שרש הרוח מאויר אור<sup data-n=\"6429\">70</sup> יו\"ד<sup data-n=\"6430\">71</sup>, ופעולת הרוח הוא דגחלת כשנכוה<sup data-n=\"6432\">73</sup> ונשאר רק ניצוץ אחד וכשויפח ברוח פיו<sup data-n=\"6431\">72</sup> יכול להוציא שלהבת וכמו\"כ ע\"ס בלי מה<sup data-n=\"6433\">74</sup> כשלהבת הקשורה בגחלת וע\"י הדיבור מוצא מהעלם אל הגילוי וזהו\"ע לימוד התורה בדיבור שממשיך ממקור התורה, ולכן התנאים והאמוראים שהמשיכו ממקור התורה הראו נסים שיוצאים מדרכי הטבע כמו גינאי נהרא כו' שהו\"ע הפך ים ליבשה<sup data-n=\"6434\">75</sup> דים ויבשה הם ב' צירופים ים העלם ויבשה גילוי אבל מצד בחי' מי אפשר שיתחלפו הצירופים ויהי' היפך ים ליבשה, וע\"ד משארז\"ל מי שאמר לשמן<sup data-n=\"6435\">76</sup> וידלק יאמר לחומץ וידלק, שהרי שמן דולק וחומץ אינו דולק אבל מצד בחי' מי אפשר שגם חומץ ידליק, וכמו מי יתן טהור מטמא<sup data-n=\"6436\">77</sup> דטהור וטמא הם ב' הפכים אבל בחי' מי יתן טהור מטמא, וכמו\"כ יובן בתנאים ואמוראים שהרי המשיכו מבחי' מקור התורה לכן הראו נסים שיוצאים מדרכי הטבע כו'.",[["6427","68","<b>מדבר . . קוש\"י</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ועוי\"ל ענין ק\"נ דאצי' על יד הערה מד ואילך."],["6428","69","<b>דחי' כולל יחידה ג\"כ</b>: ראה גם סה\"מ תרל\"ח ע' קמח."],["6429","70","<b>הרוח מאויר אור</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א מקץ מב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370194\" data-slug=\"torah-or\" data-id=\"3901370194\">מג, ב</a>."],["6430","71","<b>מאויר אור יו\"ד</b>: נסמן (לעיל בחלק המאמרים) במאמר ד\"ה להבין וכו' בענין הציץ הערה 214."],["6432","73","<b>כשנכוה</b>: אוצ\"ל: כשנכבה."],["6431","72","<b>דגחלת . . ברוח פיו</b>: השווה (לענין תפלה) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380216\" data-slug=\"likkutei-torah\" data-id=\"4001380216\">לקו\"ת אמור לב, ג</a>."],["6433","74","<b>ע\"ס בלי מה</b>: ראה ס\"י פ\"א, מ\"ז."],["6434","75","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["6435","76","<b>מי שאמר לשמן</b>: נסמן (לעיל בחלק המאמרים) במאמר כאן."],["6436","77","<b>מי יתן טהור מטמא</b>: איוב יד, ד. ראה לקו\"ת חוקת ס, א."]]],[2001910567,"<h3>שלש רגלים תחוג לי</h3>\n<b>ליל ב' דפסח</b>\n<b>שלש</b> רגלים תחוג לי<sup data-n=\"6437\">1</sup> בשנה<sup data-n=\"6438\">2</sup> את חג המצות תשמור שבעת ימים תאכל מצות כאשר צויתיך למועד חדש האביב כי בו יצאת ממצרים<sup data-n=\"6439\">3</sup>, וחג הקציר בכורי מעשיך אשר תזרע בשדה וחג האסיף בצאת השנה באספך את מעשיך מן השדה<sup data-n=\"6440\">4</sup>, ולכאו' צ\"ל הלא מ\"ש תחוג לי פי' אוא\"ס עצומ\"ה ונק' מועדי הוי'<sup data-n=\"6441\">5</sup> וא\"כ מה הם",[["6437","1","<b>שלש רגלים תחוג לי</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל (בחלק המאמרים — וראה הנסמן בהערה 1 שם). כמו\"כ ישנו עוד הנחה מדרוש זה ונדפסה לקמן בחלק ההנחות.\nלקמן בהנחה שלאח\"ז ד\"ה את חג המצות תשמור שנדפסה לאח\"ז צויין להנחה זו על יד הערה 4־ 16־ 24."],["6438","2","<b>שלש רגלים תחוג לי בשנה</b>: משפטים כג, יד."],["6439","3","<b>את חג המצות . . יצאת ממצרים</b>: שם כג, טו."],["6440","4","<b>וחג הקציר . . מן השדה</b>: משפטים שם, טז."],["6441","5","<b>מועדי הוי'</b>: אמור כג, ב. ד. לז. מד. עזרא ג, ה."]]],[2001910568,"תלוים בתבואת<sup data-n=\"6442\">6</sup>, דפסח צ\"ל בחדש האביב זמן בישול שעורים<sup data-n=\"6443\">7</sup> ודוקא בעודם מחוברי' כמו קישות שהתליע באיבו<sup data-n=\"6444\">8</sup>, ושבועות בזמן קציר חטים<sup data-n=\"6445\">9</sup>, וסוכות בזמן האסיף<sup data-n=\"6446\">10</sup>, ואם הם שייכים להתבואה דוקא הי' צ\"ל בארץ דבחו\"ל אין זמן התבואה כו' ולא יש לנו תבואה כו' והמועדים הם בין בארץ בין בחו\"ל<sup data-n=\"6447\">11</sup>. והענין דהנה רגלים פי' ל' רגל המהלכת<sup data-n=\"6448\">12</sup> ג\"כ וכמארז\"ל קטן שאינו יכול<sup data-n=\"6449\">13</sup> לאחוז בידיו של אביו ולעלות מירושלים להר הבית פטור מראי' שנא' שלש רגלים וצ\"ל מה שייך רגל המהלכת לרגלים. והענין דהנה כתי' כה אמר ה' אם בדרכי תלך ונתתי לך מהלכים<sup data-n=\"6450\">14</sup> בין העומדים האלה, הנה עבודת המלאכים הוא בבחי' עמידה וכמ\"ש שרפים עומדים<sup data-n=\"6451\">15</sup>, כולם עומדים ברום עולם<sup data-n=\"6452\">16</sup>, ויש בזה מעלה וחסרון, מעלה שאינו שייך בהם ירידה דאינם מתלבשים בגופים דד' יסודות, וחסרון שאין בהם עלי' כ\"כ אף שממשיכים ע\"י בטולם המשכת אלקות כו' מ\"מ אין העלי' כ\"כ, דכתי' ורגליהם רגל ישרה<sup data-n=\"6453\">17</sup> ואי' בתוס' ישר\"ה מספר תקט\"ו<sup data-n=\"6454\">18</sup> כמנין תקט\"ו תפלות שהתפלל משה כמנין ואתחנ\"ן<sup data-n=\"6455\">19</sup>, וצ\"ל למה מספר תקט\"ו דוקא, ומצינו כל המספרים שבשמים הם ת\"ק כמו עובי כל רקיע<sup data-n=\"6456\">20</sup> מהלך ת\"ק שנה בין כל רקיע מהלך ת\"ק שנה כו' עץ החיים מהלך ת\"ק שנה<sup data-n=\"6457\">21</sup>, וצ\"ל למה מספר ת\"ק דוקא.\n<b>והענין</b> דהנה כתי' לך ה' הגדולה והגבו'<sup data-n=\"6458\">22</sup> והת\"ת והנצח וההוד, ואמרז\"ל הגדולה זו קרי\"ס והגבו' מכות בכורות ות\"ת מ\"ת והנצח בנין ירושלים וההוד בנין<sup data-n=\"6460\">24</sup> בהמק\"ד<sup data-n=\"6459\">23</sup>, דה' מדות אלו הם עקרי המדות<sup data-n=\"6461\">25</sup> וכמ\"ש כי אמרתי עולם חסד",[["6442","6","<b>בתבואת</b>: אוצ\"ל: בתבואות־ בתבואת הארץ."],["6443","7","<b>האביב זמן בישול שעורים</b>: ראה מנחות סח, ב. אבן עזרא משפטים כג, טז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301730177\" data-slug=\"likkutei-sichot\" data-id=\"1301730177\">לקו\"ש משפטים כרך לו ע' 109</a> ואילך."],["6444","8","<b>קישות שהתליע באיבו</b>: ראה חולין נח סע\"א. סז סע\"א ואילך."],["6445","9","<b>ושבועות בזמן קציר חטים</b>: תשא לד, כב."],["6446","10","<b>וסוכות בזמן האסיף</b>: משפטים כב, טז (וברש\"י שם). תשא שם."],["6447","11","<b>והמועדים . . בארץ בין בחו\"ל</b>: ראה גם רמב\"ם הל' יו\"ט רפ\"א."],["6448","12","<b>רגלים . . רגל המהלכת</b>: ראה [ולהבא בסמוך] אוה\"ת משפטים כאן ע' א'קעד ואילך. וראה גם סה\"מ תרל\"ח ע' תקכא ואילך. ע' תקכה. (ע' תלט)."],["6449","13","<b>קטן שאינו יכול</b>: ראה חגיגה ב, א (במשנה)."],["6450","14","<b>כה אמר . . ונתתי לך מהלכים</b>: זכרי' ג, ז [בדילוג]. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370139\" data-slug=\"torah-or\" data-id=\"3901370139\">תו\"א וישב ל, סע\"א</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תרסז. וש\"נ. ש\"א ח, ב ובהערה 42."],["6451","15","<b>שרפים עומדים</b>: ישעי' ו, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380236\" data-slug=\"likkutei-torah\" data-id=\"4001380236\">לקו\"ת אמור לז, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380270\" data-slug=\"likkutei-torah\" data-id=\"4001380270\">בחוקותי מה, א</a>."],["6452","16","<b>כולם עומדים ברום עולם</b>: ברכת יוצר."],["6453","17","<b>ורגליהם רגל ישרה</b>: יחזקאל א, ז."],["6454","18","<b>ואי' בתוס' ישר\"ה מספר תקט\"ו</b>: חגיגה יג, א ד\"ה ורגלי. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380222\" data-slug=\"likkutei-torah\" data-id=\"4001380222\">לקו\"ת אמור לד, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159780113\" data-slug=\"or-hatorah-hb\" data-id=\"8159780113\">אוה\"ת</a> חנוכה כרך ה ע' 1828 ואילך [בהעלותך ע' תי ואילך]. משפטים כאן ע' א'קעג. ואתחנן ס\"ע קיג ואילך. ובכרך ו' ע' ב'קצג."],["6455","19","<b>תקט\"ו תפלות . . ואתחנ\"ן</b>: דב\"ר פי\"א, י. ראה גם אוה\"ת סידור ס\"ע קיג. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061116\" data-slug=\"likkutei-sichot\" data-id=\"1300061116\">לקו\"ש בשלח כרך ו ע' 105</a>."],["6456","20","<b>עובי כל רקיע</b>: ראה חגיגה יג, א."],["6457","21","<b>עץ החיים מהלך ת\"ק שנה</b>: ב\"ר פט\"ו, ו. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560131\" data-slug=\"or-hatorah-hb\" data-id=\"8316560131\">אוה\"ת בראשית ע' מז</a>. שם כרך ג ע' תקלב."],["6458","22","<b>לך ה' הגדולה והגבו'</b>: דברי הימים-א כט, יא."],["6460","24","<b>והנצח בנין . . וההוד בנין בהמק\"ד</b>: ראה גם לעיל (בחלק המאמרים) בהמאמר כאן ובהערות 27-28."],["6459","23","<b>הגדולה זו . . בנין בהמק\"ד</b>: ראה ברכות נח, סע\"א."],["6461","25","<b>דה' מדות . . עקרי המדות</b>: ראה זהר פינחס רנד, א. סידור שער הל\"ג בעומר דש, א. מאמרי אדה\"א בראשית ע' רפה וש\"נ. סה\"מ תרכ\"ז ע' רסב. וש\"נ."]]],[2001910569,"יבנה<sup data-n=\"6462\">26</sup> וכתי' זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"6463\">27</sup> רחמים וחסדים הם מקור העולם, וכמארז\"ל בתחילה עלה במח'<sup data-n=\"6464\">28</sup> לברוא את העולם במה\"ד ראה שאין העולם מתקיים שיתף עמו מדת החסד מדתו של אברהם<sup data-n=\"6465\">29</sup> וכמ\"ש בהבראם באברהם<sup data-n=\"6466\">30</sup>, ראה שאינו מתקיים שיתף עמו מדתו של יעקב מדה\"ר<sup data-n=\"6467\">31</sup> וכמארז\"ל על השמים נטל אש ומים ופתכן<sup data-n=\"6468\">32</sup> זה בזה ולא הוה גלדא<sup data-n=\"6469\">33</sup> עד דאגלידא ברוחא עילאה שהיא מדתו של יעקב, וזהו חג\"ת, ונו\"ה הם ענפים נצח ענף החסד והוד ענף הגבו'<sup data-n=\"6470\">34</sup> ומצינו דעיקר ההשפעה הוא מהענפי' כמו הפירות שאינם צומחים על האילן כ\"א על הענפים, וה' אלו הם עקרי המדות לכן מתניתא תנא<sup data-n=\"6471\">35</sup> רק ה' אלו, אף שיש מדה ששית כי כל בשמים וארץ הוא רק מחבר שמים וארץ<sup data-n=\"6472\">36</sup> שכל מה שיש בשמים יהי' בארץ והוא השפעה לבר מגופא, ואפי' הולדה שהיא בדומה לו הוא ג\"כ לבר מגופא דאינו דבר חדש, והמדות העיקרים הם חמש אלו, ועבודת המלאכים הוא להמשיך מי\"ה בו\"ה דה' מדות הנ\"ל הם ו\"ה וצריכים להמשיך מי\"ה דכתי' כי אמרתי עולם חסד יבנה דלצורך בריאת העולמות הי' צריכים לבנות מדת החסד<sup data-n=\"6473\">37</sup> וכתי' זכור רחמיך וחסדיך כי מעולם המה רחמים וחסדים שייכי' לעולם דענין החסד שייך כשיש זולת<sup data-n=\"6474\">38</sup> אבל בלא זולת לא שייך כלל מדת החסד וכן רחמים כו' אבל מוחין אינם שייכים לזולת כלל וכי בשביל שאין זולת לא ישכיל השכלות, ומשארז\"ל ומתלמידי יותר מכולם<sup data-n=\"6475\">39</sup> היינו להוציא מהעלם אל הגילוי, וזשארז\"ל אלפים שנה קדמה תורה לעולם<sup data-n=\"6476\">40</sup>",[["6462","26","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["6463","27","<b>זכור רחמיך וחסדיך. . המה</b>: תהלים כה, ו [בדילוג השם]. ראה זהר שמיני לח, א ובמק\"מ שם. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010262\" data-slug=\"or-hatorah-hb\" data-id=\"8159010262\">אוה\"ת</a> (יהל אור) תהלים ע' צב. ר\"ה ע' א'רפח."],["6464","28","<b>בתחילה עלה במח'</b>: ראה רש\"י בראשית א, א. לקמן הנחה ד\"ה כי תבואו וכו' ושבתה הארץ ובהערה 86 בשם הזהר. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תכ. ע' א'תמב ואילך. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' לא-לב. וש\"נ. סה\"מ תרכ\"ז ע' תלה. תורת שלום ע' 20."],["6465","29","<b>מדת החסד. . אברהם</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["6466","30","<b>בהבראם באברהם</b>: בראשית ב, ד. ראה זהר שמיני שם. ראה גם לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 36."],["6467","31","<b>יעקב מדה\"ר</b>: ראה זהר לך פז, ב. מאמרי אדה\"א בראשית ע' קנו. וש\"נ."],["6468","32","<b>נטל אש ומים ופתכן</b>: ראה ב\"ר פ\"ד, ז."],["6469","33","<b>ולא הוה גלדא</b>: ראה זהר לך עז, א."],["6470","34","<b>נצח ענף . . הגבו'</b>: ראה זהר רע\"מ פינחס רמג, סע\"א. הנסמן במאמרי אדה\"א קונטרסים ע' רכח."],["6471","35","<b>מתניתא תנא</b>: ראה לעיל הערה 23."],["6472","36","<b>כי כל . . מחבר שמים וארץ</b>: המשך הכתוב לך ה' הגדולה — דברי הימים-א כט, יא. ראה סידור שער הל\"ג בעומר דש, א ואילך."],["6473","37","<b>כי אמרתי . . לבנות מדת החסד</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה הוא אהרן ומשה ובהערה 106."],["6474","38","<b>החסד שייך כשיש זולת</b>: ראה גם אוצרות חיים בתחלתו. הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת מסעי צג, רע\"א</a>. סה\"מ תרל\"ח ס\"ע שצ. וש\"נ. תר\"ם ח\"א ע' קפה. וש\"נ."],["6475","39","<b>ומתלמידי יותר מכולם</b>: תענית ז, א. ראה גם סה\"מ תר\"ם ח\"א ע' קנב. וש\"נ."],["6476","40","<b>אלפים שנה קדמה תורה לעולם</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ. מאמר ד\"ה זה תשי\"א יום ב' דחה\"ש."]]],[2001910570,"אלפך חכ' ואלפך בינה<sup data-n=\"6478\">42</sup> הם קדמו לעולם שאינם שייכים לעולם<sup data-n=\"6477\">41</sup> כלל, וזהו עבודת המלאכים להמשיך ממוחין למדות וזהו ישר\"ה מספר תקט\"ו ת\"ק הוא חמש כלולים מי' וי' מי' מספר ת\"ק והמלאכים ממשיכים מט\"ו י\"ה בת\"ק, וזהו עץ חיים מהלך ת\"ק שנה וכתי' ועל יובל ישלח שרשיו<sup data-n=\"6479\">43</sup> מה שמו<sup data-n=\"6482\">46</sup> דההוא נהר יובל שמו<sup data-n=\"6480\">44</sup> חיים שמו חו\"ב<sup data-n=\"6481\">45</sup>, וזהו\"ע העמידה ויש בזה מעלה וחסרון מעלה שאינם מתלבשים בגופי' וחסרון דאף שע\"י אמירתם קדוש ממשיכים מוחין במדות מ\"מ א\"ז עלי' כ\"כ.\n<b>וכשם</b> שיש בחי' עמידה במלאכים כמו\"כ יש עמידה בנשמות, דנשמה קודם התלבשותה בגוף כתי' חי ה' אשר עמדתי<sup data-n=\"6483\">47</sup>, ואדרבה העמידה היא בבחי' יותר גבוה<sup data-n=\"6484\">48</sup> ואפי' לאחר שנתלבשה בגוף יש בה עבודת העמידה וכמו אשר כח בו<sup data-n=\"6485\">49</sup> לעמוד בהיכל המלך פי' שיכול לעצור א\"ע אפי' מדברי' הכרחים, וכמ\"ש בזהר דכורא קאים בחילא<sup data-n=\"6486\">50</sup> באשה קרא מושב<sup data-n=\"6487\">51</sup> ודכורא כו' ובעבודה הוא שעומד מחשבות<sup data-n=\"6488\">52</sup> זרות ורצונות זרות, דכמו שנת\"ל<sup data-n=\"6489\">53</sup> שיש הילוך בקדושה כמו\"כ יש הילוך בלעו\"ז<sup data-n=\"6490\">54</sup> וכמ\"ש ויבא הולך לאיש עשיר<sup data-n=\"6491\">55</sup> כו' ואח\"כ נק' אורח ואח\"כ איש וקאי על היצה\"ר<sup data-n=\"6492\">56</sup> בתחילה הוא כמו הולך בדבר<sup data-n=\"6493\">57</sup> מעבר בל\"א<sup data-n=\"6494\">58</sup> פאר באייגייער, וכשממלא רצונו מעט נק' אורח שעושה אכסניא עד שנעשה איש בעה\"ב ומושל ושולט וכמארז\"ל היום אומר לו כך<sup data-n=\"6495\">59</sup> ומחר אומר לו כך כו', וכשעומד מהילוך זה זהו עבודת העמידה בנשמות, ובמשכן הם קרשי המשכן דלמעלה שרפים עומדים ולמטה",[["6478","42","<b>אלפך חכ' ואלפך בינה</b>: כנצ\"ל: ואאלפך — איוב לג, ג. שבת קד, א."],["6477","41","<b>אלפים שנה . . שאינם שייכים לעולם</b>: ראה גם סה\"מ תרל\"ח ע' טז. וש\"נ. תר\"ם ח\"א ע' קפ. וש\"נ."],["6479","43","<b>ועל יובל ישלח שרשיו</b>: ירמי' יז, ח. ראה אוה\"ת ירמי' כרך א ע' שמה."],["6482","46","<b>חיים שמו</b>: ראה זהר אחרי שם. אוה\"ת ירמי' שם. סה\"מ תרל\"ח ע' תכג. וש\"נ."],["6480","44","<b>מה שמו . . יובל שמו</b>: ראה זהר יתרו פג, א. אחרי נח, א. וראה גם בכורות נה, ב. ויק\"ר ספכ\"ב."],["6481","45","<b>יובל . . חיים . . חו\"ב</b>: ראה לעיל (בחלק המאמרים) בהמאמר כאן הערה כ שיובל בחי' בינה. לקו\"ת חוקת סא, ד שחיים בחי' חכמה. לעיל שם מאמר ד\"ה וידבר כו' קדושים תהיו על יד הערה 160."],["6483","47","<b>חי ה' אשר עמדתי</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 67."],["6484","48","<b>העמידה . . יותר גבוה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370281\" data-slug=\"torah-or\" data-id=\"3901370281\">תו\"א בשלח סב, סע\"ד</a>. סה\"מ תרל\"ח ע' ת. וש\"נ. תר\"ם ח\"א ע' יב. וש\"נ."],["6485","49","<b>אשר כח בו</b>: דניאל א, ד [ושם: ואשר כח בהם]."],["6486","50","<b>דכורא קאים בחילא</b>: ראה זהר תצוה קפג, א."],["6487","51","<b>באשה קרא מושב</b>: ראה פסחים ג, א. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159780114\" data-slug=\"or-hatorah-hb\" data-id=\"8159780114\">אוה\"ת ואתחנן ע' קיד</a>. כרך ו ע' ב'קצג. משלי כרך א ס\"ע תקסז ואילך."],["6488","52","<b>מחשבות</b>: אוצ\"ל: ממחשבות."],["6489","53","<b>שנת\"ל</b>: אולי כתוב: שית\"ל שיתבאר לקמן."],["6490","54","<b>בלעו\"ז</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד."],["6491","55","<b>ויבא הולך לאיש עשיר</b>: שמו\"ב יב, ד — ושם: העשיר."],["6492","56","<b>הולך . . אורח . . איש . . היצה\"ר</b>: רש\"י שם."],["6493","57","<b>בדבר</b>: אוצ\"ל: בדרך."],["6494","58","<b>בל\"א</b>: בלשון אידיש. ראה גם סה\"מ תרל\"ח ע' ה. וש\"נ."],["6495","59","<b>היום אומר לו כך</b>: ראה שבת קה, ב."]]],[2001910571,"עצי שיטים עומדים<sup data-n=\"6496\">60</sup> שיטים הוא דאין אדם עובר עבירה<sup data-n=\"6498\">62</sup> אא\"כ נכנס בו רוח שטות<sup data-n=\"6497\">61</sup>, אבל כשעצי שיטים עומדים עי\"ז ממשיך ג\"כ מבחי' י\"ה, וזהו הללו יה<sup data-n=\"6499\">63</sup> וזהו\"ע ט\"ו<sup data-n=\"6500\">64</sup> תשבחות דישתבח<sup data-n=\"6501\">65</sup> שהם נגד ט\"ו תי' דבפסוק את ה' האמרת<sup data-n=\"6502\">66</sup> כו' וט\"ו ווין דאוי\"צ<sup data-n=\"6503\">67</sup> הכל מכוון אחד ההמשכה מי\"ה בו\"ה.\n<b>עוד</b> מדרי' יש מ\"ש ונתתי לך מהלכים בין העומדים האלה, דבחי' עמידה שנת\"ל הוא בחי' בכל לבבך ובכל נפשך<sup data-n=\"6504\">68</sup> והו\"ע ממכ\"ע ע\"י ההתבוננות דלאהבה את ה' אלקיך כי הוא חייך<sup data-n=\"6505\">69</sup> כמו האדם שאוהב חיי נפשו כמו\"כ יהי' לו אהבה לאלקות, אבל ההילוך הוא כשיתבונן איך דא\"ס למעלה עד אין קץ<sup data-n=\"6506\">70</sup> ולמטה עד אין תכלית ולגדולתו אין חקר<sup data-n=\"6507\">71</sup> ועי\"ז יבא לתשובה בחילא יתיר<sup data-n=\"6508\">72</sup> בכל מאדך בלי גבול<sup data-n=\"6509\">73</sup> והוא הרגל השלישי. וע\"י ההילוך מלמטה כמ\"ש אם בחקתי תלכו<sup data-n=\"6510\">74</sup> וכמ\"ש גבי אברהם התהלך לפני<sup data-n=\"6511\">75</sup> עי\"ז נמשך ההילוך מלמעלה וכמ\"ש והתהלכתי בתוככם<sup data-n=\"6512\">76</sup>. וזהו מ\"ש עד יעבור עמך הוי', דכתי' ויקרא הוי' הוי'<sup data-n=\"6514\">78</sup> שיש ב' שמות הוי' א' שם הוי' דסדר השתל', י' חכמה<sup data-n=\"6515\">79</sup> ה' בינה ו\"ה מדות ודיבור<sup data-n=\"6516\">80</sup>, ויש שם הוי' שלמעלה מסדר השתל', עד יעבור עמך הוי' למעלה משם הוי'<sup data-n=\"6513\">77</sup> דסדר השתל', וכמו אתהלך לפני הוי'<sup data-n=\"6517\">81</sup> לפני שם הוי' דסדר השתל'. וזהו הפך ים ליבשה<sup data-n=\"6518\">82</sup> בנהר יעברו ברגל שם נשמחה בו,",[["6496","60","<b>דלמעלה שרפים . . עצי שטים עומדים</b>: ראה שמו\"ר פל\"ג, ד. תרומה כו, טו."],["6498","62","<b>דאין אדם עובר עבירה</b>: סוטה ג, א. ראה מאמרי אדה\"א דברים ח\"ב ע' תרמה. וש\"נ."],["6497","61","<b>שיטים . . שטות</b>: סנהדרין קו, א."],["6499","63","<b>הללו יה</b>: ראה זהר ויחי רלב, ב. סידור שחרית נו, ב ואילך ובהנסמן לשם. מאמרי אדה\"א שמות ח\"א ע' יב. וש\"נ. אוה\"ת (יהל אור) תהלים ע' תקנז ואילך וע' תרצג."],["6500","64","<b>ט\"ו . . דישתבח . . האמרת . . ווי\"ן</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450596\" data-slug=\"or-hatorah-hb\" data-id=\"8316450596\">אוה\"ת תבוא ע' תתרסו</a> בשם הבחיי תרומה כה, ז. נדפס גם באוה\"ת על סידור ס\"ע קט ואילך. שם ס\"ע קי ואילך. סה\"מ תרנ\"ח ס\"ע ריד ואילך."],["6501","65","<b>ט\"ו תשבחות דישתבח</b>: ראה גם לעיל (בחלק המאמרים) בהמאמר כאן הערה 73."],["6502","66","<b>את ה' האמרת</b>: תבוא כו, יז."],["6503","67","<b>וט\"ו ווין דאוי\"צ</b>: ראה פע\"ח שער הק\"ש ש\"ח, פכ\"ח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680334\" data-slug=\"torat-chaim\" data-id=\"2300680334\">תו\"ח וישב רי, א</a> הערה 14."],["6504","68","<b>בבל לבבך ובבל נפשך</b>: ואתחנן ו, ה."],["6505","69","<b>דלאהבה את ה' אלקיך כי הוא חייך</b>: נצבים ל, כ [בדילוג]."],["6506","70","<b>דא\"ס למעלה עד אין קץ</b>: ראה ז\"ח יתרו לד, ג. ת\"ז תי\"ט (מ, ב). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670361\" data-slug=\"torat-chaim\" data-id=\"2300670361\">תו\"ח נח סט, ב</a> ובהערה 11."],["6507","71","<b>ולגדולתו אין חקר</b>: תהלים קמה, ג."],["6508","72","<b>לתשובה בחילא יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540123\" data-slug=\"torat-chaim\" data-id=\"2300540123\">תו\"ח שמות ח\"א לז, א</a>. וש\"נ. פלח הרמון אחרי ע' קפח ואילך."],["6509","73","<b>בכל מאדך בלי גבול</b>: ואתחנן ו, ה. ראה גם אגה\"ק סי\"ז. סה\"מ תר\"ם ח\"א ע' תכט. וש\"נ."],["6510","74","<b>אם בחקתי תלכו</b>: בחוקותי כו, ג. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380471\" data-slug=\"likkutei-torah\" data-id=\"4001380471\">לקו\"ת שלח לה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380270\" data-slug=\"likkutei-torah\" data-id=\"4001380270\">לט, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380279\" data-slug=\"likkutei-torah\" data-id=\"4001380279\">בחוקותי מה, א</a>. מז, ב."],["6511","75","<b>התהלך לפני</b>: לך יז, א."],["6512","76","<b>והתהלכתי בתוככם</b>: בחוקותי כו, יב."],["6514","78","<b>ויקרא הוי' הוי'</b>: תשא לד, ו. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה מגילה נקראת ובהערה 232."],["6515","79","<b>י' חכמה</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["6516","80","<b>ו\"ה מדות ודיבור</b>: ראה גם סה\"מ תר\"ם ח\"ב ע' תצה וע' תשטו."],["6513","77","<b>עד יעבור . . למעלה משם הוי'</b>: בשלח טו, טז. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370059\" data-slug=\"torah-or\" data-id=\"3901370059\">תו\"א לך יג, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370290\" data-slug=\"torah-or\" data-id=\"3901370290\">בשלח סה, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380048\" data-slug=\"likkutei-torah\" data-id=\"4001380048\">לקו\"ת בשלח ב, ג</a>. ש\"א כ, ב ובהערה 31. סה\"מ תר\"ם ח\"א ע' רמו. וש\"נ."],["6517","81","<b>אתהלך לפני ה'</b>: תהלים קטז, ט."],["6518","82","<b>הפך ים ליבשה</b>: תהלים סו, ו."]]],[2001910572,"דנהר יוצא מעדן<sup data-n=\"6519\">83</sup> וכתי' משם יפרד<sup data-n=\"6520\">84</sup> מפני שנמשך בכל עולם לפ\"ע עד שנעשה העלמות והסתרים, אך בנהר יעברו ברגל ע\"י רגל השלישי עי\"ז בעבר הנהר<sup data-n=\"6521\">85</sup> למעלה מהנהר וממילא נמשך גילוי אלקות למטה כמו למעלה, שם נשמחה בו בחי' א\"ס עצומ\"ה, וזהו שלש רגלים תחוג ל\"י א\"ס עצומ\"ה.\n<b>ושרש</b> ההפרש בין עבודת המלאכים לעבודת הנשמות בבחי' הילוך הוא, דמלאכים ממשיכים זיווג חיצוני דחו\"ב<sup data-n=\"6522\">86</sup> שהוא אין ויש<sup data-n=\"6523\">87</sup>, חכ' נק' אין והחכ' מאין תמצא<sup data-n=\"6525\">89</sup> ובינה נק' יש להנחיל אוהבי יש<sup data-n=\"6526\">90</sup> והוא ראשית ההשתל'<sup data-n=\"6524\">88</sup> שהו\"ע השתל' עו\"ע<sup data-n=\"6527\">91</sup> שהעלול מלביש רק מחצה התחתון<sup data-n=\"6528\">92</sup> מהעילה וכן העלול שלמטה ממנו מלביש מחצה התחתון מהעלול דעילה הראשונה, וכמו שכל ומדות מח' ודיבור דהמדות מלבישים רק מחצה התחתון מהשכל ולא כל השכל מלובש בהמדה, ולכן האור מתמעט למטה מטה עד שאפשר להיות העלם והסתר, ולכן אף שממשיכים בחי' חכ' ואוא\"ס המלובש בו<sup data-n=\"6529\">93</sup>, הכל רק בחי' חיצוניות שהוא ראשית ההשתל', אבל נשמות ע\"י ההילוך ממשיכים בחי' פנימיות דשם מאיר א\"א ועתיק ועוד למעלה יותר עד א\"ס ממש, וזהו קול דודי הנה זה בא מדלג על ההרים ודילוג ברגל אחת<sup data-n=\"6531\">95</sup> הוא רגל השלישי, וגילוי זה הי' ביצ\"מ<sup data-n=\"6530\">94</sup> ובמורא גדול זו גילוי שכינה<sup data-n=\"6532\">96</sup> ומבואר במ\"א בחי' מל' דא\"ס<sup data-n=\"6533\">97</sup>. וזהו מצה זו שאנו אוכלים על שום מה על שום שלא הספיק בצקת של אבותינו להחמיץ עד שנגלה עליהם מלך מלכי המלכים הקב\"ה<sup data-n=\"6534\">98</sup>, מלכים",[["6519","83","<b>בנהר יעברו . . יוצא מעדן</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380123\" data-slug=\"likkutei-torah\" data-id=\"4001380123\">לקו\"ת שמע\"צ פח, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380139\" data-slug=\"likkutei-torah\" data-id=\"4001380139\">צו יא, ד</a>. טו, ד."],["6520","84","<b>משם יפרד</b>: בראשית ב, י — ושם: ומשם."],["6521","85","<b>בעבר הנהר</b>: יהושע כד, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380278\" data-slug=\"likkutei-torah\" data-id=\"4001380278\">לקו\"ת בחוקותי מז, א</a>."],["6522","86","<b>זיווג חיצוני דחו\"ב</b>: ראה לעיל (בחלק המאמרים) בהמאמר כאן הערה 111."],["6523","87","<b>דחו\"ב שהוא אין יש</b>: ראה הנסמן בביאוה\"ז להצ\"צ כרך ב ע' תתרא. מאמרי אדה\"א בראשית ע' ב. דרושי חתונה ח\"ב ע' תעג. סה\"מ תרכ\"ט ע' רעח."],["6525","89","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["6526","90","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["6524","88","<b>חכ' . . ראשית ההשתל'</b>: ראה רמ\"ז לזהר ואתחנן רסה, ב — בדפי הספר קצד, א [ד\"ה לארקא] וסע\"ב. סה\"מ תר\"ם ח\"א ע' רי. וש\"נ."],["6527","91","<b>עו\"ע</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">לקו\"ת ברכה צה, ב</a>: הנזכר בספרים. שה\"ש א, ב: כמ\"ש בספרים. ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו."],["6528","92","<b>שהעלול מלביש . . התחתון</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 89."],["6529","93","<b>חכ' ואוא\"ס המלובש בו</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא</a> פי\"ח. פל\"ה בהג\"ה [ראה במ\"מ הגהות והע\"ק לפי\"ח. ופל\"ה]. אגה\"ק ס\"כ קל, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380365\" data-slug=\"likkutei-torah\" data-id=\"4001380365\">לקו\"ת במדבר יד, ב</a> [ושם מציין: ”בע\"ח שער מ\"ז פ\"ג\" (ולפנינו הוא פ\"ב) ”ושער ב' במה\"ב פ\"א פ\"ג\" — ולפנינו הוא בשער סדר אצי' ש\"ג]. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540658\" data-slug=\"torat-chaim\" data-id=\"2300540658\">תו\"ח שמות ח\"א ז, ד</a> הערה 333. סה\"מ תרנ\"ח ע' יב."],["6531","95","<b>ודילוג ברגל אחת</b>: אהלות פ\"ח, מ\"ה ובפיה\"מ ורע\"ב שם. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381190\" data-slug=\"likkutei-torah\" data-id=\"4001381190\">לקו\"ת שה\"ש טו, ב</a>."],["6530","94","<b>קול דודי . . מדלג . . ביצ\"מ</b>: שה\"ש ב, ח. ראה רש\"י שם."],["6532","96","<b>ובמורא גדול זו גילוי שכינה</b>: תבוא כו, ח. בספרי שם. הגדה של פסח."],["6533","97","<b>בחי' מל' דא\"ס</b>: ראה גם שע\"ת קמה, ד ובהערה 41. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540475\" data-slug=\"torat-chaim\" data-id=\"2300540475\">תו\"ח בא ח\"א ק, ג</a>. וש\"נ. (לעיל בחלק המאמרים) מאמר ד\"ה וחג הקציר בכורי מעשיך על יד הערה כח."],["6534","98","<b>מצה זו . . הקב\"ה</b>: נוסח הגדה של פסח."]]],[2001910573,"הוא כמ\"ש הנה המלכים נועדו<sup data-n=\"6536\">100</sup> הם יהודה ויוסף בחי' צ\"ע<sup data-n=\"6537\">101</sup>, מלכי חו\"ב, מלך בחי' כתר<sup data-n=\"6535\">99</sup>, וכ\"ז ממשיכים ע\"י ההילוך, ומדרי' זו הוא בחי' צדיק שלמעלה מישר וכמ\"ש בזהר<sup data-n=\"6538\">102</sup>.\n<b>וצ\"ל</b> למה דוקא נשמה בגוף מגיע לבחי' צדיקים דכתי' ועמך כולם צדיקים<sup data-n=\"6539\">103</sup> קאי דוקא על נשמות בגופי'. והענין דהנה הצמיחה היא בארץ דוקא אף דשמים למעלה מארץ וכמ\"ש שמים לרום<sup data-n=\"6540\">104</sup> מ\"מ עיקר הצמיחה בארץ דוקא, וכמו הצומח שמחי' את האדם<sup data-n=\"6541\">105</sup> אף שהמדבר למעלה מהצומח ובניהם<sup data-n=\"6542\">106</sup> מפסיק בע\"ח, מ\"מ הצומח מחי' את האדם, דכל אור שהוא למעלה יותר יורד למטה יותר<sup data-n=\"6543\">107</sup>, א\"כ בהצומח יש ניצוץ דתהו עליון יותר לכן ע\"י שהאדם מבררו מחי' אותו, א\"כ יתרון האור מתוך החשך<sup data-n=\"6544\">108</sup> וכמו אין אדם רואה מתוך הלבן שבעין אלא מתוך השחור<sup data-n=\"6545\">109</sup>, וכמו מים חיים הם דוקא לאחר שבוקעים את עפר הארץ<sup data-n=\"6546\">110</sup> וכמו שהם בים אינם מ\"ח<sup data-n=\"6547\">111</sup>, וכמו\"כ כאן דנר ה' נשמת אדם<sup data-n=\"6548\">112</sup> וכמו הנר שמאיר במקום החשך כמו\"כ הנשמה מברר הגוף והנה\"ב ועי\"ז נמשך בחי' א\"ס שלמעלה מסדר השתל', ועיקר גילוי בחי' זו יהי' לע\"ל אך הארה מבחי' זו מאיר עכשיו ג\"כ כו'.",[["6536","100","<b>הנה המלכים נועדו</b>: תהלים מח, ה. ראה זהר ויגש רו, א."],["6537","101","<b>ויוסף בחי' צ\"ע</b>: ראה זהר ויצא קנג, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370201\" data-slug=\"torah-or\" data-id=\"3901370201\">תו\"א ויגש מד, ג</a>. סה\"מ תר\"ם ח\"ב ע' תרעו. וש\"נ."],["6535","99","<b>מלכים . . כתר</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה והי' אור הלבנה ובהערה 29."],["6538","102","<b>צדיק שלמעלה מישר . . בזהר</b>: ראה זהר אחרי נט, סע\"א. רשב\"א — בע\"י — ספ\"ק דתענית הובא במהרש\"א שם. לעיל (בחלק המאמרים) בהמאמר כאן."],["6539","103","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["6540","104","<b>שמים לרום</b>: משלי כה, ג."],["6541","105","<b>הצומח שמחי' את האדם</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 138."],["6542","106","<b>ובניהם</b>: אולי כתוב: וביניהם."],["6543","107","<b>דכל אור . . למטה יותר</b>: ראה ש\"א שער הפורים נח, א. סה, א. סה\"מ תרל\"ח ע' תב. וש\"נ."],["6544","108","<b>יתרון האור מתוך החשך</b>: ע\"פ קהלת ב, יג."],["6545","109","<b>אין אדם . . מתוך השחור</b>: ראה ויק\"ר פל\"א, ח. לעיל (בחלק המאמרים) בהמאמר כאן הערה 141."],["6546","110","<b>מים חיים . . עפר הארץ</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370093\" data-slug=\"torah-or\" data-id=\"3901370093\">תו\"א תולדות כ, א</a>. ב. סהמ\"צ להצ\"צ ע' 306. אוה\"ת חוקת ע' תתס. מאמרי אדה\"א קונטרסים ס\"ע שצח ואילך. וש\"נ. לקמן הנחה ד\"ה כתר יתנו לך על יד הערה 46."],["6547","111","<b>מים . . שהם בים אינם מ\"ח</b>: ראה פרה פ\"ח, ה\"ח. מקואות פ\"ה, מ\"ד. רמב\"ם הל' פרה אדומה פ\"ו, ה\"י. מקואות פ\"ט, ה\"ח. הי\"ב."],["6548","112","<b>דנר ה' נשמת אדם</b>: משלי כ, כז."]]],[2001910574,"<h3>את חג המצות תשמור</h3>\n<b>שבת חוהמ\"פ</b>\n<b>את</b> חג המצות תשמור<sup data-n=\"6549\">1</sup> שבעת ימים תאכל מצות כאשר צויתיך למועד חדש האביב כי בו יצאת ממצרים<sup data-n=\"6550\">2</sup> וחג הקציר בכורי מעשיך אשר תזרע בשדה וחג האסיף בצאת השנה באספך<sup data-n=\"6551\">3</sup> כו'. ונת\"ל<sup data-n=\"6552\">4</sup> הקושי' מה הרגלים להתבואות. והענין דהנה כתי' קדש ישראל לה' ראשית תבואתה<sup data-n=\"6553\">5</sup> כתי' בה' והניקוד בחולם כאילו כתי' בו' והוא תבואת ה' ותבואת ו' והם פסח ועצרת, פסח אז זמן בישול שעורים<sup data-n=\"6554\">6</sup> שיעור ה'<sup data-n=\"6555\">7</sup>, ובעצרת על פירות האילן<sup data-n=\"6556\">8</sup> וכתי' כי האדם עץ השדה<sup data-n=\"6557\">9</sup>, וזהו תבואת ו', וצ\"ל למה ישראל נק' תבואה. ובת\"י אי'<sup data-n=\"6558\">10</sup> קדש ישראל לה' כתרומה ראשית תבואתה כראשית קציר שלפני העומר, וצ\"ל למה נק' בשם תבואה. והענין דהנה כתי' וזרעתי' לי בארץ<sup data-n=\"6559\">11</sup> דירידת הנשמה בגוף נק' בשם זריעה, וכן גלות בבל נק' זריעה<sup data-n=\"6560\">12</sup> זרוע בבל<sup data-n=\"6561\">13</sup>, וצ\"ל הזריעה דהנשמה. והענין דהנה כשזורע גרעין צריך לרקוב תחילה<sup data-n=\"6562\">14</sup> וכמו\"כ הנשמה קודם התלבשותה בגוף כתי' חי ה' אשר עמדתי לפניו<sup data-n=\"6563\">15</sup> שעמדה בביטול דנת\"ל<sup data-n=\"6564\">16</sup> דמלאכים עומדים בביטול ומכ\"ש נשמות<sup data-n=\"6565\">17</sup> שהם מפנימיות הכלים<sup data-n=\"6566\">18</sup>, וירדה למטה בגוף ונה\"ב שמעלים ומסתיר וזהו הרקבון, מכ\"ש גלות בבל שנק' זריעה שהיא רקבון בטול עצמותו, והעיקר הזריעה בשביל הצמיחה, כלום אדם זורע סאה<sup data-n=\"6567\">19</sup> להוציא ממנו",[["6549","1","<b>את חג המצות תשמור</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה ומעתה צ\"ל למה הוקבעו המועדים על זמן התבואה שנדפס לעיל בחלק המאמרים. וש\"נ. כמו\"כ ישנו עוד הנחה מדרוש זה ונדפסה לקמן בחלק ההנחות.\nהנחה זו נזכרה לעיל בהנחה ד\"ה זאת תהי' תורת המצורע על יד הערה 27."],["6550","2","<b>את חג . . שבעת ימים . . ממצרים</b>: משפטים כג, טו."],["6551","3","<b>וחג הקציר . . וחג האסיף . . באספך</b>: שם כג, טז."],["6552","4","<b>ונת\"ל</b>: הנחה ד\"ה שלש רגלים תחוג לי בתחילתה."],["6553","5","<b>קדש ישראל לה' ראשית תבואתה</b>: ירמי' ב, ג. ראה גם לעיל הנחה ד\"ה קדש ישראל לה' ובהערה 2."],["6554","6","<b>פסח אז זמן בישול שעורים</b>: ראה מנחות סח, ב. אבן עזרא משפטים כג, טז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301730177\" data-slug=\"likkutei-sichot\" data-id=\"1301730177\">לקו\"ש משפטים כרך לו ע' 109</a> ואילך."],["6555","7","<b>שעורים שיעור ה'</b>: נסמן לקמן בהערה 39."],["6556","8","<b>ובעצרת על פירות האילן</b>: ר\"ה פ\"א, מ\"ב (טז, א)."],["6557","9","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."],["6558","10","<b>ובת\"י אי'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010128\" data-slug=\"or-hatorah-hb\" data-id=\"8159010128\">אוה\"ת</a> ירמי' כרך א ס\"ע שכב ואילך — נדפס גם באוה\"ת פינחס ע' א'רכא ואילך."],["6559","11","<b>וזרעתי' לי בארץ</b>: הושע ב, כה. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370274\" data-slug=\"torah-or\" data-id=\"3901370274\">תו\"א בשלח סא, א</a>. הנסמן בסה\"מ תרל\"ג ח\"א כאן ע' קמח."],["6560","12","<b>גלות בבל נק' זריעה</b>: ראה בהערה הבאה."],["6561","13","<b>זרוע בבל</b>: אולי צ\"ל: וזהו זרובבל זרוע בבל — ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 13."],["6562","14","<b>כשזורע גרעין צריך לרקוב תחילה</b>: ראה אגה\"ק ס\"ח (קיג, א). מאמרי אדה\"א ויקרא ח\"ב ע' תקצח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540229\" data-slug=\"torat-chaim\" data-id=\"2300540229\">תו\"ח שמות ח\"א ב, ב</a>. וש\"נ. סה\"מ תר\"ם ח\"א ע' רב. וש\"נ."],["6563","15","<b>חי ה' אשר עמדתי לפניו</b>: לשון הכתוב מלכים-ב ה, טז. בסה\"מ תש\"ד ע' 153 צויין: ראה מ\"א יז, א (זח\"ג סח, ב. זח\"א רלג, ב)."],["6564","16","<b>דנת\"ל</b>: הנחה ד\"ה שלש רגלים תחוג לי על יד הערה 14 ואילך."],["6565","17","<b>ומכ\"ש נשמות</b>: ראה שם על יד הערה 47 ואילך."],["6566","18","<b>נשמות שהם מפנימיות הכלים</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה אז ישיר משה רפ\"ב. וש\"נ."],["6567","19","<b>כלום אדם זורע סאה</b>: ראה פסחים פז, ב. (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 8."]]],[2001910575,"כמה כורים, וכמו\"כ זריעה דהנשמה היא בשביל הצמיחה, והוא מ\"ש ברוך ה' אלקי ישראל מן העולם ועד העולם<sup data-n=\"6568\">20</sup> מעדאת\"כ לעלדאת\"ג<sup data-n=\"6569\">21</sup> ופי' הפשוט מעוה\"ז לעוה\"ב<sup data-n=\"6570\">22</sup> פי' שבחי' עלדאת\"כ יאיר בעוה\"ב, ושרש ב' עולמות אלו הם ב' שמות הוי'<sup data-n=\"6571\">23</sup> וזהו שנת\"ל<sup data-n=\"6572\">24</sup> בנהר יעברו ברגל<sup data-n=\"6573\">25</sup> ע\"י רגל השלישי יגיע לבחי' עד יעבור עמך הוי'<sup data-n=\"6574\">26</sup> היינו שימשיך בחי' הוי' דלעילא שרש עלמדא\"כ בעוה\"ב, והארה מבחי' זו מאיר ברגלים.\n<b>וסדר</b> הרגלים תחילה תחילה<sup data-n=\"6575\">27</sup> צ\"ל פסח, שבעת ימים תאכל מצות כו', דהנה אמרז\"ל אין התינוק יודע לקרות אבא<sup data-n=\"6576\">28</sup> עד שיטעום טעם דגן, והתנוק כשקורא אבא אי\"ז מצד השגה שמשיג מפני מה הוא אביו מפני שהולידו, ומ\"מ הוא קורא בתוקף ובחוזק ובגעגועים, והוא ע\"י טעימת טעם דגן, וכמו\"כ יובן דכדי שיהי' הכרה והרגשה בבחי' כי אתה אבינו<sup data-n=\"6577\">29</sup> הוא ע\"י לחם מצה, דתנוק שצריך לקרות או\"א הגשמים די באכילת לחם חמץ אבל להיות ההכרה באבינו שבשמים זהו דוקא ע\"י לחם מצה שהוא לחם דשפלות וכתי' מרום וקדוש אשכון את דכא ושפל רוח<sup data-n=\"6578\">30</sup>, דחמץ הוא הגבהה והתנשאות ובעבודה הוא גאוה וגסות ואין אני והוא יכולין לדור<sup data-n=\"6580\">32</sup>, אבל מצה הוא לחם שפלות<sup data-n=\"6579\">31</sup> לכן הוא כלי להשראת אלקות. וז\"ש אח\"כ כאשר צויתיך למועד חדש האביב, אבי\"ב ר\"ת א\"ב י\"ב<sup data-n=\"6581\">33</sup>, א\"ב ה\"ז בחי' כי אתה אבינו וי\"ב הוא י\"ב שבטים<sup data-n=\"6582\">34</sup>, ואביב כולל שניהם להורות על התחברות י\"ב שבטים עם אלקות, ופי' תי' אביב ל' מחובר כמו קישות שהתליע באיבו<sup data-n=\"6583\">35</sup> בעודו מחובר, וחודש האביב הוא כמ\"ש החודש הזה לכם ר\"ח ראשון הוא לכם לחדשי השנה<sup data-n=\"6584\">36</sup>, ראשון בחי' אני ראשון<sup data-n=\"6585\">37</sup>, ושיהי' בחי' ראשון לכם הוא בחודש האביב שאז זמן",[["6568","20","<b>ברוך ה' . . ועד העולם</b>: תהלים קו, מח־ דברי הימים-א טז, לו. ראה זהר ויצא קנח, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541020\" data-slug=\"torat-chaim\" data-id=\"2300541020\">תו\"ח שמות ח\"א יח, ג</a>. וש\"נ."],["6569","21","<b>מעדאת\"כ . . לעלדאת\"ג</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>."],["6570","22","<b>מעוה\"ז לעוה\"ב</b>: ראה תרגום ורש\"י לתהלים שם. מצו\"ד לדברי הימים-א שם."],["6571","23","<b>ב' שמות הוי'</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה מגילה נקראת ובהערה 232."],["6572","24","<b>שנת\"ל</b>: הנחה ד\"ה שלש רגלים תחוג לי על יד הערה 77 ואילך."],["6573","25","<b>בנהר יעברו ברגל</b>: תהלים סו, ו."],["6574","26","<b>עד יעבור עמך הוי'</b>: בשלח טו, טז. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370059\" data-slug=\"torah-or\" data-id=\"3901370059\">תו\"א לך יג, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370290\" data-slug=\"torah-or\" data-id=\"3901370290\">בשלח סה, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380048\" data-slug=\"likkutei-torah\" data-id=\"4001380048\">לקו\"ת בשלח ב, ג</a>. ש\"א כ, ב ובהערה 31. סה\"מ תר\"ם ח\"א ע' רמו. וש\"נ."],["6575","27","<b>תחילה תחילה</b>: כ\"ה בגוכתי\"ק."],["6576","28","<b>אין התינוק יודע לקרות אבא</b>: ראה ברכות מ, סע\"א. מאמרי אדה\"א דברים ח\"א ע' רמה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540734\" data-slug=\"torat-chaim\" data-id=\"2300540734\">תו\"ח בא ח\"א צה, ב</a>. וש\"נ."],["6577","29","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["6578","30","<b>מרום וקדוש אשכון את דכא ושפל רוח</b>: ישעי' נז, טו [ושם: ואת — אבל כ\"ה בכ\"מ ומהם: סה\"מ תרכ\"ז ע' קמג וע' רא. תרל\"ח ס\"ע נד. תר\"ם ח\"ב ע' תתכב. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 34]."],["6580","32","<b>ואין אני והוא יכולין לדור</b>: סוטה ה, א. ערכין טו, ב."],["6579","31","<b>דחמץ הוא הגבהה . . מצה . . שפלות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380130\" data-slug=\"likkutei-torah\" data-id=\"4001380130\">לקו\"ת צו יג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381188\" data-slug=\"likkutei-torah\" data-id=\"4001381188\">שה\"ש יד, ד</a>. סה\"מ תר\"ם ח\"א ע' ריב."],["6581","33","<b>אביב ר\"ת אב י\"ב</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה קדש ישראל לה' פ\"ה ובהערה 178."],["6582","34","<b>וי\"ב הוא י\"ב שבטים</b>: ראה גם לעיל שם."],["6583","35","<b>קישות שהתליע באיבו</b>: ראה חולין נח סע\"א. סז סע\"א ואילך."],["6584","36","<b>החדש הזה . . לחדשי השנה</b>: בא יב, ב."],["6585","37","<b>אני ראשון</b>: ישעי' מד, ו."]]],[2001910576,"ההתחברות, ואז זמן כי השעורה אביב<sup data-n=\"6586\">38</sup> פי' שיעור ה'<sup data-n=\"6587\">39</sup> בהבראם בה' בראם<sup data-n=\"6588\">40</sup> ושיעור ה' כחו\"ח לפום שיעורה דלי'<sup data-n=\"6589\">41</sup> לפום מה דמשער בליבי', דלפ\"ע ההתבוננות במקור התהוות העולמות מבחי' ה' לפ\"ע זה ההתקשרות באלקות, כי בו יצאת ממצרים, מצרי' הוא ערות הארץ<sup data-n=\"6590\">42</sup> וישראל שהיו שם היו משוקע במ\"ט שע\"ט<sup data-n=\"6591\">43</sup>, וע\"י המצה יצאו ממצרים, וזהו תחילת העבודה כמ\"ש זה השער לה'<sup data-n=\"6592\">44</sup> דא תרעא לעלאה<sup data-n=\"6593\">45</sup>, בזאת יבא אהרן<sup data-n=\"6594\">46</sup> אל הקדש, וכמ\"ש בזהר ובא לקרן בקדמיתא<sup data-n=\"6595\">47</sup>, דהקרן בפ\"ע הוא אינו מציאות כלל<sup data-n=\"6596\">48</sup> והו\"ע קבעומ\"ש, וכמו טלית ותפילין, דתפילין גבוהים מטלית דציצית הם תשמישי מצוה<sup data-n=\"6597\">49</sup> ותפילין תשמישי קדושה<sup data-n=\"6598\">50</sup>, ומ\"מ מקדימים טלית לתפילין<sup data-n=\"6599\">51</sup> מפני שהוא פריסא דמלכא<sup data-n=\"6600\">52</sup>, וכן תש\"י ותש\"ר דתש\"ר קדושתו חמור<sup data-n=\"6601\">53</sup> ומ\"מ מקדימים התש\"י<sup data-n=\"6602\">54</sup> מפני שצ\"ל כסדר המדרגות, וכמו\"כ כאן צ\"ל תחילה בחי' שעורה.\n<b>ואח\"כ</b> בשבועות אז זמן קציר חטים<sup data-n=\"6603\">55</sup> וכמ\"ש וחג הקציר בכורי מעשיך כו' וצ\"ל והלא ביו\"ט אסור לקצור<sup data-n=\"6604\">56</sup>, וגם מהו קציר חטים דוקא. והענין דהנה כתי' עניך בשדה אשר יקצרון<sup data-n=\"6605\">57</sup> ואי' במדרש דעניך הם סנהדרין שנק' עיני העדה<sup data-n=\"6606\">58</sup>, ומשל העינים הוא שכל הגוף נמשך אחר העינים כמ\"ש ולא תתורו אחרי לבבכם<sup data-n=\"6607\">59</sup>",[["6586","38","<b>כי השעורה אביב</b>: וארא ט, לא."],["6587","39","<b>השעורה . . שיעור ה'</b>: זהר בלק קפח, ב."],["6588","40","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב. פרש\"י עה\"פ."],["6589","41","<b>כחו\"ח לפום שיעורה דלי'</b>: ראה תניא בהקדמה (ד, א) ע\"פ זהר וירא קג, ריש ע\"ב. וראה גם זהר ח\"ש קכט, ב."],["6590","42","<b>מצרי' הוא ערות הארץ</b>: מקץ מב, ט. יב. ראה קה\"ר פ\"א, ד בסופה. ע\"ח שער ציור עולמות שמ\"ג, פ\"א."],["6591","43","<b>וישראל . . משוקע במ\"ט שע\"ט</b>: ראה ז\"ח יתרו לא, א. סה\"מ תר\"ם ח\"א ע' קמב. וש\"נ."],["6592","44","<b>זה השער לה'</b>: תהלים קיח, כ. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 39."],["6593","45","<b>דא תרעא לעלאה</b>: ראה זהר בהקדמה ח, רע\"א. יא, ב."],["6594","46","<b>בזאת יבא אהרן</b>: אחרי טז, ג. ראה זהר אחרי נו, ב."],["6595","47","<b>ובא לקרן בקדמיתא</b>: ראה זבחים נג, רע\"א (במשנה). זהר במדבר קכ, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרט ואילך. ביאוה\"ז במדבר קמד, ב ואילך. מאמרי אדה\"ז הנחות הר\"פ ע' נב ואילך. תקס\"ז ע' קסה ואילך. ביאוה\"ז להצ\"צ במדבר כרך א' ע' תסד ואילך."],["6596","48","<b>דהקרן . . אינו מציאות כלל</b>: ראה גם בהדרושים שבהערה שלפנ\"ז. אוה\"ת ישעי' כרך א' ע' קלו. סה\"מ תרכ\"ט ע' לח וע' רפט."],["6597","49","<b>דציצית הם תשמישי מצוה</b>: ראה שו\"ע אדה\"ז הל' ציצית סכ\"א, ס\"א. הל' תפילין שבהערה הבאה."],["6598","50","<b>ותפילין תשמישי קדושה</b>: ראה שו\"ע אדה\"ז הל' תפילין סמ\"ב, ס\"ו. אבל כ\"ה בכ\"מ — ראה סה\"מ תר\"ם ח\"א ע' שא. וש\"נ."],["6599","51","<b>מקדימין טלית לתפילין</b>: ראה שו\"ע אדה\"ז הל' תפילין רסכ\"ה. ובאו\"א ראה אמ\"ב שער הציצית צא, ב. צה, ד."],["6600","52","<b>טלית . . פריסא דמלכא</b>: ראה זהר סבא משפטים צז, ב. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרמא. מאמרי אדה\"א במדבר ח\"ג ע' א'רפ לע' א'מד."],["6601","53","<b>דתש\"ר קדושתו חמור</b>: ראה שו\"ע אדה\"ז הל' תפילין סכ\"ה , סי\"ד."],["6602","54","<b>מקדימים התש\"י</b>: ראה שו\"ע אדה\"ז הל' תפילין שם, סי\"ב."],["6603","55","<b>בשבועות אז זמן קציר חטים</b>: תשא לד, כב."],["6604","56","<b>ביו\"ט אסור לקצור</b>: חגיגה יח, א."],["6605","57","<b>עניך בשדה אשר יקצרון</b>: רות ב, ט."],["6606","58","<b>במדרש . . סנהדרין שנק' עיני העדה</b>: שלח טו, כד. ראה רו\"ר פ\"ד, יב פסוק ט. וש\"נ. (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 52 : בזהר ס\"פ ויקהל דרי\"ח ע\"א."],["6607","59","<b>ולא תתורו אחרי לבבכם</b>: שלח טו, לט."]]],[2001910577,"ואחרי עיניכם אשר אתם זונים אחריהם עינא וליבא תרין סרסורא דעבירה<sup data-n=\"6608\">60</sup>, והעיקר העינים<sup data-n=\"6609\">61</sup> דעיקר החמדה במה שהלב רואה, וכמו\"כ כל העדה נמשכים אחרי הסנהדרין מה שהם עושים, ועוד י\"ל שלכן נק' עינים מפני שעבודתם לאסתכלא ביקרא דמלכא<sup data-n=\"6610\">62</sup>, וכמ\"ש העיני אדם לא תשבענה<sup data-n=\"6611\">63</sup>, וכתי' עיניך יונים<sup data-n=\"6612\">64</sup> שהעיקרם האסתכלות<sup data-n=\"6613\">65</sup> כמו\"כ הסנהדרין עבודתם לאסתכלא כו', וזהו לבבתיני אחותי כלה<sup data-n=\"6614\">66</sup> לבבתיני באחד מעיניך באחד כתי' באחת קרי, באחד בחי' יחו\"ע<sup data-n=\"6615\">67</sup> דכולי' קמי' כל\"ח<sup data-n=\"6617\">69</sup> ביטל מבמציאות<sup data-n=\"6618\">*70</sup> ביטל דמשה ואנחנו מ\"ה<sup data-n=\"6619\">70</sup>, באחת הוא השגחה<sup data-n=\"6620\">71</sup> דיחו\"ת<sup data-n=\"6616\">68</sup> ביטל היש לאין, בשדה אשר יקצרון הוא התשלום שכר כמו זרעו לכם צדקה וקצרו לפי חסד<sup data-n=\"6621\">72</sup> דקצרו כו' הוא תשלום שכר, כמו\"כ כאן מ\"ש בשדה אשר יקצרון הוא תשלום שכר, והוא בחי' ציון וכמארז\"ל ע\"פ כריח השדה<sup data-n=\"6622\">73</sup> זה ציון<sup data-n=\"6623\">74</sup>, וירא והנה באר בשדה<sup data-n=\"6624\">75</sup> זה ציון<sup data-n=\"6625\">76</sup>, ציון שדה תחרש<sup data-n=\"6626\">77</sup>, וכתי' ישלח עזרך מקדש ומציון יסעדך<sup data-n=\"6627\">78</sup> ואמרז\"ל כל הברכות והישועות<sup data-n=\"6628\">79</sup> והנחמות הם מציון כי שם צוה את הברכה<sup data-n=\"6629\">80</sup>, מי יתן מציון ישועות ישראל<sup data-n=\"6630\">81</sup>, תורה ג\"כ מציון כמ\"ש כי מציון תצא תורה<sup data-n=\"6631\">82</sup>, והתשלום שכר הוא לפ\"ע הזריעה, וכמו שלש פעמים בשנה יראה כל זכורך וארז\"ל כשם שבא לראות<sup data-n=\"6632\">83</sup> כך בא לראות, ולראות בשתי עיניו של מקום דכתי'",[["6608","60","<b>עינא וליבא תרין סרסורא דעבירה</b>: לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 70 בשם הזהר. ראה במד\"ר פ\"י, ב. ירושלמי ברכות פ\"א, ה\"ה. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370243\" data-slug=\"torah-or\" data-id=\"3901370243\">תו\"א שמות נד, סע\"ג</a> ואילך. מאמרי אדה\"א שמות ח\"א ע' כ."],["6609","61","<b>והעיקר העינים</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 55."],["6610","62","<b>לאסתכלא ביקרא דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."],["6611","63","<b>העיני אדם לא תשבענה</b>: משלי כז, כ [ושם: ועיני האדם]. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381267\" data-slug=\"likkutei-torah\" data-id=\"4001381267\">לקו\"ת שה\"ש לד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381272\" data-slug=\"likkutei-torah\" data-id=\"4001381272\">לה, ד</a>. סהמ\"צ להצ\"צ ע' קפח. פלח הרמון שה\"ש ע' 124 ואילך."],["6612","64","<b>עיניך יונים</b>: שה\"ש א, טו. ד, א."],["6613","65","<b>יונים שהעיקרם האסתכלות</b>: ראה מאמרי אדה\"ז תקס\"ד ע' קלז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381186\" data-slug=\"likkutei-torah\" data-id=\"4001381186\">לקו\"ת שה\"ש יד, ב</a>. תו\"ח ח\"ש קלב, סע\"א ואילך ובהנסמן לשם. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תקפז."],["6614","66","<b>לבבתיני אחותי כלה</b>: שה\"ש ד, ט."],["6615","67","<b>באחד בחי' יחו\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381247\" data-slug=\"likkutei-torah\" data-id=\"4001381247\">לקו\"ת שה\"ש כט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381255\" data-slug=\"likkutei-torah\" data-id=\"4001381255\">לא, ג</a>."],["6617","69","<b>דכולי' קמי' כל\"ח</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["6618","*70","<b>ביטל מבמציאות</b>: כ\"ה בגוכתי\"ק."],["6619","70","<b>ביטל דמשה ואנחנו מ\"ה</b>: ראה גם לעיל הנחה ד\"ה הוא אהרן ומשה ובהערה 98."],["6620","71","<b>באחת הוא השגחה דיחו\"ת</b>: ראה לעיל הערה 67."],["6616","68","<b>יחו\"ע . . דיחו\"ת</b>: זהר בהקדמה יב, א."],["6621","72","<b>זרעו . . וקצרו לפי חסד</b>: הושע י, יב [ושם: קצרו — ראה (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 71]."],["6622","73","<b>כריח השדה</b>: תולדות כז, כז [ושם: שדה]."],["6623","74","<b>השדה זה ציון</b>: ראה תנחומא — באבער — תולדות י. ב\"ר פס\"ה, כג."],["6624","75","<b>וירא והנה באר בשדה</b>: ויצא כט, ב."],["6625","76","<b>באר . . זה ציון</b>: ראה ב\"ר פ\"ע, ח."],["6626","77","<b>ציון שדה תחרש</b>: ירמי' כו, יח."],["6627","78","<b>ישלח עזרך מקדש ומציון יסעדך</b>: תהלים כ, ג."],["6628","79","<b>כל הברכות והישועות</b>: ראה ויק\"ר פכ\"ד, ד."],["6629","80","<b>כי שם צוה את הברכה</b>: תהלים קלג, ג [בדילוג השם]."],["6630","81","<b>מי יתן מציון ישועות ישראל</b>: תהלים נג, ז. במדרש: ישועת — שם יד, ז."],["6631","82","<b>כי מציון תצא תורה</b>: ישעי' ב, ג. מיכה ד, ב."],["6632","83","<b>שלש פעמים . . כשם שבא לראות</b>: ראה לעיל הנחה ד\"ה ראה קראתי בשם ובהערות 60-61."]]],[2001910578,"עיני ה' אל צדיקים<sup data-n=\"6634\">85</sup> וכתי' עין<sup data-n=\"6635\">86</sup> ה' אל יראיו כאן בזמן שישראל<sup data-n=\"6633\">84</sup> עושין רש\"מ וכאן בזמן שאין ישראל ערש\"מ, דבזמן שישראל ערש\"מ אז עיני ה' הוא חבור יחו\"ע ולזה מבחי'<sup data-n=\"6636\">87</sup> שלמעלה גם מיחו\"ע, והו\"ע יחוד הוי' ואלקים יחוד סובב וממלא<sup data-n=\"6637\">88</sup>, אך בזמן שאין ערש\"מ אז בעין אחת בהשגחה דשם אלקים לבד, והתשלום שכר הוא תורה שהיא מציון כי מציון תצא תורה, וזהו קציר חטים דחטה הוא ך\"ב אתוון דאורייתא<sup data-n=\"6638\">89</sup>, דאף דשעורה הם ג\"כ אותיו' שיעור ה' ה\"ה ה' זעירא<sup data-n=\"6639\">90</sup> והם אותיו' שנבראו לצרף בהם שמים וארץ, אבל תורה רובה באתוון בינונים ויש אתוון רברבין והם אתוון אוחרנין<sup data-n=\"6640\">*91</sup>, ומ\"מ יש מעלה בשעורה שתחילת העבודה צ\"ל בזה זה השער לה' כו'.\n<b>ושרש</b> ההפרש בין התשלום שכר דפסח ושבועות הוא, דבפסח השגת הנפש בממכ\"ע ושבועות השגת הנפש בסוכ\"ע דתורה הוא סוכ\"ע, בכורי מעשיך אשר תזרע בשדה דזמן הבאת בכורים בשבועות<sup data-n=\"6641\">91</sup> והוא משדה אילן, דיש שדה לבן ושדה אילן<sup data-n=\"6642\">92</sup>, שדה לבן הוא שיעור ה' ויש בזה מעלה כנ\"ל, ושדה אילן הוא בחי' כי אדם עץ השדה אדם אדמה לעליון<sup data-n=\"6643\">93</sup>, אשר תזרע בשדה שהוא ג\"כ לפ\"ע הזריעה, דמצות נק' ג\"כ זריעה<sup data-n=\"6644\">94</sup> וכמ\"ש זרעו לכם צדקה, וצדקה כולל כללות כל המצות<sup data-n=\"6645\">95</sup>, וזריעה צריך מים וז\"ש אשריכם זרעי<sup data-n=\"6646\">96</sup> על כל מים והוא תורה<sup data-n=\"6647\">97</sup> וכמ\"ש הוי כל צמא לכו למים<sup data-n=\"6648\">98</sup>, וזשארז\"ל כל העוסק בתורה וגמ\"ח<sup data-n=\"6649\">99</sup> זוכה לנחלת שני שבטים דכתי' אשריכם זורעי על כל מים<sup data-n=\"6650\">100</sup> משלחי הרגל שור וחמור<sup data-n=\"6651\">101</sup> שור יוסף וחמור ישכר<sup data-n=\"6652\">102</sup>, דמים הוא תורה, והזריעה היא בארץ העליונה והצמיחה בעדן עין לא ראתה<sup data-n=\"6653\">103</sup>,",[["6634","85","<b>עיני ה' אל צדיקים</b>: תהלים לד, יז."],["6635","86","<b>עין ה' אל יריאיו</b>: תהלים לג, יח."],["6633","84","<b>עיני . . עין . . בזמן שישראל</b>: שהש\"ר פ\"ח, יב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380811\" data-slug=\"likkutei-torah\" data-id=\"4001380811\">לקו\"ת פ' ראה כג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380812\" data-slug=\"likkutei-torah\" data-id=\"4001380812\">כד, א</a>. ג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010120\" data-slug=\"or-hatorah-hb\" data-id=\"8159010120\">אוה\"ת</a> (יהל אור) תהלים ע' קכב. סה\"מ תר\"ל ע' קלה ואילך. ע' רי ואילך [אוה\"ת פינחס ע' א'ריז ואילך]."],["6636","87","<b>ולזה מבחי'</b>: אוצ\"ל: ולזה מאיר מבחי'."],["6637","88","<b>הוי' ואלקים . . סובב וממלא</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ועבדתם את ה\"א פ\"ב. וש\"נ."],["6638","89","<b>דחטה הוא ך\"ב אתוון דאורייתא</b>: ראה זהר בלק קפח, ב. ת\"ז תס\"ט (קיד, א. ב)."],["6639","90","<b>ה' זעירא</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 78."],["6640","*91","<b>אתוון אוחרנין</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה *78 ואילך. (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 101."],["6641","91","<b>דזמן הבאת בכורים בשבועות</b>: ראה בכורים פ\"א, מ\"ג. סה\"מ מלוקט ה' ע' קסט הערה 10."],["6642","92","<b>שדה לבן ושדה אילן</b>: שביעית פ\"ב, מ\"א. מוע\"ק פ\"א, מ\"ד."],["6643","93","<b>אדם אדמה לעליון</b>: ישעי' יד, יד. ראה עבוה\"ק ח\"א חלק היחוד פי\"ז. של\"ה תולדות אדם ג, א. מאמרי אדה\"א דברים ח\"א ע' קכב. וש\"נ. בראשית ע' קסב. וש\"נ."],["6644","94","<b>דמצות נק' ג\"כ זריעה</b>: ראה גם תו\"א שמות נג, ג. סה\"מ תרל\"ח ע' תי ואילך. תר\"ם ח\"א ע' רסב. וש\"נ."],["6645","95","<b>וצדקה כולל כללות כל המצות</b>: ראה גם לעיל הנחה ד\"ה ועבדתם את ה' אלקיכם ובהערה 34."],["6646","96","<b>אשריכם זרעי</b>: נסמן לקמן הערה 100."],["6647","97","<b>מים והוא תורה</b>: נסמן בסמוך הערה 99."],["6648","98","<b>הוי כל צמא לכו למים</b>: ישעי' נה, א."],["6649","99","<b>כל העוסק בתורה וגמ\"ח</b>: ראה ב\"ק יז, א."],["6650","100","<b>אשריכם זורעי על כל מים</b>: ישעי' לב, כ."],["6651","101","<b>הרגל שור וחמור</b>: בישעי' שם: רגל השור והחמור."],["6652","102","<b>ישכר</b>: ראה גם סה\"מ תרל\"ח ע' תמ. וש\"נ. תר\"ם ח\"א ע' כט."],["6653","103","<b>בעדן עין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."]]],[2001910579,"והארה מבחי' זו מאיר בגעה\"ע ואפי' בגה\"ת ג\"כ שהוא בתחילת עשי' ובעצם הוא ביצי'<sup data-n=\"6654\">104</sup>, והיינו הארות אצי' שלמעלה מבריאה שבבריאה<sup data-n=\"6655\">105</sup>, וזהו\"ע זיו תורתן ועבודתן שכ' בסש\"ב<sup data-n=\"6656\">106</sup>, ועיקר הגילוי יהי' לע\"ל ועכשיו מאיר הארה מבחי' זו, דמצות הם הזריעה וכמארז\"ל זרע הקב\"ה התומ\"צ<sup data-n=\"6657\">107</sup> כו', ובכ\"י מאיר ג\"כ מבחי' זו דכ\"י מברכים נותן התורה<sup data-n=\"6658\">108</sup>, דבכ\"י נמשך גילוי עליון יותר.\n<b>וחג</b> האסיף בצאת השנה כו' זהו חג הסוכות דלמעלה מפסח ושבועות והוא מדרי' התשובה, דהנה כתי' כי אבי ואמי עזבוני והוי' יאספני<sup data-n=\"6659\">109</sup>, או\"א הם תושב\"כ ותושבע\"פ וכמ\"ש שמע בני מוסר אביך<sup data-n=\"6660\">110</sup> הוא תושב\"כ ואל תטוש תורת אמך תושבע\"פ, ואף אם פגם בתורה מ\"מ הוי' יאספני דארז\"ל שאלו לחכמ'<sup data-n=\"6661\">111</sup> נפש החוטאת מה עונשה א' חטאים תרדוף רעה<sup data-n=\"6662\">112</sup> שאל<sup data-n=\"6663\">113</sup> לתורה א' יביא קרבן<sup data-n=\"6664\">114</sup> ויתכפר, אך הקרבן מכפר רק על שוגג<sup data-n=\"6665\">115</sup> ולא על מזיד<sup data-n=\"6666\">116</sup>, שאלו להקב\"ה א' יעשה תשובה ויתכפר לו זש\"ה טוב וישר ה' על כן יורה חטאים בדרך<sup data-n=\"6667\">117</sup>, וזהו וה' יאספני, וזהו\"ע וחג האסיף בצאת השנה דתחלה צ\"ל ר\"ה ויוהכ\"פ דכתי' בהתאסף ראשי עם<sup data-n=\"6668\">118</sup> יחד שבטי ישראל שאז מתאספי' כל הניצוצות ולכן נק' סוכות חג האסיף, וכמ\"ש ואספת דגנך ותרושך ויצהרך, והו\"ע כהנים לוים וישראלים<sup data-n=\"6669\">119</sup>, דגנך אלו ישראלים כמ\"ש מה טובו ומה יפיו דגן בחורים<sup data-n=\"6670\">120</sup>, וארז\"ל ע\"פ ורוב דגן<sup data-n=\"6671\">121</sup> אלו בחורי ישראל, ותרשך הם לוים שאומרים שירה על היין<sup data-n=\"6672\">122</sup>, ויצהרך אלו כהנים שהם משוחים בשמן<sup data-n=\"6673\">123</sup>, וג' אלו ממשיכי' מבחי' עליונה יותר וכמו בג' אומר נברך<sup data-n=\"6674\">124</sup> דיחיד",[["6654","104","<b>בגה\"ת . . בתחילת עשי' . . ביצי'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370152\" data-slug=\"torah-or\" data-id=\"3901370152\">תו\"א מקץ לב, ד</a>. סה\"מ תר\"ם ח\"א ע' טז. וש\"נ."],["6655","105","<b>הארות אצי' . . שבבריאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380317\" data-slug=\"likkutei-torah\" data-id=\"4001380317\">לקו\"ת במדבר ב, ב</a>."],["6656","106","<b>זיו תורתן . . בסש\"ב</b>: פל\"ט."],["6657","107","<b>זרע הקב\"ה התומ\"צ</b>: ראה במדב\"ר פי\"ז, ה. סה\"מ תר\"ם ח\"א ע' רסב. וש\"נ."],["6658","108","<b>דכ\"י מברכים נותן התורה</b>: בברכת התורה. ראה גם סה\"מ תר\"ל כאן ע' קלו. מאמרי אדה\"א דברים ח\"ג ס\"ע תתכא ואילך."],["6659","109","<b>כי אבי ואמי . . יאספני</b>: תהלים כז, י."],["6660","110","<b>שמע בני מוסר אביך</b>: משלי א, ח. ראה גם אגה\"ק סכ\"ט (קנא, א). מאמרי אדה\"ז תקע\"א ע' פא. מאמרי אדה\"א דברים ח\"ד ע' א'תנ. וש\"נ."],["6661","111","<b>שאלו לחכמ'</b>: ראה ירושלמי מכות פ\"ב, ה\"ו. ילקוט שמעוני יחזקאל יח, ד (רמז שנח). תהלים כה, ח (רמז תשב). (לעיל בחלק המאמרים) מאמר ד\"ה וברך את לחמך ובהערה 47."],["6662","112","<b>חטאים תרדוף רעה</b>: משלי יג, כא.\nולהעיר ש (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 124 מובא שכ\"ק אדמו\"ר מהר\"ש אמר שמענת החכמה היתה: ”תמות\"."],["6663","113","<b>שאל</b>: אוצ\"ל: שאלו."],["6664","114","<b>קרבן</b>: כ\"ה בירושלמי שם. אבל בילקוט שם: אשם. ובזית רענן לילקוט תהלים שם: דרוב אשמות בא על מזיד — ראה בסמוך הערה 116."],["6665","115","<b>הקרבן . . על שוגג</b>: ראה רמב\"ם הל' שגגות רפ\"א ואילך. אגה\"ק סוסכ\"ח."],["6666","116","<b>הקרבן . . ולא על מזיד</b>: ראה סה\"מ תרל\"ג ח\"א כאן ע' קמט בשולי היריעה. תר\"ם ח\"ב ע' תר. וש\"נ."],["6667","117","<b>טוב וישר ה' . . בדרך</b>: תהלים כה, ח."],["6668","118","<b>בהתאסף ראשי עם</b>: ברכה לג, ה."],["6669","119","<b>ואספת דגנך . . וישראלים</b>: עקב יא, יד. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 108."],["6670","120","<b>מה טובו . . דגן בחורים</b>: זכרי' ט, יז."],["6671","121","<b>ורוב דגן</b>: תולדות כז, כח. ב\"ר פס\"ו, ג."],["6672","122","<b>שאומרים שירה על היין</b>: ברכות לה, א."],["6673","123","<b>כהנים שהם משוחים בשמן</b>: ראה תשא ל, ל. פקודי מ, יג. טו. רמב\"ן צו ח, יא. רמב\"ם הל' כלי המקדש פ\"א ה\"ז."],["6674","124","<b>בג' אומר נברך</b>: ברכות פ\"ז, מ\"ג (מט, ב). ראה סידור שער בהמ\"ז קב, א ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450538\" data-slug=\"or-hatorah-hb\" data-id=\"8316450538\">אוה\"ת עקב ע' תקלח</a> ואילך. סה\"מ תרכ\"ו ריש ע' ריט. לקמן הנחה ד\"ה והי' אמונת עתך על יד הערה 38."]]],[2001910580,"א\"י לומר נברך, וז\"ש ואגודתו על ארץ יסדה<sup data-n=\"6675\">125</sup> עי\"ז בונה בשמים מעליותיו<sup data-n=\"6676\">126</sup> מעל לרקיע, וכמו\"כ יובן בסוכות שנק' חג האסיף, דד\"מ שבלולב<sup data-n=\"6677\">127</sup> ג' מינים אוגדים כאחת<sup data-n=\"6679\">129</sup> והאתרוג בשער<sup data-n=\"6681\">131</sup> צ\"ל מחובר<sup data-n=\"6680\">130</sup> עם הג' מינים, והם עצמן מורין על התכללות<sup data-n=\"6678\">128</sup> דלולב צ\"ל כפות כפת תמרים<sup data-n=\"6682\">132</sup> והדסים תלתא בחד קינא<sup data-n=\"6683\">133</sup> וערבה גדילים באחוה<sup data-n=\"6684\">134</sup>, ואתרוג גדל על כל מים<sup data-n=\"6685\">135</sup>, ואוגדים אותם כו' וזהו וחג האסיף וכמו וכבוד ה' יאספך<sup data-n=\"6686\">136</sup>, וכמו והיתה נפש אדוני צרורה<sup data-n=\"6687\">137</sup> בצרור החיים את ה' אלקיך ואין צרור פחות משלשה<sup data-n=\"6688\">138</sup>. ולפ\"ז יתורץ מ\"ש לעיל מה שייך הרגלים לתבואה, אך הם מורים על הגילוי, דבפסח אז זמן אשר שעורה אביב שיעור ה', ושבועות זמן קציר חטים מ\"ת<sup data-n=\"6689\">139</sup> והבאת בכורים משדה אילן, וסוכות חג האסיף כמו וכבוד ה' יאספך.\nשייך לענין בכורי מעשיך<sup data-n=\"6690\">140</sup>\nלחם מן השמים ולחם מן הארץ, לחם מן השמים<sup data-n=\"6691\">141</sup> הוא מצה<sup data-n=\"6693\">143</sup> ואח\"כ לחם מן השמים<sup data-n=\"6692\">142</sup> מן ממצה נעשה מצוה<sup data-n=\"6694\">144</sup>.",[["6675","125","<b>בג' . . ואגודתו על ארץ יסדה</b>: עמוס ט, ו. רש\"י שבת קט, ב ד\"ה ג' קלחים. וראה גם סוכה יג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380880\" data-slug=\"likkutei-torah\" data-id=\"4001380880\">לקו\"ת תצא מ, ד</a>."],["6676","126","<b>בונה בשמים מעליותיו</b>: ע\"פ התחלת הכתוב ואגודתו על ארץ. ראה גם לקמן (בחלק ההנחות) בהנחה כאן ובהערה 136."],["6677","127","<b>דד\"מ שבלולב</b>: סוכה לא, א. מנחות כז, א."],["6679","129","<b>ג' מינים אוגדים כאחת</b>: ראה שו\"ע אדה\"ז הל' לולב סתרנ\"א, ס\"א. ס\"ב. וש\"נ."],["6681","131","<b>בשער</b>: לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 140: בשעת הברכה."],["6680","130","<b>והאתרוג . . מחובר</b>: ראה סידור אדה\"ז דיני הלולב (קודם הלל). ראה גם סה\"מ תרל\"ח ע' קלד."],["6678","128","<b>דד\"מ שבלולב . . התכללות</b>: ראה סידור שער הלולב רסא, ג — רסב, ג. רסד, ד — רסה, א. (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 117."],["6682","132","<b>דלולב צ\"ל כפות כפת תמרים</b>: אמור כג, מ. ראה סוכה לב, א. סה\"מ מלוקט א' ע' רנג."],["6683","133","<b>והדסים תלתא בחד קינא</b>: ראה סוכה לב, ב."],["6684","134","<b>וערבה גדילים באחוה</b>: ראה שבת כ, א וברש\"י שם. מאמרי אדה\"א דברים ח\"ד ע' א'שיב בהערה."],["6685","135","<b>ואתרוג גדל על כל מים</b>: סוכה לה, א."],["6686","136","<b>וכבוד ה' יאספך</b>: וכ\"ה בסמוך. ישעי' נח, ח [ושם: כבוד — ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 123. סה\"מ תר\"ם ח\"א ע' קמט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550611\" data-slug=\"torat-chaim\" data-id=\"2300550611\">תו\"ח משפטים ח\"ב שב, ב</a>. וש\"נ]."],["6687","137","<b>והיתה נפש אדוני צרורה</b>: שמו\"א כה, כט."],["6688","138","<b>ואין צרור פחות משלשה</b>: ראה פרדס שעה\"כ פי\"ח, מערכת צרור החיים. מגיד משרים תצא (סדר סעודת שבת קלה, א)."],["6689","139","<b>ושבועות זמן . . מ\"ת</b>: ראה נוסח התפלה וקידוש לשבועות. שו\"ע אדה\"ז חאו\"ח סתצ\"ד, ס\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081021\" data-slug=\"likkutei-sichot\" data-id=\"1300081021\">לקו\"ש שבועות כרך ח ע' 21</a>."],["6690","140","<b>שייך . . מעשיך</b>: נרשם בצד הימיני של הגליון באותיות קטנות."],["6691","141","<b>לחם מן . . מן השמים</b>: ראה זהר ויצא קנז, סע\"א."],["6693","143","<b>מצה</b>: ראה אור החמה לזהר שם."],["6692","142","<b>השמים</b>: אוצ\"ל: הארץ."],["6694","144","<b>ממצה נעשה מצוה</b>: זהר ויצא שם לפנ\"ז. הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380102\" data-slug=\"likkutei-torah\" data-id=\"4001380102\">לקו\"ת ויקרא ז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380132\" data-slug=\"likkutei-torah\" data-id=\"4001380132\">צו יד, א</a>. סה\"מ תרכ\"ט ס\"ע קמ. תרל\"ב ח\"א ע' כג. ס\"ע ל."]]],[2001910581,"<h3>והמים להם חומה</h3>\n<b>ליל אחש\"פ</b>\n<b>והמים</b> להם חומה<sup data-n=\"6695\">1</sup> מימינם ומשמאלם<sup data-n=\"6696\">2</sup>, ואי' במדרש מימינם זה ק\"ש ומשמאלם זה תפלה<sup data-n=\"6697\">3</sup>, והקשו המפרשים למה נק' תפלה שמאל, ופי' המת\"כ<sup data-n=\"6698\">4</sup> דתורה הוא חיי עולם ותפלה חיי שעה<sup data-n=\"6699\">5</sup> ועוה\"ז ועוה\"ב, עוה\"ב ימין ועוה\"ז שמאל<sup data-n=\"6700\">6</sup> ובתפלה יש י\"ב ברכות האמצעיות שאדם שואל צרכיו בהם<sup data-n=\"6701\">7</sup> לכן נק' התפלה שמאל, והוא תירוץ. אך י\"ל תירוץ מרוחב יותר. והענין דהנה גבי קרי\"ס כתי' וירא ישראל<sup data-n=\"6702\">8</sup> את היד הגדולה אשר עשה ה' במצרים ויראו<sup data-n=\"6703\">9</sup> העם את ה', ואי' במדרש<sup data-n=\"6704\">10</sup> דפרעה חטא במה שהתגאה ואמר מי הוי' אשר אשמע בקולו<sup data-n=\"6705\">11</sup> ופגם במי לכן ילקה בי\"ם אותיות מי<sup data-n=\"6706\">12</sup>, וכמה לקה נו\"ן מכות דכתי' את היד הגדולה דבמצרים לקו באצבע<sup data-n=\"6707\">13</sup> לכן לקו עשר מכות ועל הים בחמשה אצבעות בכל אצבע י' מכות ולקו חמשים מכות אמור מעתה במצרים לקו עשר מכות ועל הים לקו חמישים מכות<sup data-n=\"6708\">14</sup>, ולכאורה צ\"ל והלא יד הגדולה הוא חסד<sup data-n=\"6709\">15</sup> ואיך נמשך מזה דין לפרעה<sup data-n=\"6710\">16</sup>, אך מ\"מ כ\"ה דכתי' לך הגדולה<sup data-n=\"6711\">17</sup> ואמרז\"ל זה קרי\"ס<sup data-n=\"6712\">18</sup>. ולהבין זה צלה\"ק מ\"ש ויאמינו בה'<sup data-n=\"6713\">19</sup> ולכאורה אחר דכתי' וירא ישראל מה שייך אמונה אח\"כ דאמונה שייך בדבר שאינו רואה, וקושיא זו אי' במדרש<sup data-n=\"6714\">20</sup> אית מאן דחמי ומהימן בתמי'.\n<b>והענין</b> דהנה מ\"ש ויראו העם את ה' הוא כמ\"ש יראו את הוי' קדושיו<sup data-n=\"6715\">21</sup> כי אין מחסור ליראיו, וג\"ז צ\"ל דבמזמור שלפני זה כתי' יראו מה' כל הארץ<sup data-n=\"6716\">22</sup>",[["6695","1","<b>והמים להם חומה</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה וירא ישראל את היד הגדולה שנדפס לעיל בחלק המאמרים. וש\"נ. ולהעיר שהכותרת שם היא: ”שש\"פ מ\"א\"\nהנחה זו כנראה נרשמה כשהי' כבר לפניו המאמר — ראה לקמן על יד הערה 116 שמציין להמאמר ”ע' בכתב\" ."],["6696","2","<b>והמים להם חומה מימינם ומשמאלם</b>: בשלח יד, כב. כט."],["6697","3","<b>מימינם זה ק\"ש . . תפלה</b>: שהש\"ר פ\"א, ט (ד)."],["6698","4","<b>ופי' המת\"כ</b>: ראה שם ד\"ה תפלה. וראה גם פי' זה ינחמינו על המכילתא בשלח יד, כח [אלא ששם הגירסא תורה ולא ק\"ש]."],["6699","5","<b>דתורה הוא חיי עולם . . חיי שעה</b>: שבת י, א."],["6700","6","<b>עוה\"ב ימין ועוה\"ז שמאל</b>: ראה ב\"ר פנ\"ט, ב. ערכי הכנויים לבעל סדה\"ד מערכת ימין עה\"ב. אוה\"ת חנוכה ע' שלז ואילך."],["6701","7","<b>י\"ב ברכות האמצעיות . . בהם</b>: ראה ברכות לד, א. שו\"ע אדה\"ז הל' תפלה סקי\"ב."],["6702","8","<b>וירא ישראל . . את ה'</b>: בשלח יד, לא."],["6703","9","<b>ויראו</b>: אוצ\"ל: וייראו."],["6704","10","<b>ואי' במדרש</b>: ראה שמו\"ר פ\"ה, יד. הועתק לשונו באוה\"ת בשלח ע' תכח."],["6705","11","<b>מי הוי' אשר אשמע בקולו</b>: שמות ה, ב."],["6706","12","<b>בי\"ם אותיות מי</b>: זהו פי' אחר במדרש שם."],["6707","13","<b>דבמצרים לקו באצבע</b>: וארא ח, טו."],["6708","14","<b>אמור מעתה . . חמישים מכות</b>: הלשון ע\"פ מכילתא בשלח יד, ל."],["6709","15","<b>יד הגדולה הוא חסד</b>: ראה מאו\"א מערכת יד אות ה."],["6710","16","<b>ואיך נמשך מזה דין לפרעה</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 9."],["6711","17","<b>לך הגדולה</b>: דבהי\"א כט, יא [בדילוג השם]."],["6712","18","<b>הגדולה . . זה קרי\"ס</b>: ראה ברכות נח, סע\"א."],["6713","19","<b>ויאמינו בה'</b>: המשך הכתוב וירא ישראל — בשלח יד, לא."],["6714","20","<b>אי' במדרש</b>: שהש\"ר פ\"ד, ח (ב). הועתק לשונו באוה\"ת בשלח ע' תל."],["6715","21","<b>יראו את הוי' קדושיו</b>: תהלים לד, י."],["6716","22","<b>יראו מה' כל הארץ</b>: שם לג, ח [ושם: ייראו]."]]],[2001910582,"ולמה א' כאן רק קדושיו, ועוד צ\"ל מהו הנתינת טעם כי אין מחסור ליראיו דלכאו' אין לו פי' כלל. והענין דאף שיש כמה פרטים ביראה, בד\"כ הם ב' מדרי' יר\"ת ויר\"ע<sup data-n=\"6717\">23</sup>, יר\"ת הוא היראה הבאה מההתבוננות דהתהוות העולמות, וכמ\"ש יראו מה'<sup data-n=\"6718\">24</sup> כל הארץ ממנו יגורו כל יושבי תבל כי הוא אמר ויהי<sup data-n=\"6719\">25</sup>, דכל העולמות נתהוו מאמירה א' וכמ\"ש במשנה בע\"מ ברא הקב\"ה את עולמו והלא במאמר אחד יכול להבראות<sup data-n=\"6720\">26</sup>, ובפתקא<sup data-n=\"6721\">27</sup> דב\"ש אומרים ברוך שאמ\"ר והי' העולם שנתהווה מאמירה<sup data-n=\"6722\">28</sup>, וכתי' אלה תולדות השמים בהבראם<sup data-n=\"6723\">29</sup> בה' בראם<sup data-n=\"6724\">30</sup> בה' נברא העוה\"ז, ואין הכוונה על עוה\"ז לבד כ\"א על כלליות עלדאת\"ג<sup data-n=\"6725\">31</sup>, ומה תופס מקום אות א' לגבי כללות עולם הדיבור ובפרט אות ה' דהוא אתא קלילא<sup data-n=\"6726\">32</sup> דלית בי' מששא<sup data-n=\"6727\">33</sup>, וכשיתבונן בזה תפול אימה ופחד על האדם, וזהו יראו מה' יראה מרחוק<sup data-n=\"6728\">34</sup> דאין הפי' מהוי' מעצם שם הוי' אלא מהארה דשם הוי' דמע\"ב<sup data-n=\"6729\">35</sup> כתי' ל\"ב פעמים שם אלקים<sup data-n=\"6730\">36</sup> ולא נזכר כלל שם הוי', דגבי שם הוי' כתי' יהללו שם הוי' כי הוא צוה ונבראו<sup data-n=\"6731\">37</sup> בדרך מאיליו וממילא, ולהיות כח הפועל בנפעל<sup data-n=\"6732\">38</sup> הוא ע\"י שם אלקים דוקא, אך מ\"מ הארה משם הוי' מאיר בשם אלקים וכמ\"ש כי הוא אמר ויהי צוה ויעמד<sup data-n=\"6733\">39</sup>, והוא כמ\"ש יהללו שם הוי' כי הוא צוה ונבראו ויעמידם<sup data-n=\"6734\">40</sup> כו', ועז\"נ יראו מה' כל הארץ שכל הברואים יכולים לבוא ליראה זו, ומ\"ש יראו את ה' קדושיו הוא בחי' יר\"ע<sup data-n=\"6735\">41</sup>, ולהגיע לבחי' זו דוקא קדושיו היינו המקיימים תומ\"צ שמברכים אשר קדשנו במצותיו<sup data-n=\"6736\">42</sup>, ועי\"ז יבא לבחי' יראה עילאה יראת הרוממות שאוא\"ס הוא קדוש ומובדל ומרומם, וצ\"ל למה",[["6717","23","<b>ב' מדרי' יר\"ת ויר\"ע</b>: ראה הנסמן באוה\"ת שבהערה הבאה."],["6718","24","<b>יר\"ת . . יראו מהוי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380361\" data-slug=\"likkutei-torah\" data-id=\"4001380361\">לקו\"ת במדבר יג, ב</a>. ד\"ח שער התפלה נב, א ואילך. אוה\"ת בשלח כאן ע' תלב. ע' תס ואילך. לעיל מאמר ד\"ה ועבדתם את ה\"א פ\"ג."],["6719","25","<b>כי הוא אמר ויהי</b>: תהלים לג, ט."],["6720","26","<b>בע\"מ ברא . . להבראות</b>: אבות רפ\"ה. ראה לעיל הנחה ד\"ה הקבצו ושמעו הערה 29."],["6721","27","<b>ובפתקא</b>: אוצ\"ל: ובפסקא."],["6722","28","<b>ברוך שאמ\"ר . . מאמירה</b>: נוסח ברכת ברוך שאמר. ראה גם שע\"ת עג, א ובהערה 26. לקו\"ת ואתחנן ב, א."],["6723","29","<b>אלה תולדות השמים בהבראם</b>: בראשית ב, ד [בדילוג]."],["6724","30","<b>בהבראם בה' בראם</b>: ראה מנחות כט, ב. ב\"ר פי\"ב, ב. פרש\"י עה\"פ."],["6725","31","<b>בה\"א נברא העוה\"ז . . עלדאת\"ג</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370210\" data-slug=\"torah-or\" data-id=\"3901370210\">תו\"א ויחי מו, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380043\" data-slug=\"likkutei-torah\" data-id=\"4001380043\">לקו\"ת בשלח א, ב</a>."],["6726","32","<b>ה' דהוא אתא קלילא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381022\" data-slug=\"likkutei-torah\" data-id=\"4001381022\">לקו\"ת האזינו עד, ד</a>: והה' הוא אתא קלילא דלית בי' מששא כמבואר באקדמות. תו\"ח ח\"ש קכא, ג ובהערה 48."],["6727","33","<b>מששא</b>: תיבה זו אינה ברורה כ\"כ."],["6728","34","<b>יראה מרחוק</b>: ראה גם בענין יראה (לעיל בחלק המאמרים) מאמר ד\"ה הים ראה וינוס על יד הערה 75."],["6729","35","<b>דמע\"ב</b>: אוצ\"ל: דבמע\"ב."],["6730","36","<b>דבמע\"ב כתי' ל\"ב פעמים שם אלקים</b>: נמנו בפרטיות בתקז\"ח קיב, ג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכה. וש\"נ. שעה\"י קלב, א ובהערה 3."],["6731","37","<b>יהללו . . צוה ונבראו</b>: תהלים קמח, ה [בדילוג]. ראה גם לקמן הנחה ד\"ה וידבר כו' קדושים תהיו ובהערה 29. (לעיל בחלק המאמרים) מאמר ד\"ה ועבדתם את ה\"א ובהערה 79."],["6732","38","<b>כח הפועל בנפעל</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a>: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת) סוף ש\"ג."],["6733","39","<b>כי הוא אמר . . ויעמוד</b>: תהלים לג, ט [בדילוג]. ראה גם לקמן הנחה ד\"ה וידבר כו' קדושים תהיו על יד הערה 30."],["6734","40","<b>ויעמידם</b>: תהלים קמח, ו."],["6735","41","<b>יראו את ה' . . יר\"ע</b>: ראה לעיל הערה 24."],["6736","42","<b>שמברכים אשר קדשנו במצותיו</b>: נוסח ברכת המצות."]]],[2001910583,"ע\"י מצות דוקא יבא ליר\"ע. והענין דהנה במצוה יש ב' פי' א' ל' ציווי כמו צו אל בנ\"י<sup data-n=\"6738\">44</sup>, ב' ל' צוותא<sup data-n=\"6737\">43</sup> וחיבור כמארז\"ל ע\"פ כי זה כל האדם<sup data-n=\"6739\">45</sup> כל העולם לא נברא אלא לצוות לזה<sup data-n=\"6740\">46</sup> פי' להתחבר לזה.\n<b>ולהבין</b> זה הנה אמרז\"ל ע\"פ ויהי ביום השישי<sup data-n=\"6741\">47</sup> ה' יתירה תנאי התנה הקב\"ה<sup data-n=\"6742\">48</sup> במע\"ב אם יקיימו ישראל את תורתי מוטב וא\"ל אחזור<sup data-n=\"6743\">49</sup> את העולם לתהו, וכן מ\"ש וישב הים לפנות בקר לאיתנו<sup data-n=\"6744\">50</sup> אמרז\"ל לתנאו<sup data-n=\"6745\">51</sup> דקי\"ס הי' הכנה למ\"ת<sup data-n=\"6746\">52</sup>, ולכאו' צ\"ל מה שייך תורה לעולם והרי תורה ניתנה לך\"ו דור<sup data-n=\"6747\">53</sup>. והענין דהנה אי' בזהר ובמדרש<sup data-n=\"6749\">55</sup> עשרה עשרה הכף<sup data-n=\"6750\">56</sup> בשקל<sup data-n=\"6751\">57</sup> עה\"ד מכוון כנגד ע\"מ<sup data-n=\"6748\">54</sup>, דיבור אנכי נגד מאמר יהי אור<sup data-n=\"6752\">58</sup> כו' דאם לא בריתי יומם ולילה חקת שמים וארץ לא שמתי<sup data-n=\"6753\">59</sup>, וכתיב אנכי עשיתי ארץ<sup data-n=\"6754\">60</sup> ואדם עלי' בראת\"י בגימ' תרי\"ג<sup data-n=\"6755\">61</sup> דעיקר המכוון הוא בשביל תומ\"צ. וביאור הענין דאף שאמרז\"ל בע\"מ נברא העולם<sup data-n=\"6756\">62</sup>, ואמרז\"ל בעשרה דברים ברא הקב\"ה<sup data-n=\"6757\">63</sup> את עולמו בחכ' ובתבונה ובדעת ובכח ובגערה כו' דכתי' ה' בחכ' יסד ארץ כונן שמים בתבונה<sup data-n=\"6758\">64</sup> בדעתו תהומות נבקעו<sup data-n=\"6759\">65</sup> כו' אך מ\"מ הרי כתי' רבות עשית אתה ה' נפלאותיך ומחשבותיך אלינו אין ערוך אליך<sup data-n=\"6760\">66</sup>, פי' נפלאותיך כמ\"ש בס\"י בל\"ב נתיבות<sup data-n=\"6761\">67</sup> פליאות חכ' חקק י\"ה הוי' צבאות וברא את עולמו,",[["6738","44","<b>צו אל בנ\"י</b>: ראה גם לעיל הנחה ד\"ה אז ישיר משה ובהערה 39."],["6737","43","<b>במצוה . . ל' צוותא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380272\" data-slug=\"likkutei-torah\" data-id=\"4001380272\">לקו\"ת בחוקותי מה, ג</a>. סה\"מ תרל\"ח ע' קכב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071030\" data-slug=\"likkutei-sichot\" data-id=\"1300071030\">לקו\"ש צו כרך ז ע' 30</a> ואילך."],["6739","45","<b>כי זה כל האדם</b>: קהלת יב, יג."],["6740","46","<b>כל העולם . . לצוות לזה</b>: ראה ברכות ו, ב."],["6741","47","<b>ויהי ביום השישי</b>: לשון הכתוב בשלח טז, כב. ראה (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 45 שמביא הכתוב: ויהי ערב . . הששי: בראשית א, לא."],["6742","48","<b>תנאי התנה הקב\"ה</b>: כ\"ה בכ\"מ — ראה גם לעיל הנחה ד\"ה קדש ישראל לה' ובהערה 53."],["6743","49","<b>אחזור</b>: לעיל שם: אחזיר."],["6744","50","<b>וישב הים . . לאיתנו</b>: בשלח יד, כז."],["6745","51","<b>לתנאו</b>: ראה ב\"ר פ\"ה, ה. שמו\"ר פכ\"א, ו. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061097\" data-slug=\"likkutei-sichot\" data-id=\"1300061097\">לקו\"ש בשלח כרך ו' ע' 86</a> ואילך. וש\"נ."],["6746","52","<b>דקי\"ס הי' הכנה למ\"ת</b>: ראה שער האמונה לב, ב ובהערה 9. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540550\" data-slug=\"torat-chaim\" data-id=\"2300540550\">תו\"ח בשלח ח\"א קמח, ג</a>. וש\"נ."],["6747","53","<b>תורה ניתנה לך\"ו דור</b>: ראה פסחים קיח, א."],["6749","55","<b>ובמדרש</b>: ראה פסיקתא רבתי פיסקא עשה\"ד פכ\"א, יט-כ. מדרש לקח טוב ואתחנן ה, ו."],["6750","56","<b>עשרה עשרה הכף</b>: נשא ז, פו."],["6751","57","<b>בשקל</b>: אוצ\"ל: בשקל הקדש."],["6748","54","<b>אי' בזהר . . ע\"מ</b>: ראה זהר יתרו צג, ב. ויקרא יא, ב. לעיל הנחה ד\"ה קדש ישראל לה' הערה 52."],["6752","58","<b>דיבור אנכי . . יהי אור</b>: יתרו כ, ב. בראשית א, ג. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 54. שע\"ת יב, ג הערה 42. סה\"מ תר\"ם ח\"א ע' קצ."],["6753","59","<b>דאם לא בריתי . . שמתי</b>: ירמי' לג, כה."],["6754","60","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב. ראה גם זהר תולדות קלד, ב. ויגש רה, ב."],["6755","61","<b>בראת\"י בגימ' תרי\"ג</b>: ראה רמ\"ז לזהר ויגש שם (קז, ב בדפי הספר). לעיל הנחה ד\"ה קדש ישראל לה' ובהערה 173."],["6756","62","<b>בע\"מ נברא העולם</b>: אבות רפ\"ה."],["6757","63","<b>בעשרה דברים ברא הקב\"ה</b>: ראה חגיגה יב, א. לעיל הנחה ד\"ה זכור את יום השבת ובהערה 49."],["6758","64","<b>ה' בחכ' . . בתבונה</b>: משלי ג, יט."],["6759","65","<b>בדעתו תהומות נבקעו</b>: משלי שם כ."],["6760","66","<b>רבות עשית . . אין ערוך אליך</b>: תהלים מ, ו [בדילוג]. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370148\" data-slug=\"torah-or\" data-id=\"3901370148\">תו\"א מקץ לא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381289\" data-slug=\"likkutei-torah\" data-id=\"4001381289\">לקו\"ת שה\"ש מ, סע\"ב</a> ואילך."],["6761","67","<b>כמ\"ש בס\"י בל\"ב נתיבות</b>: פ\"א, מ\"א."]]],[2001910584,"ומספר ל\"ב הם ך\"ב אותיות וע\"מ<sup data-n=\"6762\">68</sup>, ומחשבותיך הוא הארת החכ' שמאיר במדות דעיקר התהוות העולמות הי' ממדות וכמ\"ש ששת ימים עשה<sup data-n=\"6763\">69</sup> בששת אכ\"כ<sup data-n=\"6764\">70</sup> אלא ששת דכל יומא ויומא עביד עבידתא<sup data-n=\"6765\">71</sup> אך הרי ה' בחכ' יסד ארץ היינו הארת החכ' שמאיר במדות, וזהו שת\"י בראשית בחוכמתא<sup data-n=\"6766\">72</sup>, וזהו מחשבותיך דפעולת המח' הוא שיבא השכל לידי גילוי במדות, וזהו רבות עשית דרבוי הנבראים שנעשו הם מבחי' נפלאותיך ומחשבותיך.\n<b>וכ\"ז</b> אלינו אבל לגבי א\"ס אין ערוך אליך שאינו תופס מקום כלל, וצריכים להמשיך שיאמר הע\"מ וכמ\"ש את ה' האמרת היום<sup data-n=\"6767\">73</sup> שיאמר הע\"מ, דהנה כתי' לעולם ה' דברך נצב בשמים<sup data-n=\"6768\">74</sup> דדבר ה' עומד תמיד<sup data-n=\"6769\">75</sup> בשמים להחיותו ולקיימו ואם הי' מסתלק כרגע הי' נעשה אין ואפס, וכן כל הנבראים, דההתהוות הוא מיוחס בחיק הבורא דוקא דאלמלי מתכנשין כל באי עולם לא הי' יכולים לברוא אפי' כנף יתוש א'<sup data-n=\"6770\">76</sup>, דמעשה אדם הוא יש מיש<sup data-n=\"6771\">77</sup> לכן אפשר להתקיים בלא האומן, אבל ההתהוות היא בחיק הבורא יש מאין ולכן אלמלי מתכנשין כו', לכן צריך הדיבור להיות תמיד בשמים להחיותו ולקיימו וזהו ע\"י תורה, ואף שהיו ך\"ו דור שהיו נזונין בחסדי' של הקב\"ה<sup data-n=\"6772\">78</sup>, זהו מצד בחי' כי חפץ חסד הוא<sup data-n=\"6773\">79</sup> דבתחילה כשעלה במח' לברא את העולם הוא מצד כי חפץ חסד טבע הטוב<sup data-n=\"6774\">80</sup> כו' אבל לאחר מ\"ת ההמשכה היא ע\"י תורה, ועה\"ד כולל כללות התורה דאנכי מקור רמ\"ח מ\"ע ולא יהי' לך מקור שס\"ה ל\"ת<sup data-n=\"6775\">81</sup>. ובפרט יותר יובן דבתורה יש רמ\"ח מ\"ע ושס\"ה מל\"ת<sup data-n=\"6776\">82</sup> וכמו\"כ באדם יש רמ\"ח אברים<sup data-n=\"6777\">83</sup> ושס\"ה גידים<sup data-n=\"6778\">84</sup>,",[["6762","68","<b>ומספר ל\"ב הם ך\"ב אותיות וע\"מ</b>: ראה מאו\"א מערכת ל\"ב נתיבות אות יט וביאיר נתיב שם. ראה גם אוה\"ת יתרו כרך ז ע' ב'תרפד."],["6763","69","<b>ששת ימים עשה</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, ריש ע\"ב. האזינו חצר, ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["6764","70","<b>אכ\"כ</b>: אין כתיב כאן."],["6765","71","<b>דכל יומא . . עבידתא</b>: ראה זהר ויגש רה, סע\"א. אמור שם. השמטות לזח\"א רסד, ב."],["6766","72","<b>שת\"י בראשית בחוכמתא</b>: ראה תרגום ירושלמי לבראשית א, א. סה\"מ תר\"ם ח\"ב ע' תקלג. וש\"נ."],["6767","73","<b>את ה' האמרת היום</b>: תבוא כו, יז."],["6768","74","<b>לעולם ה' דברך נצב בשמים</b>: תהלים קיט, פט."],["6769","75","<b>דדבר ה' עומד תמיד</b>: ראה שער היחוה\"א פ\"א."],["6770","76","<b>דאלמלי מתכנשין . . יתוש א'</b>: ראה ירושלמי סנהדרין ספ\"ז. ספרי ואתחנן ו, ה. ב\"ר פל\"ט, יד. וש\"נ. אוה\"ת בראשית כרך ו ע' 2040. המשך מים רבים תרל\"ו פכ\"ה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261455\" data-slug=\"likkutei-sichot\" data-id=\"1300261455\">לקו\"ש משפטים כרך כו ע' 366</a>."],["6771","77","<b>דמעשה אדם הוא יש מיש</b>: ראה שער היחוה\"א פ\"ב."],["6772","78","<b>ך\"ו דור . . של הקב\"ה</b>: פסחים קיח, א. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251010\" data-slug=\"likkutei-sichot\" data-id=\"1300251010\">לקו\"ש בראשית כרך כה ע' 10</a> הערה 6."],["6773","79","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["6774","80","<b>טבע הטוב</b>: ראה עמק המלך שער שעשועי המלך בתחילתו. שומר אמונים ויכוח שני סי\"ד. שער היחוה\"א פ\"ד ובמ\"מ הגהות והע\"ק לשם. ולהעיר משו\"ת חכם צבי סי\"ח."],["6775","81","<b>דאנכי . . מ\"ע ולא יהי' . . ל\"ת</b>: יתרו כ, ב. ג. ראה זח\"ב (תוספות) רעו, א. (יתרו) צא. א. של\"ה ר\"פ יתרו שטו, ב. תניא רפ\"כ."],["6776","82","<b>רמ\"ח מ\"ע ושס\"ה מל\"ת</b>: מכות כג, סע\"ב."],["6777","83","<b>רמ\"ח אברים</b>: אהלות פ\"א, מ\"ח."],["6778","84","<b>ושס\"ה גידים</b>: ראה תרגום יוב\"ע בראשית א, כז. זהר וישלח קע, ב. ע\"ח שער פנו\"ח ש\"מ, דרוש יב: אותן הגידין שזכרו רז\"ל אינן אותן הלבנים. עשרה מאמרות מאמר חיקור דין ח\"א, פי\"א ובכנפי יונה ח\"א, פע\"א בשם הראב\"ע בס' העצמים שס\"ה גידין כפולין. סה\"מ תרכ\"ח ע' קכט ואילך בשם המד\"ר."]]],[2001910585,"ומבשרי אחזה<sup data-n=\"6779\">85</sup> שהם נכללים בעשר, הראש כולל ג' מוחין חב\"ד וגולגלתא דחפיא על מוחא<sup data-n=\"6780\">86</sup>, והגוף כולל חג\"ת חסד דרועא<sup data-n=\"6781\">87</sup> ימינא גבו' דרועא שמאלא תפארת גופא, נצח והוד תרין שוקין יסוד סיומא דגופא אות ברית קודש, וכמו\"כ בתורה עה\"ד כוללים כל התורה. ועוד בפרט יותר י\"ל דבעשרת הדברות יש תרי\"ג אותיות וכל אות מרמז על מצוה, וז' או' הנוספות מרמזים על ז' מצות<sup data-n=\"6783\">89</sup> דרבנן<sup data-n=\"6782\">88</sup>, וזהו שעה\"ד הם קיום העולם. ואף שהמאמרות הם ג\"כ עשר, ואמרז\"ל בעשרה דברים ברא כו', י\"ל דע\"מ וע\"ד<sup data-n=\"6784\">90</sup> הם במל'. ועוי\"ל דע\"מ הם במל' וע\"ד הם עשרה מלכיות שמהם נבנה פרצוף מל' דמל' נאצל רק נקודה חדא<sup data-n=\"6785\">91</sup> ובנינה מהספי' שלמעלה ממנה ממל' שבחכ' נעשה חכ' שבמל'<sup data-n=\"6786\">92</sup> וממל' שבחסד נעשה חסד שבמל' (ע' בק\"י ע' דב דבר<sup data-n=\"6787\">93</sup> הוא מל', ומספר עשרה מל' אפ\"ל מל' דגולגלתא דחפי' על מוחא כו' וצ\"ע). ועוי\"ל דע\"ד הם ע\"ס דז\"א ונכלל בזה גם חב\"ד דז\"א וע\"מ<sup data-n=\"6788\">94</sup> הם ע\"ס דחכ' דה' בחכ'.\n<b>ובד\"כ</b> (קיום העולם) הם (על) ג' דברים וכמארז\"ל על שלשה דברים העולם עומד על תורה ועל עבודה ועל גמ\"ח<sup data-n=\"6789\">95</sup>, עבודה הו\"ע הקרבנות<sup data-n=\"6790\">96</sup> קו השמאל העלאה מלמטלמ\"ע<sup data-n=\"6791\">97</sup> וגמ\"ח המשכה מלמעלמ\"ט<sup data-n=\"6792\">98</sup>, ותורה הוא קו האמצעי. והנה שחיטת קדה\"ק צ\"ל בצפון<sup data-n=\"6793\">99</sup> וכמ\"ש ושחט אותו על ירך המזבח צפונה לפני ה'<sup data-n=\"6794\">100</sup>, וכתי' הר ציון ירכתי צפון<sup data-n=\"6795\">101</sup> וכי בצפון הי' הלא בדרום מכאן דשחיטת",[["6779","85","<b>ומבשרי אחזה</b>: איוב יט, כו."],["6780","86","<b>וגולגלתא דחפיא על מוחא</b>: ראה זהר אד\"ר נשא קכח, ב."],["6781","87","<b>חסד דרועא . . קדש</b>: ראה ת\"ז בהקדמה יז, א."],["6783","89","<b>תרי\"ג . . ז' מצות דרבנן</b>: ראה גם לעיל הנחה ד\"ה קדש ישראל לה' ובהערות 131 ואילך."],["6782","88","<b>דבעשרת הדברות יש תרי\"ג אותיות . . דרבנן</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן פ\"ב על יד הערה 85 בשם המד\"ר. וש\"נ."],["6784","90","<b>וע\"ד</b>: ועשרה דברים."],["6785","91","<b>דמל' נאצל רק נקודה חדא</b>: ראה גם לעיל הנחה ד\"ה ועבדתם את ה\"א ובהערה 90."],["6786","92","<b>ממל' שבחכ' . . חכ' שבמל'</b>: ראה ע\"ח שער מיעוט הירח של\"ו, פ\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תשצה. שעה\"י קמא, ב ובהערה 41. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550485\" data-slug=\"torat-chaim\" data-id=\"2300550485\">תו\"ח יתרו ח\"ב רסח, ג</a>. סה\"מ תרל\"ח ע' ח ובהערה 71."],["6787","93","<b>בק\"י ע' דב דבר</b>: בקהלת יעקב ערך דב אות דבר."],["6788","94","<b>וע\"מ</b>: אוצ\"ל ועשרת הדברות."],["6789","95","<b>על שלשה דברים . . גמ\"ח</b>: ראה אבות פ\"א, מ\"ב."],["6790","96","<b>עבודה הו\"ע הקרבנות</b>: ראה מפרשים לאבות שם. סה\"מ תרל\"ח ע' לד הערה 79."],["6791","97","<b>הקרבנות . . העלאה מלמטלמ\"ע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310039\" data-slug=\"tanya\" data-id=\"3401310039\">תניא פל\"ד</a>. אגה\"ת ספי\"ב. אגה\"ק סוס\"כ. סכ\"ח. סה\"מ תר\"ם ח\"א ע' יד. וש\"נ. לקמן הנחה ד\"ה כתר יתנו לך על יד הערה 77."],["6792","98","<b>וגמ\"ח המשכה מלמעלמ\"ט</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670436\" data-slug=\"torat-chaim\" data-id=\"2300670436\">תו\"ח בראשית כו, ג</a>."],["6793","99","<b>שחיטת קדה\"ק צ\"ל בצפון</b>: זבחים פ\"ה, מ\"א-ה. ראה סה\"מ תרכ\"ז ע' רמט ואילך. וש\"נ. וראה גם ש\"א ט, ב ואילך ובהערה 39. סה\"מ תרל\"א ח\"א ע' קי. וש\"נ."],["6794","100","<b>ושחט אותו . . לפני ה'</b>: ויקרא א, יא."],["6795","101","<b>הר ציון ירכתי צפון</b>: תהלים מח, ג. ראה מדרש תהלים שם. ילקוט שמעוני שם (רמז תשנה). פסיקתא רבתי פ' תקעו שופר פמ\"ב [ובנ\"א פמ\"א], ב."]]]]});
